import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст мучениці Людмилі, княгині Чеській","e":"Akathist to the Martyr Ludmila, Princess of Bohemia","secs":[{"h":"Кондак 1","ps":["Ізбра́нная Бо́гом от іновернаго язи́чеськаго ро́да чешськаго, призва́нная в язи́к свят, служи́тельнице но́вая благода́ті, свята́я всехва́льная му́ченице Христо́ва Людмило, во страда́нії твоє́м му́ченичеський віне́ць нетлі́нний прия́вшая от руки́ Вседержи́теля і со А́нгели ни́ні предстоя́щая Єго́ Престо́лу, пі́сньми восхваля́єм тя любо́вію, уго́днице Христо́ва, і мо́лим ті ся: моли́твами твої́ми от ві́чних мук, бід і скорбе́й свобожда́й ни, зову́щия:","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгелов сожи́тельниця і челові́ков засту́пниця воі́стину яви́лася єси́, му́ченице Людмило достохва́льная, благоволе́нієм всіх Творця́, Христа́ Бо́га, Єго́же возлюби́ла єси́ і за Него́же пострада́ла єси́ да́же до сме́рти во іспові́данії непоколеби́мім; ті́мже прийми́ от нас сія́ хвале́нія:","Ра́дуйся, ско́рби мно́гія за і́м'я Госпо́днє прия́вшая;","ра́дуйся, вінце́м ісповедничеським от Бо́га укра́шенная.","Ра́дуйся, му́чеников совсельнице;","ра́дуйся, ві́ри христия́нськия небоя́зненная пропові́днице.","Ра́дуйся, я́ко тлі́нноє бога́тство своє́ раздавала єси́ ни́щим;","ра́дуйся, за не́же нетлі́нноє обрі́тшая на Небесі́.","Ра́дуйся, ду́шу свою́ Христа́ ра́ди погубившая, во є́же спасти́ ю;","ра́дуйся, а́ки світи́ло, во тьмі нече́стія пресла́вно возсія́вшая.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дя Христо́с Госпо́дь ду́шу твою́, ко прия́тію сі́мене Сло́ва Бо́жия чистото́ю і ми́лостинею предуготовленную, сві́том позна́нія Своєго́ просвіти́ ю, блаже́нная Людмило, і спаса́ємих ча́сти сотвори́ тя о́бщницю в Небе́снім Ца́рствії, іді́же со А́нгели поє́ши Пресвяті́й Тро́йце піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́нний дарова́ся тебе́, свята́я му́ченице Людмило, і́мже я́сно проразумела єси́ тщету́ душепа́губную злові́рія неві́стки твоєя́, хотя́щия тя погуби́ти. Ти же, ві́дящи сіє́, удали́лася єси́ во град Тетин, укри́тися спасе́нія ра́ди душі́ твоєя́, Христа́ же взиска́ти потща́лася єси́ вседу́шні. Ті́мже взива́єм ті:","Ра́дуйся, блаже́нная последовательнице Христо́ва;","ра́дуйся, любительнице за́повідей Єго́ преіскренняя.","Ра́дуйся, всемогу́щую си́лу благода́ті Христо́ви позна́вшая;","ра́дуйся, лю́таго де́монськаго ра́бства ізбі́гшая.","Ра́дуйся, бога́тство земно́є ні во что́же вміни́вшая;","ра́дуйся, от ю́ности ідолослуже́ніє презревшая.","Ра́дуйся, рука́ми убо́гих сокро́вища твоя́ го́ре предпославшая;","ра́дуйся, ідолослужительния лю́ди к І́стинному Бо́гу призва́вшая.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́ла благода́ті Бо́жия осіни́ тя, блаже́нная Людмило, єгда́ прия́сте Свято́є Креще́ніє с супру́гом твої́м Боривоєм (Борживоєм), князе́м чешським, во І́м'я Отця́ і Си́на і Свята́го Ду́ха. Таяже си́ла Бо́жия осіни́ тя ко благоче́стію і научи́ тя сла́вити Єди́наго Бо́га і воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи неоску́дноє милосе́рдіє ко вся́кому челові́ку, но бо́ліє к присним, свята́я блаже́нная княги́не Людмило, в стра́сі Бо́жиєм воспитивающи ча́да твоя́, яви́лася єси́ до́брая прама́ти вну́ка твоєго́, свята́го кня́зя В'ячеслава, воспита́вши єго́ во благоче́стії; помози́ і нам, му́ченице Христо́ва, прейти́ сіє́ земно́є по́прище во благо́м ді́ланії, да велича́єм тя зва́нії си́ми:","Ра́дуйся, блаже́нная ма́ти Людмило, му́ченице Христо́ва;","ра́дуйся, поне́сшая вдовство́ твоє́ благоче́стно і пресла́вно.","Ра́дуйся, по сме́рті кня́зя, супру́га твоєго́, во́лі Бо́жієй предавшаяся;","ра́дуйся, я́ко і нам помо́щниця явля́єшися в ско́рбіх на́ших.","Ра́дуйся, в ну́ждах на́ших обраща́тися к Бо́гу нас науча́ющая;","ра́дуйся, вну́ка твоєго́, свята́го кня́зя В'ячеслава, в істинах ві́ри воспита́вшая.","Ра́дуйся, я́ко і той прия́т му́ченичеськую кончи́ну, я́коже і ти, прама́ти єго́;","ра́дуйся, я́ко вам за сіє́ угото́вано сокро́вище ві́чних благ.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́рею одержи́ма помишле́ній зло́бних, нечести́вая неві́стка твоя́ см'яте́ся зіло́, ви́дівши тя ві́рную рабу́ Христо́ву, во ві́рі і благоче́стії просвіща́ющую страну́ Чешськую, низлагающую і́дольськия хра́ми і созидающую христия́нськия, во є́же славосло́вити Трисвято́є І́м'я Бо́жиє і пі́ти хвале́бную піснь Тому́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавши от свята́го равноапо́стольнаго Мефо́дія, архієпи́скопа Мора́вськаго, сло́во о чистоті́, по́сте, моли́тві і о всіх доброді́теліх, христия́ном подоба́ющих, прия́ла єси́ в се́рдці своє́, і за сія́ доброді́телі возлюби́ тя Госпо́дь і даде́ ті крі́пость і си́лу. Ті́мже і нас научи́, блаже́нная Людмило, за́повіді Госпо́дні ісполня́ти і тебі́ велича́ти:","Ра́дуйся, усе́рдная слушательнице слове́с Боже́ственних;","ра́дуйся, ревностная ісполнительнице зако́на Христо́ва.","Ра́дуйся, ни́ву се́рдця твоєго́ очи́стившая от те́рнія душевре́дних страсте́й;","ра́дуйся, оросившая ю слеза́ми покая́нія.","Ра́дуйся, во вдовстві́ чистоту́ непоро́чно сохранившая;","ра́дуйся, воздержа́нієм, моли́твою і му́ченичеським по́двигом Бо́гу угоди́вшая.","Ра́дуйся, страда́нієм сочетавшаяся Христу́;","ра́дуйся, ізбавля́ющая от бід і скорбе́й ві́ру і любо́в к тебі́ іму́щих.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лася єси́, свята́я княги́не му́ченице Людмило, єгда́ боготка́нною оде́ждею свята́го Креще́нія обле́кшися і нетлі́нною пи́щею Пречи́стаго Ті́ла і Кро́ве Христо́ви духо́вно укрі́пльшися, приліпи́лася єси́ всім се́рдцем твої́м ко Єди́ному Ісу́су; ті́мже вся страна́ Чешськая, просвіще́нная тобо́ю, єди́ними усти́ поє́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши, свята́я блаже́нная княги́не Людмило, вся лю́ди землі́ Чешськия во тьмі ідолослуже́нія погруже́нния, усе́рдно потща́лася єси́ просвіти́ти тіх сві́том Христо́ви ві́ри, подвиза́ющися в созида́нії хра́мов Бо́жиїх і в укріпле́нії ві́ри правосла́вния в страні́ чешстей; ми же воспіва́єм і велича́єм тя та́ко:","Ра́дуйся, му́дрими глаго́ли поучавшая лю́ди оста́вити тьму язи́чеськаго нече́стія;","ра́дуйся, от Бо́га то́кмо, а не от челові́к, утіше́ніє в ско́рбіх іска́ти нас науча́ющая.","Ра́дуйся, вну́ка твоєго́ В'ячеслава научи́вшая покланя́тися Єди́ному і І́стинному Бо́гу;","ра́дуйся, я́ко тім сестра́ явля́єшися равноапо́стольній О́льзі, княги́не Росси́йстій.","Ра́дуйся, ум твой ви́ну го́ре імі́вшая;","ра́дуйся, се́рдце твоє́ жили́ще Свята́го Ду́ха соді́лавшая.","Ра́дуйся, Христу́ Бо́гу Человіколю́бцю всю себ'я́ преда́вшая;","ра́дуйся, пе́рвая от землі́ Чешськия к ли́ку святи́х причтенная.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 6","ps":["Пропові́дником духоно́сним, апо́столом, подража́вши, блаже́нная Людмило, сла́вная княги́не, твої́ми сле́зними моли́твами ороси́ла і облагоуха́ла єси́ вся гра́ди і ве́сі близлежащия гра́да Пра́ги, приводя́щи, єли́ко ті мо́щно, лю́ди к ві́рі Христо́вой і науча́ющи їх воспіва́ти Єди́ному, в Тро́йці сла́вимому Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["В гра́ді Праге і била́ єси́ ма́ти милосе́рдная возлю́бленним ча́дом Це́ркве Правосла́вния, досточу́дная уго́днице Христо́ва, блаже́нная Людмило, се́рдце бо твоє́ на проше́нія і ну́жди приходя́щих к тебі́ ми́лостиво откривала єси́. Прийми́ і нас, до́брая ма́ти, с любо́вію к тебі́ прибіга́ющих і вопію́щих си́це:","Ра́дуйся, я́ко сирота́м била́ єси́ ма́ти і вдови́цям пита́тельниця;","ра́дуйся, я́ко ни́щим била́ єси́ ми́лостивая пода́тельниця і оби́димих блага́я защи́тниця.","Ра́дуйся, со князе́м, супру́гом твої́м, во благоче́стії пожи́вшая;","ра́дуйся, ча́да твоя́ в стра́сі Бо́жиєм воспита́вшая.","Ра́дуйся, я́ко блага́я о́трасль твоя́, святи́й князь В'ячесла́в, восприя́т му́ченичеськую кончи́ну;","ра́дуйся, я́ко і той с прама́терію своє́ю всели́ся в ца́рствіє Небе́сноє.","Ра́дуйся, за всіх христия́н пред Престо́лом Бо́жиїм ві́рная моли́твеннице;","ра́дуйся, іщущим путі́ ко спасе́нію наста́внице благода́тная.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 7","ps":["Коль мно́гими би́сери і ка́менієм драгоці́нним укра́шен єсть віне́ць, па́че со́лнця сія́яй, єго́же дарова́ ті Госпо́дь, свята́я блаже́нная княги́не Людмило, і́бо по́двигом до́брим во іспові́данії ві́ри подвиза́лася єси́ і о́браз свята́го житія́ нам яви́ла єси́; сего́ ра́ди прибіга́єм под кров твой, і́щуще спасе́нія, і благода́рно о тебі́ вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє ізобрі́те безчелові́чіє злочести́вая неві́стка твоя́ Драгомира, бегущей тебі́ во град Тетин, укри́тися хотя́щей от о́ния, свята́я благові́рная Людмило. Та бо, науче́нная сатанинською си́лою, погуби́ти ду́шу твою́ возжела́вши позорною сме́ртію, посла́ вслід ті двух злочести́вих боляр, преда́ти тя на лю́тая страда́нія, а́ки а́гницю Христо́ву, за́висти ра́ди. Ті́ї же собра́ша мно́жество нечести́ваго наро́да, взломаша две́рі дворця княжеськаго і позорней сме́рті удавле́нієм преда́ша непоро́чноє ті́ло твоє́. Ми же, воспомина́юще стра́шную смерть твою́, вопіє́м ті сицева́я:","Ра́дуйся, блаже́нная Людмило, от злих боляр ве́рвієм удавленная по ви́ї твоє́й;","ра́дуйся, такови́м о́бразом угоди́вшая Бо́гу, пострада́вшая му́ченичеськи.","Ра́дуйся, Го́споду ду́шу преда́вшая в суббо́ту, во єди́ном часі́ нощі́;","ра́дуйся, імі́вшая от рожде́нія твоєго́ шестьдеся́т і єди́но лі́то, Го́сподем к муче́нію угото́ванная.","Ра́дуйся, я́ко тобо́ю ди́вен Бог во святи́х Свої́х явля́ється;","ра́дуйся, я́ко мо́щі твоя́ просла́ви Госпо́дь нетлі́нієм благода́тно.","Ра́дуйся, градо́в чешських і словацьких похвало́ і утвержде́ніє;","ра́дуйся, всім носящим і́м'я твоє́ ско́рая помо́щнице і моли́твеннице.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 8","ps":["Не мо́жеть укри́тися град, верху́ гори́ стоя́й, та́ко, свята́я му́ченице Людмило, по кончи́ні твоє́й просла́ви Госпо́дь мо́щі твоя́ і мі́сто погребе́нія твоєго́, є́же под градською стіно́ю гра́да Тетина. Ми же тя, уго́дницю Бо́жию, про́сим: бу́ди нам хода́тайця ко Го́споду о проще́нії гріхо́в на́ших, да і ми, вку́пі с тобо́ю, Вели́кому і Чу́дному Бо́гу воспої́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся била́ єси́ об'ята неізрече́нною ра́достію, блаже́нная ма́ти Людмило, зря́щи креща́ємия лю́ди твоя́, повелі́нієм А́нгелов, і во умиле́нії воздала́ єси́ хвалу́ Спаси́телю Бо́гу, усе́рдно моливши Єго́, да при́зрить на обратившіяся лю́ди Своя́, да утверди́ть їх во ві́рі і благоче́стії і да просла́вить І́м'я Своє́ в страні́ чешстей. Ми же, воспомина́юще у́бо прерадостноє соби́тіє сіє́, прино́сим ті благода́рственния і похва́льния пі́сні:","Ра́дуйся, неоскудеваяй істо́чниче ми́лостей к наро́ду сему́;","ра́дуйся, духо́вная на́ша ма́ти, іспросившая у Бо́га просвіще́ніє пра́отцем на́шим.","Ра́дуйся, явле́нієм на тебі́ си́ли Бо́жия христия́ни возра́довавшая;","ра́дуйся, і́менем Всеси́льнаго Го́спода вся і́доли в страні́ Чешстей сокруши́вшая.","Ра́дуйся, му́ченице Христо́ва предо́брая;","ра́дуйся, моли́твеннице пред Бо́гом чу́дная.","Ра́дуйся, я́ко де́монов коварствіє упраздни́ся по моли́твам твої́м;","ра́дуйся, побі́ди віне́ць от руки́ Христа́ Жизнода́вця приє́мшая.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 9","ps":["Во вся конці́ землі́ Чешськия і за єя́ преді́ли просла́вися великоіменитоє і́м'я твоє́, преблагостная му́ченице ма́ти Людмило! Імі́ла бо єси́ ду́ха прему́дрости, я́ко му́дрими словеси́ безу́мних я́ві обуяла єси́, і ду́ха стра́ха Бо́жия, я́ко дія́ньми богоуго́дними ду́шу очи́стила єси́. Ті́мже, предста́вши Престо́лу Ви́шняго с со́нмом А́нгелов, ку́пно воспіва́єши Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не мо́гуть досто́йно ізобрази́ти вели́чіє благодія́ній твої́х, свята́я му́ченице Людмило, страні́ Чешстей і іни́м страна́м ідолопоклонства, іді́же водворила єси́ Боже́ственную ві́ру, ізбавля́ющи лю́ди от мра́ка язи́чеськаго і ві́чния поги́белі, откривающи їм путь ко спасе́нію. Сего́ ра́ди со благодаре́нієм благоче́стно поє́м ті:","Ра́дуйся, к сві́ту Правосла́вія ду́шу свою́ обрати́вшая;","ра́дуйся, мно́гія в духо́внім разумі́ просвіти́вшая.","Ра́дуйся, я́ко се́рдце твоє́ на проше́нія і ну́жди приходя́щих к тебі́ откривала єси́;","ра́дуйся, я́ко стра́нники і нищія пита́ла єси́.","Ра́дуйся, я́ко с ві́рою покланя́ємся честні́й іко́ні твоє́й;","ра́дуйся, я́ко, чту́ще па́м'ять твою́, восхваля́єм Го́спода.","Ра́дуйся, страда́нієм твої́м це́рков Христо́ву украси́вшая;","ра́дуйся, я́ко, взира́юще на страда́нія твоя́, ві́рнії прославля́ють І́м'я Ви́шняго.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасти́ся всім преі́скренні жела́ющи, мо́лишися за ни го́ре у Престо́ла Госпо́дня, ізбраннице Христо́ва, блаже́нная Людмило, і твої́ми моли́твами посо́бствуєши нам в стра́нствованії многотруднем земна́го житія́, є́же сподо́би ни в покая́нії і благоче́стії сконча́ти, я́ко облече́ тя Госпо́дь Боже́ственною си́лою, да обрати́ши вся неві́рния і научи́ши всіх со умиле́нієм серде́ць воспіва́ти Творцю́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ яви́лася єси́ страні́ твоє́й несокруши́мая, богому́драя Людмило, і необори́мая защи́тниця всім призива́ющим тя, зане́ та́ко благоволи́ о тебі́ Небесі́ і землі́ Творе́ць Госпо́дь, прославля́я уго́дницю Свою́, я́ко при гробни́ці твоє́й совершашася зна́менія і чудеса́, і ізи́де молва́ по всей страні́, і пону́ди кня́зя В'ячеслава торже́ственно пренести́ нетлі́нноє ті́ло твоє́ із гра́да Тетина во град Пра́гу, в сооруженную отце́м єго́ це́рков свята́го великому́ченика Гео́ргия. Ми же із глубини́ се́рдця со воздиха́нієм к Бо́гу глаго́лем ті пі́сні такови́я:","Ра́дуйся, моли́твенниця на́ша пред Бо́гом те́плая;","ра́дуйся, ізи́де бо по всей страні́ віща́ніє о чудесі́х твої́х.","Ра́дуйся, я́ко ні́кий сліпе́ць прозрі́, єгда́ прикосну́ся землі́ с могили твоєя́;","ра́дуйся, я́ко внук твой со сла́вою пренесе́ честно́є ті́ло твоє́.","Ра́дуйся, просла́вленная Бо́гом на Небесі́ і на землі́;","ра́дуйся, я́ко успе́ніє твоє́ торжеству́єть Це́рков Правосла́вная.","Ра́дуйся, явле́нієм моще́й твої́х младенчеськую Це́рков Чешськую возвесели́вшая;","ра́дуйся, му́ченице Христо́ва, і в землі́ Росси́йстій і Се́рбстій зіло́ почита́ємая.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прино́сим ті, уго́днице Бо́жия, і смире́нно мо́лим тя: моли́ о нас Єди́наго Человіколю́бця Бо́га, да не отврати́ть от нас Лиця́ Своєго́ і да́руєть нам по моли́тві твоє́й, свята́я му́ченице Людмило, проще́ніє мно́гих на́ших согріше́ній. Ми же, прославля́юще Бо́га о тебі́, вопіє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоно́сним Тро́їчеським сія́нієм го́ре осія́нная, свята́я му́ченице Людмило, озари́ се́рдця на́ша, тьмо́ю гріхо́вною покрові́нная, да єле́єм благи́х діл возже́гше угасшия світи́льники на́ша, сподо́бимся вни́ти в бра́чний черто́г Христо́в, іді́же ти весели́шися і сли́шиши сія́ от нас благохвале́нія:","Ра́дуйся, предстоя́щи ни́ні А́гнцю Бо́жию в ли́ці му́ченичестім;","ра́дуйся, я́ко і по преставле́нії твоє́м с на́ми пребива́єши.","Ра́дуйся, луно́, просвіще́нная от незаходи́маго Со́лнця Пра́вди;","ра́дуйся, путеводи́тельнице, пра́вую стезю́ к ві́чному спасе́нію нам показу́ющая.","Ра́дуйся, я́ко Христо́с по муче́нії твоє́м в черто́г Свой тя всели́;","ра́дуйся, я́ко, тебі́ послі́дующе, і ми ца́рство Небе́сноє обря́щем.","Ра́дуйся, особливая покрови́тельнице Чешськаго і Словацькаго наро́да правосла́внаго;","ра́дуйся, о нас, сро́дних ті лю́діх, при́сная пред Бо́гом моли́твеннице.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть Пресвята́го Ду́ха іспроси́ нам, уго́днице Христо́ва, свята́я му́ченице Людмило, от Всеще́драго Бо́га і Спа́са на́шего, вразумля́ющую і укріпля́ющую нас в ді́лі спасе́нія, да не бесплодно бу́деть в нас всі́янноє тобо́ю сі́м'я святи́я ві́ри, но да прозя́бнеть і плод достоєн сотвори́ть, і́мже препитаєм душі́ на́ша до бу́дущия жи́зні і со всі́ми святи́ми воспоє́м Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ преставле́ніє, ублажа́єм му́ченичеськую кончи́ну і почита́єм па́м'ять твою́, свята́я му́ченице ма́ти Людмило, многомо́щная засту́пнице землі́ Чешськия, Словацькия і Се́рбськия, бу́ди же і о россі́йських лю́діх блага́я моли́твенниця ко Го́споду, да вопіє́м ті:","Ра́дуйся, благода́тію Свята́го Ду́ха оді́янная;","ра́дуйся, предста́вшая Живу́щему во сві́ті непристу́пнім.","Ра́дуйся, вдови́цям пра́вило богоуго́днаго житія́;","ра́дуйся, те́плая хода́тайце, всім правосла́вним от Бо́га дарова́нная.","Ра́дуйся, соучастнице на Небесі́ жре́бія пра́ведников ві́ри Христо́ви;","ра́дуйся, со святи́ми Бо́жиїми Трисвяту́ю піснь воспіва́ти сподо́бльшаяся.","Ра́дуйся, от Го́спода всіх благ нам, молящимся ті, пода́тельнице;","ра́дуйся, я́ко всім правосла́вним христия́ном, тя моли́твенно призива́ющим, на по́мощ ско́ро притека́єши.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 13","ps":["О, свята́я му́ченице і ві́рная уго́днице Христо́ва Людмило! Ма́лоє сіє́ пісносло́віє от нас приє́млющи, моли́ ми́лостиваго Бо́га на́шего, да всели́ться і возблагоухаєть в сердця́х на́ших святи́ня Правосла́вния ві́ри, да умно́житься в житії́ на́шем єле́й діл благи́х, да не уга́снуть світи́льници на́ші в полунощний час срі́тенія Небе́снаго Жениха́ і да сподо́бимся ку́пно с тобо́ю ви́ну воспіва́ти Єму́ во ві́чнім ца́рствії: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов сожи́тельниця і челові́ков засту́пниця воі́стину яви́лася єси́, му́ченице Людмило достохва́льная, благоволе́нієм всіх Творця́, Христа́ Бо́га, Єго́же возлюби́ла єси́ і за Него́же пострада́ла єси́ да́же до сме́рти во іспові́данії непоколеби́мім; ті́мже прийми́ от нас сія́ хвале́нія:","Ра́дуйся, ско́рби мно́гія за і́м'я Госпо́днє прия́вшая;","ра́дуйся, вінце́м ісповедничеським от Бо́га укра́шенная.","Ра́дуйся, му́чеников совсельнице;","ра́дуйся, ві́ри христия́нськия небоя́зненная пропові́днице.","Ра́дуйся, я́ко тлі́нноє бога́тство своє́ раздавала єси́ ни́щим;","ра́дуйся, за не́же нетлі́нноє обрі́тшая на Небесі́.","Ра́дуйся, ду́шу свою́ Христа́ ра́ди погубившая, во є́же спасти́ ю;","ра́дуйся, а́ки світи́ло, во тьмі нече́стія пресла́вно возсія́вшая.","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нная Бо́гом от іновернаго язи́чеськаго ро́да чешськаго, призва́нная в язи́к свят, служи́тельнице но́вая благода́ті, свята́я всехва́льная му́ченице Христо́ва Людмило, во страда́нії твоє́м му́ченичеський віне́ць нетлі́нний прия́вшая от руки́ Вседержи́теля і со А́нгели ни́ні предстоя́щая Єго́ Престо́лу, пі́сньми восхваля́єм тя любо́вію, уго́днице Христо́ва, і мо́лим ті ся: моли́твами твої́ми от ві́чних мук, бід і скорбе́й свобожда́й ни, зову́щия:","Ра́дуйся, блаже́нная княги́не Людмило, свята́я му́ченице і моли́твеннице о душа́х на́ших."]},{"h":"Молитва","ps":["О, свята́я уго́днице Христо́ва, му́ченице княги́не Людмило, первоуго́днице Чешськия страни́ і сто́льнаго гра́да Пра́ги украше́ніє, те́плая о нас пред Бо́гом моли́твеннице! Се ми, многогрі́шнії, смире́нно припа́дающе, мо́лим тя: не попусти́ нам поги́бнути в ти́ні гріхо́в на́ших, но вознеси́ о нас моле́ніє ко Го́споду, да поми́луєть нас і да́руєть нам покая́ніє. О, преблага́я ма́ти Людмило! Не забу́ди посіща́ти чад твої́х, а́ще бо і преста́вилася єси́ от нас в Небе́сния оби́телі, вку́пі со внуко́м твої́м, святи́м му́чеником В'ячеславом. Ті́мже, свята́я прама́ти єго́, іспроси́ і нам, грі́шним, Бо́жиє благослове́ніє на ча́да на́ша і на всіх нас, да і ми, многогрі́шнії, возблагодари́м Го́спода за подая́ніє Єго́ благода́ті і ку́пно с тобо́ю да просла́вим Отця́ і Си́на і Свята́го Ду́ха і твоє́ вели́коє заступле́ніє о нас во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Оста́вльша тьму ідолослуже́нія / і с горя́чей любо́вію прия́в світ Правосла́вния ві́ри Христо́ви, / яви́ся ти, свята́я Людми́ло, я́ко звізда́ у́тренняя, / і сві́том свя́тости твоєя́ // і́стинний день Богопочита́нія в Че́стей землі́ нача́в."]},{"h":"Кондак, глас 2","ps":["Храм Твой всечестни́й, / я́ко цільбу́ душе́вную обрі́тше всі ві́рнії, / велегла́сно вопіє́м ті, / ді́во му́ченице Людми́ло, великоімени́тая: // Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпице Христо́ва Людмило, і чтим честно́є страда́ніє твоє́, є́же за Христа́ претерпі́ла єси́."]}],"notes":[]},{"u":"Акафіст преподобному Серафиму, Вирицькому чудотворцю","e":"Akathist to our Venerable Father Seraphim of Vyritsa, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, преподо́бне о́тче Серафи́ме, ві́ри правосла́вния світи́льниче і землі́ Россі́йськия благода́тний засту́пниче, чу́дний о́браз спасе́нія нам яви́вий, ді́ланієм сокрове́нним Ца́рство Небе́сноє стяжа́вий, к твоєму́ предста́тельству ни́ні притека́юще, пі́ніє хвале́бноє прино́сим ті, любо́вію зову́ще:","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Ікос 1","ps":["Ангелоподо́бную красоту́ душі́ імі́л єси́, преподо́бне о́тче, се́рдцем пламені́я ко Го́споду Сил, і Тому́ єди́ному служи́ти от ю́ности восхоті́л єси́, і послуша́ніє і́стинноє Творцю́ своєму́ яви́л єси́. Ті́мже промишле́нію Бо́жию о тебі́ див'я́щеся, с ві́рою зове́м ті:","Ра́дуйся, благочести́вих роди́телей о́троче досто́йний;","ра́дуйся, ізмла́да все́ю душе́ю Го́спода возлюби́вий.","Ра́дуйся, слу́жби церко́вния благогові́йний ревни́телю;","ра́дуйся, ми́ра духо́внаго умиле́нний созерца́телю.","Ра́дуйся, моли́тви чи́стия соверши́телю усе́рдний;","ра́дуйся, се́рдцем сокруше́нним всеці́ло к Бо́гу устремле́нний.","Ра́дуйся, схи́мнику ла́врському жела́ніє се́рдця своєго́ пове́давий;","ра́дуйся, от него́ во́лю Бо́жию о себі́ позна́вий.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя Го́спода очеси́ духо́вними і на ми́лость Єго́ упова́я, бра́ком зако́нним сочета́лся єси́, блаже́нне о́тче, чистоту́ душе́вную і тіле́сную усе́рдно соблюда́я. Вку́пі же с супру́жницею своє́ю возраста́л єси́ во вся́кой доброді́телі, непреста́нно поя́ Го́сподеві: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум наш недоуміва́єть, о́тче Серафи́ме, ка́ко словеси́ із'ясни́ти ві́ру і любо́в твою́ ко Го́споду, ніколи́же бо усумні́лся єси́ во бла́гости Отця́ Небе́снаго і всеці́лоє дове́ріє к Бо́гу в душі́ твоє́й пита́л єси́. Сего́ ра́ди глаго́лем ті сицева́я:","Ра́дуйся, о́бразе ві́ри непоколеби́мия;","ра́дуйся, іспо́лненний кро́тости духо́вния.","Ра́дуйся, боя́вийся Го́спода і храни́вий за́повіді Єго́;","ра́дуйся, на всяк день поуча́вийся в пра́вді Єго́.","Ра́дуйся, ду́шу твою́ в терпі́нії стяжа́вий;","ра́дуйся, Ца́рствія Бо́жия па́че всего́ іска́вий.","Ра́дуйся, цілому́дрія і воздержа́нія супру́жеськаго храни́телю;","ра́дуйся, ти́хаго нра́ва любому́дрий носи́телю.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укріпля́єм, по́прище мирсько́є с ді́ланієм вну́тренним му́дро сочета́л єси́, пра́ведне о́тче, і діла́ми милосе́рдія, Христа́ ра́ди твори́мими, благослове́ніє Бо́жиє сниска́л єси́. Покри́й у́бо і нас, обнаже́нних вся́каго ді́ла бла́га, любо́вію твоє́ю, да восхва́лим ми́лостиваго Бо́га: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я сострада́ніє, ми́лостиве о́тче, скорб'я́щих укріпля́л єси́, больни́х і си́рих утіша́л єси́, ті́мже і любо́в Христо́ву стяжа́л єси́. Прийми́ і от нас благода́рственную піснь сію́:","Ра́дуйся, ско́рий помо́щниче в біда́х су́щим;","ра́дуйся, ще́дрий пода́телю прося́щим.","Ра́дуйся, хра́мов і оби́телей благотвори́телю;","ра́дуйся, немощни́х і убо́гих попечи́телю.","Ра́дуйся, я́коже Самому́ Христу́, бли́жнему послужи́вий;","ра́дуйся, бога́тство тлі́нноє ні во что́же вміни́вий.","Ра́дуйся, земни́х пристра́стій свободи́вийся;","ра́дуйся, ві́рою і до́брими ді́ли утверди́вийся.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́ри богобо́рчеськия, в Россі́ї воздви́гнутия, не устраши́лся єси́, богоно́сне о́тче, но по́двиг іспові́дничества под'є́м, му́жеством вооружи́лся єси́ во є́же соверше́нний учени́ко Госпо́день нариця́тися, і Єму́ всеці́ло себі́ преда́в, ра́достно воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав о тя́жких страда́ніях, ві́рними за і́м'я Христо́во претерпева́ємих, со апо́столом вопроша́л єси́: кто ни разлучи́ть от любве́ Бо́жия? Ві́дуще же воі́стину, о́тче, я́ко лю́б'ящим Бо́га вся поспішеству́ють во благо́є, мо́лим тя: і нам многогрі́шним душеполе́зная от Го́спода іспроси́, да согла́сно поє́м ті:","Ра́дуйся, ві́ру правосла́вную му́жественно іспові́давий;","ра́дуйся, да́же до сме́рти за Христа́ постра́дати возжела́вий.","Ра́дуйся, імі́ніє твоє́ по словесі́ Госпо́дню разда́вий;","ра́дуйся, за Возлю́бленним тобо́ю і Возлю́бльшим тя послі́довавий.","Ра́дуйся, зла́то, в горни́лі іскуше́ній очище́нноє;","ра́дуйся, дре́во, при істо́чниціх вод живи́х насажде́нноє.","Ра́дуйся, ско́рби і іспита́нія в бога́тство ду́ха обрати́вий;","ра́дуйся, сокрове́нним по́двигом ко і́ночеству себі́ предугото́вавий.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 5","ps":["Богоуго́дні в честні́м бра́ці пожи́вше, восхоті́сте ви с супру́жницею в ли́ці а́нгельстім Спаси́телю послужи́ти, і та́ко во єди́н день восприя́ли єсте́ постриже́ніє мона́шеськоє. Єгда́ же восприя́л єси́ благода́ть свяще́нства в ла́врі Алекса́ндро-Не́встей, тогда́ я́ко звізду́ сві́тлую яви́ тя Госпо́дь лю́дем, во мра́ці ско́рби і отча́янія пребива́ющим, є́же сих укріпля́ти і сві́том і́стини їх озаря́ти, Бо́гу же пі́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша бра́тія, я́ко потща́вся вседу́шно Бо́гу благоугоди́ти, не вотще́ потруди́лся єси́, па́че же смире́нія глубину́, мир і ра́дость о Го́споді стяжа́л єси́. Ті́мже і ми, зря́ще от си́ли в си́лу духо́вноє восхожде́ніє твоє́, с благогові́нієм взива́єм ті:","Ра́дуйся, плоть твою́ со страстьми́ і похотьми́ распе́ншій;","ра́дуйся, скве́рну гріхо́вную покая́нієм оми́вий.","Ра́дуйся, я́ко благода́тную си́лу смире́нія позна́л єси́;","ра́дуйся, я́ко ді́ланієм за́повідей єва́нгельських ду́шу обнови́л єси́.","Ра́дуйся, і́м'я Ісу́са Сладча́йшаго непреста́нно призива́вий;","ра́дуйся, на землі́ блаже́нство бу́дущаго ві́ка вкуси́вий.","Ра́дуйся, Же́ртву безкро́вную со стра́хом і тре́петом приноси́вий;","ра́дуйся, сло́вом му́дрим всіх притека́ющих к тебі́ пита́вий.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 6","ps":["Соверше́нную любо́в я́ко віне́ць доброді́телей і дар Свята́го Ду́ха приє́мий, немощни́х не́мощі под'я́л єси́, духоно́сне о́тче, і ко спасе́нію мно́гі ду́ші упра́вил єси́. Ті́мже предста́тельством твої́м і ми грі́шнії неду́гов многоразли́чних ісцілі́вше, благода́рственно вопіє́м Го́споду: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в лиці́ твоє́м пра́вда Бо́жия, і отгна́ся пре́лесть бісо́вськая, єгда́ ла́вра і́га обновле́нчеськаго свободи́ся, і́ноці же всі возвесели́шася. Сего́ ра́ди про́сим тя, миротво́рче: раздо́ри і нестроє́нія житія́ на́шего утоли́, непра́вди разори́, да в єдиноду́шії глаго́лем ті:","Ра́дуйся, хра́мі нерукотворе́нний Христа́ Бо́га на́шего;","ра́дуйся, щедро́тами Ду́ха Свята́го благолі́пно украше́нний.","Ра́дуйся, се́рдце твоє́ вмісти́лище ми́ра соді́лавий;","ра́дуйся, фиміа́м моли́тви Го́споду непреста́нно возноси́вий.","Ра́дуйся, о заблу́ждших зіло́ душе́ю боле́зновавий;","ра́дуйся, всім спасти́ся і в ра́зум і́стини прийти́ жела́вий.","Ра́дуйся, го́рдость і зло́бу нечести́вих смире́нієм і кро́тостію побіди́вий;","ра́дуйся, по за́повіді Христо́ві люби́ти враги́ своя́ учи́вий.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь яви́ти в тебі́ но́воє духо́вноє світи́ло, даде́ тя бра́тії оби́телі во отця́ духо́внаго. Ті́мже вели́кую схи́му я́ко печа́ть соверше́нства от Бо́га приє́мши, душа́ твоя́ чи́стая огне́м пла́менния моли́тви за весь мир іспо́лнися, благоче́стію і братолю́бію всіх наставля́ющи і с тре́петом вопію́щи Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["В ди́вном проро́честві, преблаже́нне, указа́ Госпо́дь путеводи́теля і покрови́теля твоєго́, преподо́бнаго Серафи́ма Саро́вськаго, єго́же і́менем в схи́мі нарече́нний, воі́стину но́вий уті́шитель наро́ду на́шему бил єси́. Сему́ благоволе́нію Бо́жию чудя́щеся, вопіє́м ті:","Ра́дуйся, те́плий к Бо́гу о всіх моли́твенниче;","ра́дуйся, Преблагослове́нния Влади́чиці Держа́вния уго́дниче.","Ра́дуйся, А́нгелом прия́тний собесі́дниче;","ра́дуйся, духоно́сних оте́ць сподви́жниче.","Ра́дуйся, правосла́вних благода́тноє заступле́ніє;","ра́дуйся, блужда́ющих во тьмі безбо́жия світоза́рноє наставле́ніє.","Ра́дуйся, грі́шников с Бо́гом і́скреннєє примире́ніє;","ра́дуйся, істо́чниче ра́дости і умиле́нія.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нно єсть і неудобоприя́тельно су́єтному ми́ру сли́шати, ка́ко моли́твами твої́ми, чудотво́рче, бога́тство милосе́рдія Бо́жия ізлива́ється на всіх с ві́рою притека́ющих к твоєму́ небе́сному покрови́тельству. Ми же, сла́в'яще Тро́йцю Святу́ю, дарова́вшую ті благода́ть сію́, ра́достно восклиця́єм: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ себе́ на служе́ніє Бо́гу і лю́дем преда́л єси́, ди́вний о́тче, ча́дом свої́м запові́дав о Го́рнем всегда́ помишля́ти і моли́тву Ісу́сову усе́рдно твори́ти, є́юже вся́кий гріх в душі́ посіка́ється і дух челові́ч с Ду́хом Бо́жиїм соєдиня́ється. Под твоє́ у́бо пречу́дноє благослове́ніє прибіга́юще, с любо́вію велича́єм тя:","Ра́дуйся, Го́рняго Ієрусали́ма жи́телю;","ра́дуйся, неізрече́нния сла́ви Спаси́теля ми́ра зри́телю.","Ра́дуйся, моли́тви на́ша к стопа́м Вседержи́теля і Богоро́диці принося́й;","ра́дуйся, я́коже оте́ць чадолюби́вий прося́щим поле́зная подава́яй.","Ра́дуйся, ві́рний Це́ркве Христо́ви служи́телю;","ра́дуйся, неісці́льних болі́зней духо́вний врачева́телю.","Ра́дуйся, гряду́щих време́н чуде́сноє предзрі́ніє;","ра́дуйся, настоя́щих обстоя́ній ско́роє ізбавле́ніє.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 9","ps":["Вся Си́ли Небе́сния удиви́шася смире́нію і терпі́нію твоєму́, свя́тче, мучи́тельним тя неду́гом зря́ще пораже́ннаго, оба́че промисли́тельно от рук гони́телей із ла́ври восхище́ннаго. Лю́діє же ві́рнії, ви́дівше тя, чу́дно под кро́вом Богоро́диці во Ви́рицькой ві́си храни́маго, воспіва́ху Человіколю́бцю Го́споду: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє умолка́єть пред вели́чієм по́двиг твої́х, преподо́бне: ка́ко у́бо, ста́рець пло́тію не́мощен сий, мно́гія труди́ под'я́л єси́? Ті́мже, си́лі Бо́жієй в не́мощіх соверша́ємой див'я́щеся, взива́єм ті:","Ра́дуйся, дре́вніх пусти́нников іску́сний подража́телю;","ра́дуйся, по́стничеськаго житія́ ізря́дний люби́телю.","Ра́дуйся, моли́твенних бді́ній усе́рдний ревни́телю;","ра́дуйся, тіле́сних не́мощей чу́дний побіди́телю.","Ра́дуйся, і́стинним смире́нієм доброді́телі своя́ сокри́вий;","ра́дуйся, пла́чем плоди́ Бо́жия благода́ті умно́живий.","Ра́дуйся, єле́й ра́дости трезве́нієм сохрани́вий;","ра́дуйся, Христу́ Бо́гу житіє́м твої́м благоугоди́вий.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ Русь Святу́ю от наше́ствія іноплеме́нник Го́спода умоля́л єси́, боголю́бче ди́вний: Ісу́се Христе́, Си́не Бо́жий, поми́луй страну́ на́шу і мир Твой. Та́ко со умиле́нієм серде́чним к Бо́гу взива́я, подо́бні ста́рцю Саро́вському но́вий по́двиг моли́твеннаго стоя́нія на ка́мені под'я́л єси́. Ті́мже тя укріпи́вшаго Го́спода сла́вим, побі́дную піснь Єму́ пою́ще: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ бисть незри́мая моли́тва твоя́, уго́дниче Бо́жий, во́їнству і наро́ду на́шему в годи́ну іспита́ній тя́жких. Ра́зумом духо́вним смисл попу́щенних Бо́гом скорбе́й постига́я, обрати́тися ко Христу́ отступи́вшия лю́ди призива́л єси́. Ті́мже і нас от вся́кия ве́щі сопроти́вния соблюди́, вопію́щих ті такова́я:","Ра́дуйся, ча́шу страда́ній со оте́чеством земни́м до конця́ іспи́вий;","ра́дуйся, о поми́лованії Россі́ї Го́спода проси́вий.","Ра́дуйся, во́їнству христолюби́вому Бо́гом дарова́нноє поможе́ніє;","ра́дуйся, душ і тіле́с на́ших живи́тельноє ороше́ніє.","Ра́дуйся, му́ченичество безкро́вноє во́лею претерпі́вий;","ра́дуйся, не́мощі єстества́ челові́чеськаго презрі́вий.","Ра́дуйся, землі́ Россі́йськия моли́твенноє огражде́ніє;","ра́дуйся, от враг ви́димих і неви́димих досточу́дноє ізбавле́ніє.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прино́сим ті, преподо́бне о́тче Серафи́ме, ублажа́юще многотру́дноє земно́є житіє́ твоє́, ти же не преста́й моли́тися за ни ко Го́споду, да да́руєть нам гріхо́в оставле́ніє, страсте́й одолі́ніє, во вся́цій доброді́телі утвержде́ніє і ми́ра душе́внаго хране́ніє, і да сподо́бит нас недосто́йних вку́пі с тобо́ю во Ца́рствії Небе́снім благода́рственно воспіва́ти: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рнаго пропові́дника су́щим во тьмі безбо́жия зрим тя, всеблаже́нне о́тче, духо́вноє бо возрожде́ніє Россі́ї прови́діл єси́ і сооте́чественником тве́рдо ві́ри правосла́вния держа́тися завіща́л єси́. Ми же, словеси́ твої́ми просвіща́ємі, со умиле́нієм взива́єм ті:","Ра́дуйся, сла́ви Предві́чнаго Царя́ прича́стниче;","ра́дуйся, Боже́ственнаго Со́лнця луче́.","Ра́дуйся, милосе́рдія світи́ло, согріва́ющеє ду́ші;","ра́дуйся, наста́вниче, духо́вно пробужда́ющий уми́.","Ра́дуйся, світи́льниче, і́мже мно́зі челові́ци просвіща́ються;","ра́дуйся, моли́твенниче, і́мже ко́зні вра́жия разруша́ються.","Ра́дуйся, чистоти́ серде́чния храни́телю;","ра́дуйся, соверше́нства христия́нськаго учи́телю.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 12","ps":["Блаже́нную кончи́ну твою́, богому́дре о́тче, моле́нієм ака́фистним Богома́тері предвари́л єси́: Та бо я́вственні посети́вши тя, отше́ствіє твоє́ бли́зькоє на Не́бо десни́цею указа́ ті. Ки́їми похвала́ми досто́йно ублажи́м тя, ізбра́нниче Цари́ці Небе́сния, ни́ні со ли́ки а́нгельськими пою́ща: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́внаго во святи́х Свої́х Бо́га, ві́руєм, я́ко мно́го мо́жеть моли́тва пра́веднаго ко благосе́рдію Влади́ки, і сего́ ра́ди про́сим тя, преподо́бне о́тче, бу́ди о нас хода́тай те́плий у Престо́ла Пресвяти́я Тро́йці, вопію́щих ті си́це:","Ра́дуйся, пла́менним Серафи́мом тезоимени́тий;","ра́дуйся, ста́рчества восприє́мниче духоно́сний.","Ра́дуйся, ни́ви Христо́ви неуста́нний ді́лателю;","ра́дуйся, ми́ра Бо́жия усе́рдний насади́телю.","Ра́дуйся, Правосла́вния Це́ркве но́воє украше́ніє;","ра́дуйся, ве́ліє к Бо́гу за Русь многострада́льную дерзнове́ніє.","Ра́дуйся, ро́да христия́нськаго благомо́щноє заступле́ніє;","ра́дуйся, почита́ющим тя хода́таю ві́чнаго спасе́нія.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 13","ps":["О пресла́вний і досточу́дний уго́дниче Бо́жий Серафи́ме, Ви́рицький чудотво́рче, прийми́ усе́рдноє сіє́ моле́ніє на́ше, с любо́вію тебі́ возноси́моє. Умоли́ Всеми́лостиваго Го́спода ізба́вити нас от вся́каго зла і напа́сти, да в ни́нішнем ві́ці благоче́стно поживе́м і блаже́нства жи́зні ві́чния моли́твами твої́ми сподо́бимся, о тебі́ благода́рственно Го́сподеві пою́ще: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Ангелоподо́бную красоту́ душі́ імі́л єси́, преподо́бне о́тче, се́рдцем пламені́я ко Го́споду Сил, і Тому́ єди́ному служи́ти от ю́ности восхоті́л єси́, і послуша́ніє і́стинноє Творцю́ своєму́ яви́л єси́. Ті́мже промишле́нію Бо́жию о тебі́ див'я́щеся, с ві́рою зове́м ті:","Ра́дуйся, благочести́вих роди́телей о́троче досто́йний;","ра́дуйся, ізмла́да все́ю душе́ю Го́спода возлюби́вий.","Ра́дуйся, слу́жби церко́вния благогові́йний ревни́телю;","ра́дуйся, ми́ра духо́внаго умиле́нний созерца́телю.","Ра́дуйся, моли́тви чи́стия соверши́телю усе́рдний;","ра́дуйся, се́рдцем сокруше́нним всеці́ло к Бо́гу устремле́нний.","Ра́дуйся, схи́мнику ла́врському жела́ніє се́рдця своєго́ пове́давий;","ра́дуйся, от него́ во́лю Бо́жию о себі́ позна́вий.","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, преподо́бне о́тче Серафи́ме, ві́ри правосла́вния світи́льниче і землі́ Россі́йськия благода́тний засту́пниче, чу́дний о́браз спасе́нія нам яви́вий, ді́ланієм сокрове́нним Ца́рство Небе́сноє стяжа́вий, к твоєму́ предста́тельству ни́ні притека́юще, пі́ніє хвале́бноє прино́сим ті, любо́вію зову́ще:","Ра́дуйся, преподо́бне о́тче Серафи́ме, Ви́рицький чудотво́рче."]},{"h":"Молитва","ps":["О богоблаже́нний і премилосе́рдий о́тче наш Серафи́ме! Ві́дуще тя і по сме́рті я́ко жи́ва су́ща, с ві́рою припа́даєм ті і вопіє́м: не забу́ди убо́гих твої́х до конця́, но ми́лостивно при́зри на ста́до твоє́ духо́вноє і упаси́ є, до́брий па́стирю, благоприя́тними твої́ми к Бо́гу моли́твами. Іспроси́ нам от Го́спода вре́м'я на покая́ніє і гріхо́вния жи́зні ісправле́ніє, ві́си бо вся не́мощі на́ша душе́вния: не і́мами діл ві́ри і спасе́нія, не і́мами ре́вности ко і́стинному богоугожде́нію, плени́хомся умо́м в поги́бельних страстеіх, растле́хом сердца́ во гну́сних по́хотіх. Что у́бо ча́єм і на что наді́ємся, неключи́мії, разори́вше хра́мини душ на́ших? Єй, святи́й о́тче, простри́ моли́твенно ру́ці твої́ ко Го́споду і умоли́ Спаси́теля ро́да челові́чеськаго косну́тися благода́тію окамене́нних серде́ць на́ших, оми́ти нас слеза́ми покая́нія, возста́вити во ві́рі, укріпи́ти во благоче́стії і вся поле́зная ко спасе́нію дарова́ти. Не посрами́ упова́нія на́шего, є́же по Бо́зі і Богоро́дице на тя возлага́єм, но бу́ди нам ско́рий помо́щник, уті́шитель в ско́рбіх і покрови́тель во обстоя́нії, да сподо́бимся моли́твами твої́ми наслі́довати Ца́рствіє Небе́сноє, іді́же всі святі́ї непреста́нно сла́в'ять і воспіва́ють пречестно́є і великолі́поє і́м'я Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко пресві́тлая звізда́ Россі́йськия землі́, / возсія́л єси́ во ві́си Ви́рицтей, / преподо́бне Серафи́ме, / і благода́тію Свята́го Ду́ха наставля́єм, / сві́том чуде́с твої́х страну́ на́шу озари́л єси́. / Ті́мже ко гро́бу твоєму́ притека́юще, уми́льно глаго́лем: // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["Я́ко вели́каго моли́твенника за зе́млю на́шу / і уті́шителя те́плаго притека́ющих к тебі́, / ублажа́єм тя, втори́й ру́ський о́тче Серафи́ме, / вся бо я́же в ми́рі кра́сная оста́вил єси́, / всім се́рдцем устреми́лся єси́ к черто́гам сладча́йшаго Христа́ / і в годи́ну лю́тих гоне́ній о́браз кро́тости і смире́нія всім бил єси́: / не преста́й і ни́ні моли́тися за ни, / да в терпі́нії обря́щем путь покая́нія // і с тобо́ю ви́ну сла́вим Пресвяту́ю Тро́йцю."]},{"h":"Кондак, глас 5","ps":["Дре́внім отце́м подража́я, / по́двигом до́брим подвиза́лся єси́ / і, благода́ть Ду́ха Свята́го оби́льно стяжа́в, / Саро́вському уго́днику уподо́бился єси́ / і мно́гим путь спасе́нія яви́л єси́. / Сего́ ра́ди зове́м ті: / ра́дуйся, преподо́бне Серафи́ме, / Алекса́ндро-Не́вския ла́ври ди́вний подви́жниче // і Ви́рицькия ві́си сла́вная похвало́."]},{"h":"Інший кондак, глас 5","ps":["Подража́я богоно́сному уго́днику Саро́вському, / Ду́ха Свята́го благода́ть оби́льно стяжа́л єси́: / Алекса́ндро-Не́вския ла́ври кри́не благоуха́нний, / Ви́рицькия ві́си похвало́, / сего́ ра́ди і ми тебі́ зове́м: / ра́дуйся, преподо́бне Серафи́ме, // ми́лостивий наш предста́телю пред Го́сподем."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче Серафи́ме, і чтим святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче а́нгелов."]}],"notes":[]},{"u":"Акафіст святому апостолу Симону Зилоту, Кананіту","e":"Akathist to the Holy Apostle Simon the Zealot, the Canaanite","secs":[{"h":"Кондак 1","ps":["Ізбра́нний апо́столе Христо́в і благові́стниче, мре́жею про́повіді твоєя́ улови́вий во спасе́ніє мно́гія душі́ челові́чеськія і ко Христу́ приведи́й ідолослуже́нієм помраче́нния лю́ди, Си́моне блаже́нне, в пі́сніх восхваля́єм тя с любо́вію і мо́лим ті ся приле́жно: я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся Єму́ ви́ну за ни грі́шния і моли́твами твої́ми от вся́ких нас бід свобожда́й, да зове́м ті:","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Влади́ка, Христо́с Бог, спасти́ хотя́ па́дшеє челові́чество, в плоть на́шу облече́ся і с челові́ки поживе́, в Ка́ну же Галиле́йськую на брак в дом твой при́йде, Си́моне прехва́льне, вку́пі с Пречи́стою Своє́ю Ма́терію, Ді́вою Богоро́дицею, Єя́же умоле́нієм Ма́тернім нача́ток чуде́с Свої́х в до́мі твоє́м яви́, во́ду во вино́ на бра́ці твоє́м чуде́сно претвори́в і сим показа́в Божества́ Своєго́ си́лу. Ті́мже тебі́, си́це облагодатствованному посіще́нієм і благоволе́нієм Богочелові́ка, я́ко Богови́дцю і ученику́ Єго́ ізбра́нному, со умиле́нієм си́це вопіє́м:","Ра́дуйся, женише́ прекра́сний, от бра́ка земна́го на брак А́гнчий чуде́сно призва́нний;","Ра́дуйся, на небесі́ і на землі́ просла́вленний.","Ра́дуйся, вопло́щшемуся Бо́гу Сло́ву ві́рно послужи́вий;","Ра́дуйся, в пропові́данії Єва́нгелія пра́вди ре́вность ве́лію яви́вий.","Ра́дуйся, Пресла́дкаго Го́спода Ісу́са всім се́рдцем твої́м возлюби́вий;","Ра́дуйся, обру́чницю земну́ю оста́вивий і во слід Єго́ потекий.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дів чудеса́ Христо́ви, Си́моне пресла́вне, ві́рно послі́довал єси́ во пло́ті я́вльшемуся Бо́гу, от Него́же возлю́блен бил єси́ і к ли́ку ізбра́нних двана́десяти апо́стол Єго́ сопричтен бил єси́, я́коже ревни́тель сла́ви Єго́, найменова́ніє но́воє Зило́та, сі єсть ревни́теля, получи́л єси́. Сію́ ре́вность о сла́ві Бо́жієй іспроси́ і нам, учениче́ Спасов, да ку́пно с тобо́ю сподо́бимся пі́ти Христу́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний тебі́ сви́ше даде́ся, Си́моне богому́дре, ті́мже внима́я Боже́ственним словесе́м Христа́ Бо́га, слагал єси́ я в се́рдці твоє́, і, я́ко земля́ до́брая, плод сторичен прине́сл єси́ Єму́ уче́нія Єва́нгельськаго благода́ть, є́юже озари́л єси́ во спасе́ніє ми́ра конці́ і, я́ко богопропові́дник душеспасительний, сли́шиши от нас пі́сні такови́я:","Ра́дуйся, і́го Христо́во, благо́є і ле́гкоє, на ра́мо твоє́ восприє́мий;","Ра́дуйся, приме́ром твої́м святи́м вся ни к послі́дованію Христо́ву привлека́яй.","Ра́дуйся, ре́вности тезоимени́тий ревни́телю о сла́ві Бо́жієй;","Ра́дуйся, теплі́йший люби́телю Го́спода Ісу́са.","Ра́дуйся, ди́вний наста́вниче к Нему́ і́щущих спасе́нія;","Ра́дуйся, немо́лчний благові́стниче Єва́нгельськаго душеспаси́тельнаго уче́нія.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́ла Бо́жия осіни́ тя, апо́столе Христо́в Си́моне, єгда́ во слід ходи́л єси́ Христа́ Го́спода, обходя́ с Ним Іуде́ю і Галиле́ю, внима́я уче́нію Єго́ Боже́ственному і созерца́я преве́лія Єго́ чудеса́. Ті́мже і Христо́с, я́ко ві́рному Своєму́ послі́дователю і ученику́, дарова́ ті власть і си́лу неду́ги ісціля́ти, болі́зні врачева́ти і ду́хи нечи́стия прогоня́ти, да всі сла́в'ять си́лу Єго́, в тебі́ явле́нную, і пою́ть Єму́ хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́л єси́ єди́но попече́ніє, Си́моне всеблаже́нне, є́же ві́рно служи́ти і благоугожда́ти Христу́ Бо́гу, во пло́ті я́вльшуся на спасе́ніє челові́чеськоє, Єго́же спу́тник і самови́дець сподо́бился єси́ би́ти і от уст Єго́ Боже́ственних почерпнул єси́ преве́лію уче́нія небе́снаго благода́ть, о не́йже див'я́щеся, си́це тебі́ глаго́лем:","Ра́дуйся, всера́достний нам пропові́дниче Єва́нгелія пра́вди;","Ра́дуйся, денни́це, возвісти́вшая нам со́лнце невече́рнєє.","Ра́дуйся, самови́дче і слуго́ воплоще́ннаго Бо́га;","Ра́дуйся, стра́нствія Влади́чня і безсме́ртния Єго́ трапе́зи соприча́стниче.","Ра́дуйся, ізбра́нний і ві́рний Христо́в учениче́;","Ра́дуйся, дру́же Єго́ при́сний, до конця́ дру́жество твоє́ к Нему́ сохрани́вий.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́ря я́рости іуде́йськия пригвозди́ ко Кресту́ Христа́ Бо́га, во́лею пострада́ти за вся лю́ди ізволившего, но не поколеба́ ві́ри і упова́нія твоєго́, Си́моне блаже́нне, я́ко Той єсть Спаси́тель ми́ра, дре́вле прорече́нний проро́ки во іскуше́ніє па́дшаго челові́чества. Ті́мже, я́ко Влади́ці і Бо́гу, ві́рно воспіва́л єси́ Єму́ хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав Боже́ственний глас Христа́ жизнода́вця, тридне́вно воскре́сшаго от ме́ртвих і две́рем затворе́нним вше́дшаго ко ученико́м Свої́м, і “Мир вам!” ре́кшаго, Си́моне богоно́сне, зіло́ возра́довался єси́ і Тому́, я́ко Бо́гу, благогові́йно поклони́лся єси́, всім же пото́м возвіща́л єси́ немо́лчно непрело́жную і́стину Єго́ воскресе́нія. О сем і ми хвале́бно тебі́ зове́м:","Ра́дуйся, мир Христо́в досто́йно приє́мий в непоро́чний сосу́д душі́ твоєя́;","Ра́дуйся, ми́ром тім ми́ра конці́ умиротвори́вий благода́тно.","Ра́дуйся, дре́внія вражди́ ідолослужительния потреби́телю;","Ра́дуйся, і́стини воскресе́нія Христо́ва очевидний і громогла́сний свиді́телю.","Ра́дуйся, две́рем затворе́нним ди́вно проше́дшаго Христа́ созерца́телю;","Ра́дуйся, пребоже́ственнаго і радостотворнаго гла́са Єго́ сли́шателю.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 5","ps":["Боготечноє на не́бо вознесе́ніє Христо́во ви́дів і Ду́ха Свята́го, от Него́ ниспосланнаго во о́гненних язи́ціх, соприча́стник бив, Си́моне прехва́льне, духоно́сець боже́ственний соді́лался єси́ і, облече́нний си́лою сви́ше, поте́кл єси́ на про́повідь Єва́нгельськую во Іуде́ю, Сирі́ю, Єги́пет, Мавритані́ю, Іспа́нію, Британію, Перси́ду, Іверію і Арме́нію, возвіща́я лю́дем, во мра́ці неві́рія би́вшим, світ Христа́ Бо́га спаси́тельний і ві́ру в Него́ пра́вую і всіх приводя́ зва́ти Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши тя, апо́столе Христо́в, Пречи́стая Богоро́диця, от да́льних стран на о́блаці приспевшаго ко пречестно́му Єя́ успе́нію, возра́довася ра́достію свято́ю і сподо́би тя Своєя́ бесі́ди і благослове́нія предсмертнаго; ти же о коли́кия ра́дости іспо́лнился єси́, созерца́я Си́на Єя́ і Бо́га, со святи́ми А́нгели к Ней прише́дшаго і святу́ю ду́шу Єя́ в ру́ці Свої́ приє́мшаго. Сію́ ра́дость твою́ і ми, благогові́йно воспомина́юще, от любве́ усе́рдния возглаша́єм ті сія́ всерадостния глаго́ли:","Ра́дуйся, небошественний учениче́ Спасов, на погребе́ніє Ма́тере Госпо́дні на о́блаці чуде́сно принесе́нний;","Ра́дуйся, Христа́, в ру́ці Свої́ ду́шу Ма́тере Своєя́ приє́мшаго, созерца́вий.","Ра́дуйся, погребе́нію Пречи́стия Богома́тере досто́йно послужи́вий;","Ра́дуйся, вознесе́нную с ті́лом го́ре Богоро́дицю уразумі́вий.","Ра́дуйся, погреба́льния пелени́ і пра́здний гроб Єя́ в Гефсима́нії ви́дівий;","Ра́дуйся, во виді́нії світоза́рнім со святи́ми А́нгели прише́дшую Влади́чицю ми́ра зрі́ти сподо́бивийся.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 6","ps":["Пропові́дник богоглаго́ливий яви́лся єси́, апо́столе Христо́в Си́моне, в страна́х ди́ких і лю́дем зверонравним возвіща́л єси́ Єва́нгеліє Христо́во, кро́тостію і незло́бієм твої́м препобіжда́я тіх лю́тость і із волко́в ди́віїх претворя́я їх в а́гнці Христо́ви, і́же і научи́шася тобо́ю пі́ти Трієди́ному Бо́гу а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, учениче́ Спасов, я́ко світи́льник лучеза́рний, в страна́х неві́рних і, я́ко боготечноє світи́ло, обте́кл єси́ восто́к і за́пад, возвіща́я лю́дем спаси́тельную ві́ру во Христа́ Ісу́са, І́же внуша́єть нам благохвали́ти тя, богопропові́дника божественного, похвала́ми си́ми:","Ра́дуйся, от восто́ка востеки́й і за́пад просвіти́вий сві́том Христо́вим;","Ра́дуйся, Африку і Іспа́нію огласи́вий уче́нієм Єва́нгельським.","Ра́дуйся, бритян суро́вость укроти́вий кро́тостію Ісу́совою;","Ра́дуйся, Арме́нію і Іверію приведи́й к позна́нію Си́на Бо́жия.","Ра́дуйся, пе́рсов і ми́дов убедивий ві́ровати во Христа́ Бо́га;","Ра́дуйся, неутомимо трудивийся во благові́стії Христо́ві.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хоті́ніє усе́рдноє імі́л єси́, апо́столе Христо́в, є́же му́ченичеськи пострада́ти за і́м'я Христо́во і кро́вію твоє́ю запечатлі́ти боже́ственную і́стину про́повіді твоєя́ Єва́нгельськия, є́же Госпо́дь устроя́я, приведе́ тя во Іве́рії от неві́рних Лазов на кресті́ расп'я́ту би́ти і му́ченичеськи сконча́тися. Такову́ю страда́льчеськую Христоподо́бную кончи́ну твою́ воспомина́юще, почита́єм болі́зні і труди́ твоя́ і поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго Но́я, нача́льника ковче́га душеспаси́тельнаго ві́ри Христо́ви во Іве́рії, позна́єм тя би́ти, Си́моне Богоглаго́ливе, і я́ко основа́теля і краєуго́льнаго ка́мня це́ркве І́верськия тя почита́єм, мі́сто же погребе́нія твоєго́ с любо́вію чтим, я́ко освяще́нноє кро́вію твоє́ю і моще́й твої́х почиванієм, от него́же да́ри ціле́бния істоча́єши ві́рним і привлека́єши зва́ти тебі́:","Ра́дуйся, Іве́рії храни́телю неотсту́пний;","Ра́дуйся, Пицюнди покрови́телю, Бо́гом да́нний.","Ра́дуйся, храм твой в пусти́ні чуде́сно сохрани́вий от коне́чнаго разруше́нія;","Ра́дуйся, гроб твой честни́й нам дарова́вий во утіше́ніє.","Ра́дуйся, мі́сто по́двигов твої́х і страда́ній обнови́вий оби́телію іночеською во і́м'я твоє́;","Ра́дуйся, от свята́го Афо́на подви́жники поста́ і моли́тви в ню преселивий преди́вно.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є соверши́в, апо́столе Спасов, пресели́лся єси́ от землі́ к оби́телем небе́сним, на землі́ же чуде́с луча́ми сія́єши і просвещавши душі́ ві́рних, і́же по Бо́зі моли́твенно к тебі́ прибіга́ють і почита́ють святу́ю твою́ па́м'ять, ю́же і ми благогові́йно чту́ще, поє́м просла́вльшему тя Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся це́рков І́верськая почита́єть тя, апо́столе Си́моне, я́ко основа́теля своєго́ і покрови́теля, назда́вшаго ю на основа́нії незиблемом ві́ри Христо́ви і ороси́вшаго ю к плодоно́сію духо́вному честно́ю твоє́ю кро́вію, от нея́же ди́вно прозябо́ша в ней со́нми святи́х, торжеству́ющих ни́ні вку́пі с тобо́ю на не́бі. Ті́мже і ми на землі́ блажи́м твоя́ по́двиги і си́це тебі́ зове́м:","Ра́дуйся, благи́й і ми́лостивий уті́шителю скорб'я́щих;","Ра́дуйся, скоропредста́тельний помо́щниче бі́дствующих.","Ра́дуйся, ве́ліє дерзнове́ніє стяжа́вий ко Христу́ Бо́гу, я́ко друг Єго́ і́скренній;","Ра́дуйся, приє́мий от Него́ власть на ду́хи нечи́стия.","Ра́дуйся, оби́телі твоєя́ святи́я сла́во і похвало́;","Ра́дуйся, подвизающимся в ней хода́таю ві́чнаго спасе́нія.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 9","ps":["Всему́ ми́ру суди́ти і́маши, апо́столе Спасов, сідя́й на престо́лі висо́ці і превознесе́нні, єгда́ Христо́с Госпо́дь со сла́вою при́йдеть сотвори́ти суд Свой пра́ведний; тогда́, свя́то, умоли́ Єго́ бла́гость поми́ловати нас і не осуди́ти в поги́бель ві́чную, но сподо́бити со святи́ми пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не довлі́єть к досто́йному прославле́нію твої́х по́двигов і чуде́с, Си́моне прехва́льне, оба́че прийми́, учениче́ Спасов, благоутро́бно і ми́лостиво сія́ ма́лия на́ша і нехитростния пі́сні, в похвалу́ тебі́ приноси́мия с ві́рою і любо́вію, і усли́ши вопію́щих ті си́це:","Ра́дуйся, от восто́ка і до за́пада хвали́мий і сла́вимий;","Ра́дуйся, І́верськую страну́ кончи́ною твоє́ю освяти́вий.","Ра́дуйся, я́ко ло́зу благопло́дную, в ней Ні́ну равноапо́стольную духо́вно возрасти́вий;","Ра́дуйся, со́нми святи́х от нідр єя́ Христу́ плодопринесий.","Ра́дуйся, гори́ і удо́лія єя́ подвижниками благоче́стія просла́вивий;","Ра́дуйся, я́ко оте́ць со ча́ди, со святи́ми Іверськими в оби́теліх ра́йських торжеству́яй.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасе́нія зало́г, святу́ю правосла́вную ві́ру, унаследовахом от тебе́, апо́столе Христо́в Си́моне. Ті́мже мо́лим тя: от вся́ких єресе́й і раско́лов соблюди́ нас, чад твої́х, моли́твенним предста́тельством твої́м к Бо́гу і помози́ нам в правосла́вії непоколеби́мом преби́ти до конця́ дній на́ших і ві́рно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Христа́ ізбра́нний учениче́, Си́моне блаже́нне, помоли́ся Єму́ за ни грі́шния, да ре́вность твоя́ боголюбе́зная о хране́нії зако́на Єго́ да́рується і нам недосто́йним, во є́же би́ти нам готовими на по́двиги доброделанія християнського і на іспові́даніє правосла́вния на́шея ві́ри не словеси́ то́кмо, но і ді́ли, і яви́тися ча́дами твої́ми не по і́мені то́кмо, но са́мою і́стиною. О сем тя мо́лим і зове́м:","Ра́дуйся, звіздо́ пресві́тлая, всіх путеводящая к со́лнцю пра́вди Христо́ву;","Ра́дуйся, свіще́ неугаси́мая, в моли́твах присногоря́щая у Престо́ла Го́спода сла́ви.","Ра́дуйся, сто́лпе непоколеби́мий святи́я Христо́ви Це́ркве;","Ра́дуйся, фіяле злати́й, ізлива́яй струї́ нам ціле́бния.","Ра́дуйся, приє́мий от Христа́ власть в'яза́ти і ріши́ти;","Ра́дуйся, получи́вий от Него́ благода́тния да́ри Ду́ха Свята́го.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Тро́йце го́ре прино́сиши єє всі́ми святи́ми, Си́моне прехва́льне, і от небе́сних висо́т оте́чеськи приникаєши на мі́сто по́двигов і страда́ній твої́х на землі́, моли́твами твої́ми помога́я всім, ві́рно чту́щим святу́ю па́м'ять твою́ і пою́щим о тебі́ піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельний світи́льникі Трисо́лнечнаго Сві́та явля́єшися ві́рним, апо́столе Христо́в Си́моне, і всіх нас неви́димо озаря́єши на путі́ доброделанія христия́нськаго, да не паде́м в сіть врага́, дия́вола, но невреди́ми пребу́дем от всіх єго́ ловле́ній лука́вих і та́ко неосужде́нно возмо́жем вопи́ти тебі́:","Ра́дуйся, па́стирю до́брий слове́снаго стада́ Христо́ва;","Ра́дуйся, не попускаяй во́лку душегубительному расхи́тити духо́вную па́ству твою́.","Ра́дуйся, мре́жею про́повіді твоєя́ ми́ра конці́ улови́вий во спасе́ніє;","Ра́дуйся, і ни́ні способствуяй на́шему спасе́нію моли́твами твої́ми.","Ра́дуйся, архитектоне прему́дрий Це́ркве Христо́ви;","Ра́дуйся, ка́меню краєуго́льний єя́ основа́нія.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть і ми́лость іспроси́ нам у Го́спода, Си́моне богоно́сне, апо́столе Спасов, я́ко стяжа́вий ве́ліє к Нему́ дерзнове́ніє, найпа́че проси́ нам у Него́ покая́нія во грісі́х і ісправле́нія житія́ на́шего, да бу́деть о́но преіспо́лнено доброді́телей христия́нських, во є́же возмощи́ нам єще́ на землі́ досто́йно пі́ти Созда́телю на́шему небе́сную піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще болі́зні і труди́ твоя́, апо́столе Спасов, ї́миже труди́лся єси́ во благові́стії Христо́во, почита́єм святу́ю і присносла́вную па́м'ять твою́, я́же облагоуха́єть нас духо́вно і услажда́єть душі́ на́ша: ми́ро бо воі́стину яви́шася пред Бо́гом по́ти твоя́ і ка́плі кро́ве страда́льчеськия, за Христа́ ізлія́нния тобо́ю, святи́й наш предста́телю. Ті́мже і зове́м тебі́:","Ра́дуйся, Пресвяти́я Живонача́льния Тро́йці ві́рний пропові́дниче;","Ра́дуйся, а́нгельських лико́в досто́йний собесі́дниче.","Ра́дуйся, апо́столов красото́ і основа́ніє;","Ра́дуйся, челові́чеськаго ро́да возвише́ніє.","Ра́дуйся, врачу́ безме́здний неду́гов душе́вних і тіле́сних;","Ра́дуйся, по Бо́зі і Пресвяті́й Богоро́дице непости́дноє на́ше упова́ніє.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 13","ps":["О святи́й, сла́вний і всехва́льний апо́столе Христо́в Си́моне, ревни́телю зако́на Бо́жия і многомо́щний наш предста́телю! Прийми́ ма́лоє сіє́ моле́бноє пі́ніє, в похвалу́ тебі́ приноси́моє, і умоли́ Спа́са Христа́ ізба́вити нас муки́ ві́чния і сподо́бити ра́дості святи́х, да с ни́ми поє́м Єму́ во ві́ки: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Влади́ка, Христо́с Бог, спасти́ хотя́ па́дшеє челові́чество, в плоть на́шу облече́ся і с челові́ки поживе́, в Ка́ну же Галиле́йськую на брак в дом твой при́йде, Си́моне прехва́льне, вку́пі с Пречи́стою Своє́ю Ма́терію, Ді́вою Богоро́дицею, Єя́же умоле́нієм Ма́тернім нача́ток чуде́с Свої́х в до́мі твоє́м яви́, во́ду во вино́ на бра́ці твоє́м чуде́сно претвори́в і сим показа́в Божества́ Своєго́ си́лу. Ті́мже тебі́, си́це облагодатствованному посіще́нієм і благоволе́нієм Богочелові́ка, я́ко Богови́дцю і ученику́ Єго́ ізбра́нному, со умиле́нієм си́це вопіє́м:","Ра́дуйся, женише́ прекра́сний, от бра́ка земна́го на брак А́гнчий чуде́сно призва́нний;","Ра́дуйся, на небесі́ і на землі́ просла́вленний.","Ра́дуйся, вопло́щшемуся Бо́гу Сло́ву ві́рно послужи́вий;","Ра́дуйся, в пропові́данії Єва́нгелія пра́вди ре́вность ве́лію яви́вий.","Ра́дуйся, Пресла́дкаго Го́спода Ісу́са всім се́рдцем твої́м возлюби́вий;","Ра́дуйся, обру́чницю земну́ю оста́вивий і во слід Єго́ потекий.","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нний апо́столе Христо́в і благові́стниче, мре́жею про́повіді твоєя́ улови́вий во спасе́ніє мно́гія душі́ челові́чеськія і ко Христу́ приведи́й ідолослуже́нієм помраче́нния лю́ди, Си́моне блаже́нне, в пі́сніх восхваля́єм тя с любо́вію і мо́лим ті ся приле́жно: я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся Єму́ ви́ну за ни грі́шния і моли́твами твої́ми от вся́ких нас бід свобожда́й, да зове́м ті:","Ра́дуйся, Си́моне, апо́столе Христо́в і моли́твенниче о душа́х на́ших."]},{"h":"Молитва","ps":["Святи́й сла́вний і всехва́льний апо́столе Христо́в Си́моне, сподо́бивийся прия́ти в дом твой в Ка́ні Галиле́йстій Го́спода на́шего Ісу́са Христа́ і Єго́ Пречи́стую Ма́тер, Влади́чицю на́шу Богоро́дицю, і очевидцем би́ти пресла́внаго чудесе́ Христо́ва, на бра́ці твоє́м явле́ннаго, претворе́нія води́ во вино́! Мо́лим тя с ві́рою і любо́вію: умоли́ Христа́ Го́спода претвори́ти душі́ на́ша із гріхолюби́вих в боголюби́вия; сохрани́ і соблюди́ нас моли́твами твої́ми от іскуше́ній дия́вольських і паде́ній гріхо́вних, і іспроси́ нам сви́ше по́мощ во вре́м'я уни́нія і беспомощія на́шего; да не преткне́мся о ка́мень собла́зна, но неукло́нно ше́ствуєм спаси́тельним путе́м за́повідей Христо́вих, до́ндеже дости́гнем о́них блаже́нних оби́телей ра́йських, іді́же ти ни́ні водворя́єшися і весели́шися. Єй, апо́столе Спасов! Не посрами́ нас, крі́пці на тя упова́ющих, но бу́ди нам помо́щник і покрови́тель во всем житії́ на́шем і помози́ нам благоче́стно і богоуго́дно житіє́ сіє́ вре́менноє сконча́ти, благу́ю і ми́рную христия́нськую кончи́ну получи́ти і до́браго отві́та сподо́битися на Стра́шнім Суді́ Христо́ві; да избіжа́вше мита́рств возду́шних і вла́сті лю́таго мироде́ржця, унаслі́дуєм Ца́рство Небе́сноє і просла́вим великолі́пноє і́м'я Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Апо́столе святи́й Си́моне, / моли́ ми́лостиваго Бо́га, / да прегріше́ній оставле́ніє // пода́сть душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Ізві́стно прему́дрости уче́нія в душа́х благоче́ствующих поло́жшаго / во хвале́нії ублажі́м, я́ко Богоглаго́ливаго всі Си́мона: / престо́лу бо сла́ви ни́ні предстої́ть і со Безпло́тними весели́ться, // моля́ся непреста́нно о всіх нас."]},{"h":"Величання","ps":["Велича́єм тя, / апо́столе Христо́в Си́моне / і чтим болі́зні і труди́ твоя́, / ї́миже труди́лся єси́ / во благові́стії Христо́ві."]}],"notes":[]},{"u":"Акафіст трьом святителям Василію Великому, Григорію Богослову і Іоанну Золотоустому","e":"Akathist to the Three Hierarchs Basil the Great, Gregory the Theologian and John Chrysostom","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії світи́льници Це́ркве Христо́ви, Васи́ліє, Григо́ріє і Іоа́нне, уче́ньми ва́шими мир просвіти́вшії і вся шата́нія єресе́й і ху́льних смуще́нія угаси́вшії; я́ко хода́таї спасе́нія на́шего су́ще, моли́твами ва́шими сохрані́те ни от вся́ких бід і ві́чних мук, да с ра́достію благодаря́ще вопіє́м вам:","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци Небе́снії, святи́теліє Христо́ви і отці́ треблаже́ннії, побо́рници Живонача́льния Тро́йці, от Нея́ сві́том трисо́лнечним осіяваємії і моля́щіїся непреста́нно у Престо́ла Триіпоста́снаго Божества́ о душа́х на́ших, усли́шіте ни от се́рдця к вам взивающия:","Ра́дуйтеся, іму́щії дерзнове́ніє вопи́ти о нас ко Го́споду;","Ра́дуйтеся, вели́ції уго́дниці Святи́я Тро́йці.","Ра́дуйтеся, дарова́ньми єдиноче́стнії;","Ра́дуйтеся, апо́столом єдинонра́внії.","Ра́дуйтеся, я́ко ва́шими уче́ньми ди́вно просія́ благода́ть Христо́ва;","Ра́дуйтеся, ра́зум свой в послуша́ніє ві́ри пліни́вшії.","Ра́дуйтеся, блазі́ї ді́лателіє виногра́да Христо́ва;","Ра́дуйтеся, от ю́ности Бо́гом благослове́ннії.","Ра́дуйтеся, ско́рби житія́ сего́ до́брі претерпі́вшії і да́нний вам тала́нт приумножившії;","Ра́дуйтеся, во́лю Бо́жию си́льним ми́ра сего́ со мно́гим дерзнове́нієм благовестившії.","Ра́дуйтеся, тьму нече́стія отгна́вшії;","Ра́дуйтеся, всю подсо́лнечную заря́ми догма́тов просвіти́вшії.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 2","ps":["Ви́дя єрети́чествующих лю́тая стремле́нія, меч острі́йший проти́ву сіте́й лжеуче́ній і огнь, пле́вели суєму́дрія поядай, святи́й Васи́лій яви́ся і, я́ко па́стир ізря́днійший, обличив лесть і́дольськую свої́м богодухнове́нним віща́нієм, научи́ ни почита́ти Святу́ю Тро́йцю, разділе́ну у́бо Іпоста́сьми, соєдине́ну же Существо́м, і вопи́ти Єй: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум озаре́н благода́тію Христо́вою іму́ще, я́ко апо́столом єдинонра́внії, правосла́вних догма́тов уче́нія уясни́сте і тріє́ вели́ції світи́льници Триіпоста́снаго Божества́ яви́стеся; ва́шими бо вдохнове́нними писа́ньми озаря́єма, Це́рков Христо́ва сві́тло красу́ється, і ві́рная ча́да єя́ в мі́ру во́зраста ісполне́нія Христо́ва восхо́дять. Ті́мже взира́юще на бога́тство благода́ті Христо́ви, вам дарова́нния, я́ко просвіти́телі на́ша восхваля́єм ви, вопію́ще такова́я:","Ра́дуйтеся, богоно́снії небе́снії таї́нници;","Ра́дуйтеся, покая́нія немолчнії пропові́дници.","Ра́дуйтеся, сосу́ди ізбра́ннії;","Ра́дуйтеся, прему́дрії учи́теліє вселе́нния.","Ра́дуйтеся, в Боже́ственних уче́ніїх Христо́вих лю́ди наставившії;","Ра́дуйтеся, в повелі́ніїх Госпо́дніх всегда́ усе́рдно ходи́вшії.","Ра́дуйтеся, многоразли́чних доброді́телей обряди во ва́шем житії́ явившії;","Ра́дуйтеся, столпи́ непоколеби́мії, ві́ру Христо́ву Боже́ственними догма́ти утверди́вшії.","Ра́дуйтеся, слове́сноє ста́до Христо́во му́дре упа́сшії;","Ра́дуйтеся, Правосла́вія ізря́днійшії богосло́ві.","Ра́дуйтеся, світи́ла, вся конці́ землі́ просвіща́ющая;","Ра́дуйтеся, свирі́ль і цівни́це сладкозвучная.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 3","ps":["Си́ла моле́ній о́тчих пону́ди свята́го Григо́рія Понт оста́вити і в Назіянз ко отцю́ своєму́, по́мощі ра́ди єму́, пресели́тися, іді́же сла́ву Бо́жию уче́ньми і ді́ли віща́ше і є́ресь аріянськую посрамля́ше. Ті́мже і нас, вели́кий святи́телю Григо́ріє, Боже́ственнаго рая́ нетлі́нния проходя́ па́жити, помина́й у престо́ла Святи́я Тро́йці, да умиле́нієм взива́єм єй: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще в сердця́х світоно́сную благода́ть Святи́я, Єдиносу́щния і Неразді́льния Тро́йці, тріє́ богопропові́дници, разделеннії тілеси́ і совокупленнії ду́хом, благоче́стно я́ві пропові́даша Тро́йцю Єди́ну непремі́нную, Существо́ же і Божество́, і сію́ про́повідь страда́ньми запечатлі́ша. Ті́мже і ми, подража́юще ві́рі їх, вопіє́м такова́я:","Ра́дуйтеся, си́льнії і непреборимії Це́ркве Христо́ви спобо́рници;","Ра́дуйтеся, і́стини Христо́ви усе́рднії ревни́тели.","Ра́дуйтеся, ко Пресвяті́й Тро́йце моли́твенниці те́плії;","Ра́дуйтеся, Це́ркве Христо́ви па́стиріє до́брії.","Ра́дуйтеся, А́рія низложи́вшії і правосла́вния утверди́вшії;","Ра́дуйтеся, Тро́йцю Єди́ну Непремі́нную, Существо́ і Божество́, дія́ньми уче́ньми просла́вившії.","Ра́дуйтеся, Отця́, і Си́на, і Свята́го Ду́ха, Тро́йці Іпоста́си, ди́вно уяснившії;","Ра́дуйтеся, Трисія́тельнаго ра́ди і Єди́наго Божества́ велича́йшия ско́рби і гоне́нія претерпі́вшії.","Ра́дуйтеся, тяготу́ дневну́ю до сконча́нія своєго́ житія́ неосла́бно поне́сшії;","Ра́дуйтеся, нощ мра́чную злочести́вих єресе́й луча́ми богому́дрих догма́тов отгна́вшії.","Ра́дуйтеся, ду́ші ві́рних благода́тно напитавшії;","Ра́дуйтеся, Ца́рствія Ві́чнаго наслі́дници би́ти сподо́бившіїся.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 4","ps":["Бу́рю я́рости і гні́ва воздвиго́ша, о Златоу́сті, безу́мнії лю́діє, клевещуще на тя і ізгна́ти от ца́рствующаго гра́да повеліва́юще. Ти же, Златосло́ве, на ка́мені ві́ри Христо́ви непоколеби́мо пребива́я і благода́тію Свята́го Ду́ха укріпля́єм, бу́рю гоне́ній і муче́ній му́жественно претерпі́л єси́ і страда́ньми віне́ць нетлі́нний на Небесі́х себі́ угото́вал єси́, науча́я всіх в терпі́нії нести́ Крест Христо́в і взива́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще богодухнове́нная словеса́ ва́ша, запечатле́нная мно́гими по́двиги і страда́ньми, жа́ждущії глаго́лов Жи́зні Ві́чния іздале́ча к вам прихожда́ху, і нетлі́нную пи́щу от вас приє́мше і Боже́ственнаго питія́ поче́рпше, взива́ху вам сицева́я:","Ра́дуйтеся, глубини́ Сло́ва Бо́жия до́брі іспитавшії;","Ра́дуйтеся, непреста́нним раче́нієм Бо́га взиска́вшії.","Ра́дуйтеся, а́лчущих пра́вди пита́теліє;","Ра́дуйтеся, ни́щих ду́хом уті́шителіє.","Ра́дуйтеся, о́блаці істоча́ющії ро́су уче́ній благочести́вих і напая́ющії вселе́нную;","Ра́дуйтеся, приснотеку́щия ріки́ духо́вния, напаяющия ві́рних чад Це́ркве Христо́ви.","Ра́дуйтеся, Боже́ственних Та́їн храни́теліє і слове́сния труби́ Бо́жия;","Ра́дуйтеся, пра́вия ві́ри і благоче́стія християнського насади́теліє.","Ра́дуйтеся, чудеси́ мно́гими ві́рния озаря́ющії;","Ра́дуйтеся, ріки́ врачева́ній нам пролива́ющії.","Ра́дуйтеся, усе́рдно притекающия к вам от іскуше́нії і напа́стей моли́твами ва́шими охраняющії; Ра́дуйтеся, всего́ ро́да христия́нськаго похвало́.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ Христо́с ми́ру показа́ тя, вели́кий во ієра́рсіх Васи́ліє; стяжа́в бо ві́дініє Боже́ственних Та́їн і озаре́ніє сви́ше от Престо́ла благода́ті Бо́жия, уми́ і се́рдця ві́рних богодухнове́нними словеси́ ди́вно просвіти́л єси́, любо́вію же к Бо́гу одушевляєм, гоне́нія і страда́нія за Христа́ до́брі претерпі́л єси́ і сего́ ра́ди сподо́бился єси́ на Небесі́х моли́твеннаго дерзнове́нія у Престо́ла Царя́ Сла́ви, о́браз бив ві́рним сло́вом, житіє́м, ду́хом, любо́вію, ві́рою і чистото́ю, да всі со умиле́нієм вопію́ть Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще вас, святи́теліє Христо́ви, Небе́сним ликостоя́нієм при́сно спребивающия і Престо́лу Бо́жию всегда́ предстоящия, со умиле́нієм воспіва́єм возвели́чившую вас Живонача́льную Тро́йцю, Ю́же сло́вом і житіє́м ва́шим просла́вили єсте́, вам же, моли́твенником ізря́днійшим, от любве́ серде́чния вопіє́м:","Ра́дуйтеся, Го́рнім Лико́м совокупленнії і Святи́х А́нгел сожи́теліє;","Ра́дуйтеся, Престо́лу Царя́ Сла́ви предстоя́щії при́сно со всі́ми ізбра́нними.","Ра́дуйтеся, Сла́вою Небе́сною укра́шеннії;","Ра́дуйтеся, плоть і мир возненави́дівшії.","Ра́дуйтеся, вся сокро́вища ми́ра і жите́йськія сла́сти Христа́ ра́ди во уме́ти вміни́вшії.","Ра́дуйтеся, на світоза́рную доброді́телей колесни́цю возше́дшії і Небе́снаго Ца́рствія дости́гшії.","Ра́дуйтеся, і нам, грі́шним, о́браз доброді́телей сло́вом і житіє́м явившії;","Ра́дуйтеся, мно́гими скорбми́ вше́дшії в ра́дость Го́спода своєго́.","Ра́дуйтеся, те́плії о нас пред Бо́гом хода́таї;","Ра́дуйтеся, правосла́внаго богосло́вія світи́ла ізря́днійшая.","Ра́дуйтеся, ві́ри христия́нськия похвало́;","Ра́дуйтеся, святи́телей сла́во і Це́ркве украше́ніє.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 6","ps":["Пропові́дуя і́стину боговіща́нними твої́ми глаго́ли, сокруши́л єси́, богосло́ве Григо́ріє, е́ллинськая суєму́дрія і єресе́й собла́зни, вселе́нній же всей немо́лчно пропові́дал єси́ в Тро́йці сла́вимаго Бо́га Єдиносу́щнаго, Отця́ і Си́на і Ду́ха Свята́го, науча́я всіх вопи́ти Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́сте сві́том доброді́тельнаго житія́ і правосла́вния ві́ри іспові́данієм во всю вселе́нную і всім язи́ком світ і́стиннаго богопозна́нія уясни́сте, я́коже би́ти вам па́стирем і учи́телем всея́ Це́ркве Христо́ви. Ті́мже і по сме́рті не преста́йте призира́ти на ни, те́плі вам моля́щіяся і взивающия:","Ра́дуйтеся, три світи́ла вели́кая, путеводящая нас ко спасе́нію;","Ра́дуйтеся, просвіти́теліє сідя́щих во тьмі неві́дінія.","Ра́дуйтеся, недоми́сленния Та́йни Триіпоста́снаго Божества́ нам уясняющії;","Ра́дуйтеся, струя́ми му́дрих уче́ній па́ству свою́ напая́ющії.","Ра́дуйтеся, па́стиріє ізря́днійшії, житіє́ своє́ вся́кими доброді́тельми благоукрасившії;","Ра́дуйтеся, ста́до своє́ от волко́в хи́щних соблю́дшії.","Ра́дуйтеся, світи́льници трисо́лнечнаго сві́та, уми́ і се́рдця ві́рних ди́вно озаря́ющії;","Ра́дуйтеся, о́брази цілому́дрія, ревнова́ти о стяжа́нії сея́ доброді́телі нас научающії.","Ра́дуйтеся, церко́вная корми́ла, путь правосла́внаго богові́дінія я́сно показу́ющая;","Ра́дуйтеся, двана́десяти апо́столом єдинонра́внії.","Ра́дуйтеся, А́нгельських Лико́в сожи́теліє;","Ра́дуйтеся, ку́пно со всі́ми святи́ми непреста́нно моля́щіїся о нас.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 7","ps":["Хотя́ змій лука́вий іскуси́ти тя, я́коже І́ова многострада́льнаго, воздви́же бу́рю зло́би нечести́вих, ізгна́вших тя в заточе́ніє. Оба́че благода́тію Христо́вою укріпля́єм, вся́кая злострада́нія і болі́зні до́брі претерпі́л єси́, о́тче Іоа́нне Златоу́сте, і блаже́нния кончи́ни сподо́бился єси́. Ни́ні же пребива́я в невече́рнім дні Ца́рствія Христо́ва, не преста́й моли́тися за ни у Престо́ла Триіпоста́снаго Бо́га, да со умиле́нієм вопіє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вії світи́льници світоза́рнії і Це́ркве непоколеби́мії столпи́ яви́стеся, святи́теліє вели́ції: свя́тостію бо житія́ ва́шего, єще́ во пло́ті су́ще на землі́, бі́сте я́ко безпло́тни. Сего́ ра́ди Це́рков Христо́ва, при́сно прославля́ющи вас, благода́рственная пі́нія воспису́єть світода́вцю Христу́ Бо́гу, Єго́же благода́тію укріпля́ємі, ве́лія болі́зні претерпі́сте і труди́ понесосте во благові́стії Христо́ві. Ті́мже прославля́юще Христа́, непреста́нно благоді́ющаго Це́ркві Своє́й Святі́й, восхваля́єм і вас, я́ко ві́рних слуг Христо́вих і строї́телей Та́їн Бо́жиїх, вопію́ще сицева́я:","Ра́дуйтеся, ві́рнії Тро́йці побо́рници;","Ра́дуйтеся, Правосла́вія непобіди́мії іспові́дниці.","Ра́дуйтеся, ієра́рхов священнонача́льници;","Ра́дуйтеся, луча́ми богосло́вія ва́шего єресе́й неі́стовство разрушившії.","Ра́дуйтеся, пресві́тлії благоче́стія о́бразі;","Ра́дуйтеся, ві́рния в боговеденії утверди́вшії.","Ра́дуйтеся, сло́ва Бо́жия богодухнове́ннії із'яснителіє;","Ра́дуйтеся, Влади́ки Христа́ раби́ блазі́ї і ві́рнії.","Ра́дуйтеся, кро́тость Мойсе́єву і ре́вность Іліїну́ в по́двизіх свої́х воплотившії;","Ра́дуйтеся, терпі́нієм скорбе́й і гоне́ній дре́внему І́ову подража́вшії.","Ра́дуйтеся, Іо́сифа цілому́дрієм і чистото́ю украше́нії;","Ра́дуйтеся, Петро́во іспові́даніє і Іоа́нново богосло́віє показа́вшії.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до благода́ті дарова́нния тебі́, святи́телю Васи́ліє, уві́де на себі́ Єфре́м Сиріяни́н, єгда́ восхоті́вшу єму́ ви́діти тя, о́тче, посла́л єси́ архидия́кона своєго́ привести́ єго́ к тебі́, і моли́твою твоє́ю Єфре́м уразумі́ язи́к е́ллинський і чудеси́ див'я́ся, просла́ви Бо́га, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всю ві́ру во Святу́ю Тро́йцю непоро́чну сохрани́сте і мно́гі ко Христу́ приведо́сте, святи́теліє Христо́ви, по́двигом до́брим подвиза́вшеся. Сего́ ра́ди, взира́юще на ди́вний по́двиг ваш і на чи́стоє житіє́ ва́ше, со умиле́нієм вопіє́м вам такова́я:","Ра́дуйтеся, Правосла́вія оде́ждою сви́ше істка́нною Це́рков украси́вшії;","Ра́дуйтеся, єрети́чеськая суєсло́вія я́сно обличившії.","Ра́дуйтеся, писа́ньми і словеси́ ва́шими духо́вноє сокро́вище Це́ркві Христо́ві собра́вшії;","Ра́дуйтеся, му́дрость земну́ю і вся кра́сная ми́ра Христа́ ра́ди отве́ргшії.","Ра́дуйтеся, сокро́вищ Небе́сних па́че всего́ взиска́вшії;","Ра́дуйтеся, Пастиренача́льника Христа́, я́ко служи́теліє ві́рнії, живоно́сним стопа́м послі́довавшії.","Ра́дуйтеся, висо́кий о́браз доброді́телей в житії́ ва́шем явившії;","Ра́дуйтеся, душе́вния стра́сті, вку́пі же і тіле́сния, духо́вним мече́м посекшії.","Ра́дуйтеся, Живонача́льній Тро́йце в же́ртву живу́, свя́ту і благоуго́дну себі́ сами́х прине́сшії;","Ра́дуйтеся, грі́шников предста́теліє.","Ра́дуйтеся, ни́щих засту́пниці;","Ра́дуйтеся, па́стирей учи́теліє і о́брази.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 9","ps":["Все́ю душе́ю твоє́ю возлюби́в Бо́га, о́тче Григо́ріє, богови́дную чистоту́ і целому́дріє па́че всіх благ ізбра́л єси́ і богосло́во вели́кий і таї́нник яви́лся єси́. Ни́ні предстоя́ Престо́лу Святи́я Тро́йці, іспроси́ ми́рові мир, і спасе́ніє всім нам, восхваляющим тя і пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йством богодухнове́нним тріє́х вселе́нських святи́телей єретичестії собла́зни преста́ша, правосла́вная же ві́ра па́че і па́че превозмо́же. Сего́ ра́ди от усе́рдія на́шего со умиле́нієм і любо́вію взива́єм к ним такова́я:","Ра́дуйтеся, любо́вію Правосла́вія все житіє́ ва́ше озари́вшії;","Ра́дуйтеся, Єди́наго Бо́га в трех ли́цях чествова́ти научи́вшії.","Ра́дуйтеся, А́рієво злоче́стіє і хуле́нія іни́х єретико́в низложи́вшії;","Ра́дуйтеся, лжеучи́телей пребеззако́нная уста́ сві́тлостію слове́с ва́ших заградившії.","Ра́дуйтеся, небе́сния труби́, пропові́давшия ми́рові Христо́во Єва́нгеліє;","Ра́дуйтеся, во ієра́рсіх світи́ла три вели́кая.","Ра́дуйтеся, учи́теліє кро́тости, воздержа́нія, вку́пі же і покая́нія;","Ра́дуйтеся, мона́шествующих до́брії учи́теліє і наста́вници.","Ра́дуйтеся, Це́ркве огражде́ніє і Правосла́вія побо́рници;","Ра́дуйтеся, в труди́ апо́столов вше́дшії і клас до́браго іспові́данія пожавшії.","Ра́дуйтеся, за ві́ру і по́двиги вінці́ нетлі́нния от Пастиренача́льника Христа́ приє́мшії;","Ра́дуйтеся, вели́кия труди́ і по́двиги во благоустроє́нії Це́ркве Христо́ви под'ємшії.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 10","ps":["Спа́са Христа́ умоля́ти не преста́й о чту́щих па́м'ять твою́, всехва́льне Іоа́нне Златоу́сте: тебі́ бо даде́ся благода́ть моли́тися за ни. Ті́мже і ми, я́ко ко благоуха́ннаго ми́ра сосу́ду, точащему ісціле́нія всім с ві́рою притекающим, со умиле́нієм і любо́вію припа́дающе, вопіє́м просла́вльшему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єсте́ необори́мая празднующим святу́ю па́м'ять ва́шу і всім притекающим к моли́твенному покро́ву ва́шему, непости́дная наде́жда і крі́пкоє заступле́ніє. Ті́мже і нам, святі́ї тріє́ святи́теліє, со умиле́нієм припадающим к вам, іспросі́те у Престо́ла Святи́я Тро́йці ми́лость і благода́ть во благовре́менную по́мощ, да с ра́достію і благодаре́нієм взива́єм вам:","Ра́дуйтеся, ми́лость і утіше́ніє всім ві́рним явля́ющії;","Ра́дуйтеся, кающіяся грі́шники от сіте́й дия́вола ізбавля́ющії.","Ра́дуйтеся, благода́тних даро́в усе́рднії раздаятеліє;","Ра́дуйтеся, всіх челові́к предста́тельство і покро́ве.","Ра́дуйтеся, си́рих отце́в і вдов засту́пниці;","Ра́дуйтеся, убо́гих бога́тство і боля́щих ісціле́ніє.","Ра́дуйтеся, милосе́рдія ко стра́ждущим немолчнії пропові́дници і ю́них наста́вници;","Ра́дуйтеся, ста́рець пита́теліє.","Ра́дуйтеся, су́щих в ско́рбіх уті́шителіє;","Ра́дуйтеся, стра́нних сопутници.","Ра́дуйтеся, ізнемога́ющим поможе́ніє;","Ра́дуйтеся, чту́щим па́м'ять ва́шу ра́дость і спасе́ніє низпосилающії.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Тро́йце па́че іни́х принесли́ єсте́, святи́теліє Бо́жії, умо́м сло́вом, ді́лом і богосло́вним вити́йством ва́шим сплете́нія ри́торськая разруши́ли єсте́, наставля́юще ни почита́ти Тро́йцю во Єди́ниці і воспіва́ти Єй: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную тро́йцю святи́х ієра́рхов, Васи́лія ца́рствія тезоімени́таго, Григо́рія Богосло́ва найменованнаго, Іоа́нна Златоу́стаго учи́теля вселе́нния, глубини́ Бо́жия іспита́вших, восхваля́юще і сві́тлую па́м'ять їх благогові́йно торжеству́юще, похва́льная пі́нія прино́сим такова́я:","Ра́дуйтеся, благознамени́тия труби́ Боже́ственних глаго́лов;","Ра́дуйтеся, цівни́ци богодухнове́нния.","Ра́дуйтеся, апо́стольських богодухновенній із'яснителіє;","Ра́дуйтеся, апо́стольських преда́ній ревни́теліє.","Ра́дуйтеся, ди́вная вели́чія Бо́жия всім земноро́дним пові́дающії;","Ра́дуйтеся, Сла́ву Бо́жию ва́шим житіє́м і сло́вом пропові́давшії всей вселе́нній.","Ра́дуйтеся, ко спасе́нію до́брії путеводи́теліє і наста́вници;","Ра́дуйтеся, растлі́нних оби́чаєв іскорени́теліє, благи́х же нра́вов насади́теліє.","Ра́дуйтеся, отриця́тися плотськи́х по́хотей і страсте́й научающії;","Ра́дуйтеся, вра́чеве прему́дрії неду́гов душе́вних і тіле́сних.","Ра́дуйтеся, церко́вная світи́ла, от Трисо́лнечнаго Сві́та возжже́нная;","Ра́дуйтеся, цві́ти благово́ннії ра́йськаго прозябе́нія.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия оби́льно ізлія́ся во уста́ ва́ших, треблаже́ннії: ві́ра правосла́вная ва́ми укріпи́ся, і мгла єрети́чеських шата́ній і лжеуче́ній сві́том богодухнове́нних писа́ній отгна́ся. Ті́мже, святи́теліє, молі́теся ко Христу́ Бо́гу, да дух ре́вности ва́шея о ві́рі і благоче́стії почі́єть і на нас, да сподо́бимся ку́пно с ва́ми пі́ти Святі́й Тро́йці: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще і сві́тло пра́зднующе свяще́нную па́м'ять ва́шу, треблаже́ннії Васи́ліє Вели́кий, Богосло́ве Григо́ріє і Златоу́стий Іоа́нне, смире́нно мо́лим вас, не преста́йте моли́тися Христу́ о всіх, ві́рою призива́ющих вас і с любо́вію вопію́щих такова́я:","Ра́дуйтеся, правосла́вних догма́тов храни́теліє;","Ра́дуйтеся, богосло́вія живоноснії істо́чници.","Ра́дуйтеся, ві́рних се́рдця Боже́ственне веселящії;","Ра́дуйтеся, я́ко неосла́бними по́двиги ва́шими А́рій низложи́ся.","Ра́дуйтеся, я́ко огне́м богодухнове́нних віща́ній ва́ших Євно́мієва є́ресь попали́ся;","Ра́дуйтеся, я́ко ва́шими богодуновенними глаго́ли Саве́ллія є́ресь отгна́ся.","Ра́дуйтеся, я́ко мудрова́ніє Не́стора ва́ми упраздни́ся;","Ра́дуйтеся, о ми́рі моли́твенниці ізря́днійшії.","Ра́дуйтеся, к Ца́рствію Небе́сному ві́рния возводя́щії;","Ра́дуйтеся, Бо́жії гла́си, пречу́дно нам возгремевшії.","Ра́дуйтеся, па́стирей Це́ркве достоподражательнії о́бразі;","Ра́дуйтеся, по апо́столу всім вся би́вшії.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 13","ps":["О святи́теліє Христо́ви і отці́ треблаже́ннії, Васи́ліє Вели́кий, церко́вноє світи́ло і сто́лпе непоколеби́мий, Богосло́ве Григо́ріє, у́ме богопросвіще́нний, архієре́ю превели́кий, вку́пі же і Златоу́сте Іоа́нне, покая́нія тве́рдий пропові́дниче, небе́сним спребива́юще лико́м і А́нгельським совоку́пльшеся Си́лам, ни́нішнєє приє́мше ма́лоє моле́ніє на́ше, іспросі́те нам у Всеще́драго Бо́га ви́шняя ми́слити і ді́яти, да ві́чния муки́ ізбі́гше, небе́сную жизнь наслі́дим с ва́ми, вопію́ще Бо́гу: Аллилу́я, Аллилу́я, Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци Небе́снії, святи́теліє Христо́ви і отці́ треблаже́ннії, побо́рници Живонача́льния Тро́йці, от Нея́ сві́том трисо́лнечним осіяваємії і моля́щіїся непреста́нно у Престо́ла Триіпоста́снаго Божества́ о душа́х на́ших, усли́шіте ни от се́рдця к вам взивающия:","Ра́дуйтеся, іму́щії дерзнове́ніє вопи́ти о нас ко Го́споду;","Ра́дуйтеся, вели́ції уго́дниці Святи́я Тро́йці.","Ра́дуйтеся, дарова́ньми єдиноче́стнії;","Ра́дуйтеся, апо́столом єдинонра́внії.","Ра́дуйтеся, я́ко ва́шими уче́ньми ди́вно просія́ благода́ть Христо́ва;","Ра́дуйтеся, ра́зум свой в послуша́ніє ві́ри пліни́вшії.","Ра́дуйтеся, блазі́ї ді́лателіє виногра́да Христо́ва;","Ра́дуйтеся, от ю́ности Бо́гом благослове́ннії.","Ра́дуйтеся, ско́рби житія́ сего́ до́брі претерпі́вшії і да́нний вам тала́нт приумножившії;","Ра́дуйтеся, во́лю Бо́жию си́льним ми́ра сего́ со мно́гим дерзнове́нієм благовестившії.","Ра́дуйтеся, тьму нече́стія отгна́вшії;","Ра́дуйтеся, всю подсо́лнечную заря́ми догма́тов просвіти́вшії.","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Кондак 1","ps":["Ізбра́ннії світи́льници Це́ркве Христо́ви, Васи́ліє, Григо́ріє і Іоа́нне, уче́ньми ва́шими мир просвіти́вшії і вся шата́нія єресе́й і ху́льних смуще́нія угаси́вшії; я́ко хода́таї спасе́нія на́шего су́ще, моли́твами ва́шими сохрані́те ни от вся́ких бід і ві́чних мук, да с ра́достію благодаря́ще вопіє́м вам:","Ра́дуйтеся, тріє́ святи́теліє, вели́ції і вселе́нстії учи́теліє."]},{"h":"Молитва","ps":["О пресві́тлії світи́льници Це́ркве Христо́ви, Васи́ліє, Григо́ріє і Іоа́нне, сві́том правосла́вних догма́тов вся конці́ землі́ озари́вшії і мече́м сло́ва Бо́жия ху́льних смуще́нія і шата́нія єресе́й угаси́вшії; припа́дающе к ва́шему милосе́рдію, с ві́рою і любо́вію із глубини́ душі́ вопіє́м: предстоя́ще Престо́лу Пресвяти́я, Єдиносу́щния, Животворя́щия і Неразді́льния Тро́йці, за Ню́же сло́вом, писа́нієм і житіє́м до́брі подвиза́стеся і ду́ші своя́ полага́сте, всегда́ молі́теся Єй, да укріпи́ть і ни в Правосла́вії і єдиноми́слії, і непоколеби́мім да́же до сме́рти іспові́данії ві́ри Христо́ви, і во вседуше́внім послуша́нії єго́ Це́ркві Святі́й: да препоя́шеть ни с висоти́ си́лою на вся неви́димия і ви́димия враги́ на́ша: да соблюде́ть Це́рков свою́ нези́блему от неві́рія, суєві́рія, єресе́й і раско́ла; да да́руєть архипа́стирем на́шим здра́віє, долгоде́нствіє і во всем благо́є поспіше́ніє: па́стирем на́шим да пода́сть духо́вноє трезві́ніє і ре́вность о спасе́нії пасо́мих, прави́телем суд і пра́вду, во́їном терпі́ніє, му́жество і одолі́ніє на враги́, си́рим і вдови́цям заступле́ніє, боля́щим ісціле́ніє, ю́ним благо́є во ві́рі возраста́ніє, старцям утіше́ніє, оби́димим заступле́ніє, і всім вся ко вре́менній і ві́чній жи́зні потре́бная, я́ко да в ми́рі і покая́нії, жела́нієм спасе́нія горя́ще, Го́сподеві рабо́тающе, до́брим по́двигом подвиза́ющеся, тече́ніє на́ше сконча́єм і сподо́бимся в Небе́снім Ца́рствії ку́пно с ва́ми всегда́ пі́ти і сла́вити Пресвято́є і Великолі́поє І́м'я Отця́, і Си́на, і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко апо́столов єдинонра́внії / і вселе́нния учи́теліє, / Влади́ку всіх молі́те / мир вселе́нній дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Свяще́нния і Боговіща́нния пропові́дники, / верх учи́телей, Го́споди, прия́л єси́ в наслажде́ніє благи́х твої́х і упокоє́ніє: / труди́ бо о́ніх і смерть прия́л єси́ па́че вся́каго всепло́дія, // Єди́не прославля́яй святи́я Твоя́."]},{"h":"Величання","ps":["Велича́єм вас, / святи́теліє Васи́ліє, Григо́ріє і Іоа́нне, / і чтим святу́ю па́м'ять ва́шу: / ви бо мо́лите за нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому мученику Аврамію Болгарському","e":"Akathist to the Holy Martyr Abraham of Bulgaria","secs":[{"h":"Кондак 1","ps":["Ізбра́нний страстоте́рпче Христо́в і чудотво́рче преди́вний, во страда́нії твоє́м віне́ць приє́мий от руки́ Вседержи́теля і со а́нгели предстоя́й Єго́ престо́лу, пі́сньми восхваля́єм тя любо́вію і мо́лим ті ся, моли́твами твої́ми от вся́ких бід і скорбе́й свобожда́й нас, тебі́ зову́щих:","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Ікос 1","ps":["А́нгелов сожи́тель і челові́ков засту́пник воі́стину яви́лся єси́, му́чениче достохва́льне, благоволе́нієм всіх Творця́ Христа́ Бо́га, Єго́же возлюби́л єси́ і за Него́ же пострада́л єси́ да́же до кро́ве во іспові́данії непоколеби́мім. Ті́мже прийми́ от нас сія́ хвале́нія:","Ра́дуйся, звіздо́ пресві́тлая благоче́стія;","Ра́дуйся, світи́ло, во тьмі нече́стія пресла́вно возсія́вшеє.","Ра́дуйся, злові́рія магоме́това обличи́телю;","Ра́дуйся, ві́ри христия́нськия небоя́зненний пропові́дниче.","Ра́дуйся, Єва́нгельськаго уче́нія до́брий послу́шателю;","Ра́дуйся, зако́на Госпо́дня теплі́йший храни́телю.","Ра́дуйся, ку́плю вре́менную преміни́вий на стяжа́ніє ві́чноє небе́сноє;","Ра́дуйся, ві́ри Христо́ви би́сер многоці́нен стяжа́вий.","Ра́дуйся, Христо́вим уче́нієм ду́шу твою́ просвіти́вий;","Ра́дуйся, удосто́ївийся благода́тнаго осіне́нія сви́ше.","Ра́дуйся, яви́вийся доброді́телей жили́ще, преукра́шенноє чистото́ю;","Ра́дуйся, Ду́ха Свята́го оби́тель прекра́сная.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 2","ps":["Ви́дя Христо́с Госпо́дь ду́шу твою́, ко прия́тію сі́мені сло́ва Бо́жия чистото́ю і ми́лостинею предугото́ванную, сві́том позна́нія Своєго́ просвіти́ тя, блаже́нне, я́ко Корни́лія со́тника дре́вле, та́ко і твоя́ доброді́телі преждеби́вшия пом'яну́в любоблагоутро́бно, спаса́ємих ча́сти сотвори́ тя о́бщника в Небе́снім Ца́рствії, іді́же со а́нгели поє́ши Пресвяті́й Тро́йце піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́нний дарова́ся тебі́, Авраа́міє, і́мже я́сно проразумі́л єси́ тщету́ душепа́губную злові́рія магоме́това, і о́наго уклони́тися, Христа́ же взиска́ти потща́лся єси́ вседу́шно; ті́мже взива́єм ті:","Ра́дуйся, блаже́нний послі́дователю Христо́в;","Ра́дуйся, люби́телю за́повідей Єго́ преі́скренній.","Ра́дуйся, кри́не благоуха́нний рая́ преви́шняго;","Ра́дуйся, цві́те прекра́сний вертогра́да Ісу́сова.","Ра́дуйся, бога́тство земно́є нівочто́же вміни́вий;","Ра́дуйся, стяжа́нія тлі́нная презрі́вий.","Ра́дуйся, ни́щія удовли́вий;","Ра́дуйся, рука́ми убо́гих сокро́вища твоя́ го́ре предпосла́вий.","Ра́дуйся, я́ко не уклони́лся єси́ в сіть лихоїма́нія;","Ра́дуйся, я́ко неулови́м преби́л єси́ мре́жею сребролю́бія.","Ра́дуйся, му́дрий купе́ць Ца́рствія Небе́снаго;","Ра́дуйся, ві́рний ра́бе, да́нний тебі́ мнас усугуби́вий.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго укріпи́ тя на по́двиг страда́льчеський, му́чениче святи́й Авраа́міє; не терп'я́ бо ви́діти па́губу душ челові́чеських, ре́вностію разже́глся єси́ по Бо́зі жи́ві, і став посреді́ то́ржища, небоя́зненно обличи́л єси́ магоме́тову пре́лесть, поуча́я собра́тій твої́х благоче́стно ві́ровати во Христа́, за Него́ же і страда́ти не уклони́лся єси́, зови́й: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я злові́рієм потемне́нния ду́ші, не восхоті́ша бо́лгаре прини́кнути в ра́зум слове́с твої́х боже́ственних, но ру́ці уби́йственния на тя возложи́вше, біє́нієм лю́тим содробля́ху твоя́ соста́ви. Ми же, ублажа́я страда́нія твоя́, глаго́лем:","Ра́дуйся, Христа́ вседу́шно возлюби́вий;","Ра́дуйся, любо́в к Нему́ я́звами, за Него́ под'я́тими, яви́вий.","Ра́дуйся, апо́столом поревнова́вий;","Ра́дуйся, орга́н Свята́го Ду́ха би́вий.","Ра́дуйся, благові́стія Єва́нгельськаго уста́ благоглаго́ливая;","Ра́дуйся, словеса́ жи́зні ві́чния провеща́яй.","Ра́дуйся, біє́ніє лю́тоє за пресла́дкаго ті Ісу́са сла́дці претерпі́вий;","Ра́дуйся, поруга́ніє і досажде́ніє за Него́ благоду́шно восприя́вий.","Ра́дуйся, я́ко во іспові́данії Христо́ві непоколеби́м преби́л єси́;","Ра́дуйся, я́ко ласка́нми і прельще́нми непрекло́нен яви́лся єси́.","Ра́дуйся, страстоте́рпче, в му́жестві неодолі́нний;","Ра́дуйся, добропобе́дниче, в терпі́нії непрело́жний.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 4","ps":["Бу́рею зло́би ди́шуще, нечести́вії бо́лгаре терза́ху тя, я́ко а́гнця незло́бива зві́ріє ди́вії, покуша́яся му́ками отврати́ти тя от Христа́ ко своєму́ нече́стію; но нічто́же успі́ша потемне́ннії, си́лою бо сви́ше укріпля́єм, посрами́л єси́ о́них ухищре́ніє, посреді́ муче́ній немо́лчно іспові́дуя Христа́, єди́наго Творця́ і Бо́га, і вопія́ Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав увеща́тельния твоя́ глаго́ли, мучи́теліє твої́, а́спидом глухи́м уподо́бльшеся, сугу́бими ра́нами уязвля́ху ті́ло твоє́ многотерпіли́воє, Авраа́міє свя́те, я́ко не би́ти на нем мі́ста ці́ла і неуя́звлена. Див'я́шеся у́бо вели́честву терпі́нія твоєго́, зове́м ті:","Ра́дуйся, учи́телю благоче́стія; Ра́дуйся, посрами́телю нече́стія.","Ра́дуйся, ра́нами, я́ко у́тварми многоці́нними украше́нний;","Ра́дуйся, кро́вію твоє́ю, я́ко багряни́цею, оді́янний.","Ра́дуйся, всесожже́ніє ту́чноє себі́ Христу́ прине́сший;","Ра́дуйся, за прелюбе́знаго ті Ісу́са ду́шу положи́вий.","Ра́дуйся, страда́нієм сочета́вийся Христу́, ра́ди на́шего спасе́нія расп'я́тому;","Ра́дуйся, ликовству́яй в черто́зі небе́снаго Домовлади́ки.","Ра́дуйся, у престо́ла Бо́жия предстоя́й с го́рніми си́лами;","Ра́дуйся, открове́нним лице́м созерца́яй сла́ву трисія́ннаго Божества́.","Ра́дуйся, от ра́йських висо́т приника́яй благосе́рдієм твої́м к нам земноро́дним;","Ра́дуйся, спаса́яй от бід ві́ру і любо́в к тебі́ іму́щих.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 5","ps":["Богому́дрим пропові́дником апо́столом, за і́м'я Христо́во ра́ни ра́достно приє́мшим, подража́л єси́ во страда́нії твоє́м, Авраа́міє, вопія́ сопроти́в му́чащих тя: Христа́ чту, Єго́ єди́наго люблю́ і умре́ти за Него́ преі́скренні жела́ю, да і с Ним жи́ву во ві́ки, зови́й: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя, злочести́вії мучи́теліє бо́лгаре, непрекло́нна і непобіди́ма іспові́дника Христо́ва, пе́рвіє ру́ці і но́зі твої́ отсіко́ша, та́же і главу́ твою́ честну́ю мече́м от'я́ша, і та́ко до́блестно тече́ніє твоє́ сконча́в, преше́л єси́ к оби́телем небе́сним, от нас же земни́х сли́шиши похвали́ сія́:","Ра́дуйся, іспові́дниче Христо́в непобіди́мий;","Ра́дуйся, адама́нте терпі́нія кріпча́йший.","Ра́дуйся, но́вий му́чениче, дре́внім вели́ким му́чеником равноче́стне;","Ра́дуйся, пресла́вний вінцено́сче, го́ре увінча́нний.","Ра́дуйся, чудотворе́нія благода́тію от Го́спода обогаще́нний;","Ра́дуйся, ціле́б пода́телю всеблаги́й.","Ра́дуйся, во благоуха́нії святи́ні почива́яй;","Ра́дуйся, арома́ти ра́йськими облагоуха́яй ду́ші ві́рних.","Ра́дуйся, істо́чниче даро́в многоразли́чних;","Ра́дуйся, ріко́ приснотеку́щая чуде́с.","Ра́дуйся, милосе́рдія к стра́ждущим сокро́вище неістощи́моє;","Ра́дуйся, боля́щих врачевство́ неоску́дноє.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 6","ps":["Пропові́стся в страні́ Росси́йстій до́блесть по́двига твоєго́ страда́льчеськаго, му́чениче всехва́льний; ті́мже сли́шав твою́ кончи́ну сла́вную і чудотворе́ній твої́х благода́ть, благові́рний вели́кий князь Гео́ргій восхоті́ стяжа́ти тя засту́пника сто́льному гра́ду своєму́ Влади́миру, в онь же мо́щі твоя́ от бо́лгар принести́ потща́ся, зови́й венча́ющему му́ченики Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ пресла́вно чудотворе́нія луча́ми, по пренесе́нії моще́й твої́х честни́х, Авраа́міє свя́те, во град Влади́мир, і́же о́ними сві́тло красу́ється, я́ко сокро́вищем многоці́нним; ми же, чту́щії тя, ра́ку твою́ многоціле́бную любе́зні обстоя́ще, зове́м ті:","Ра́дуйся, гра́да на́шего похвало́ і утвержде́ніє;","Ра́дуйся, оби́телі Богома́тернія, в не́йже почива́єши, при́сноє заступле́ніє.","Ра́дуйся, подвиза́ющимся в ней благода́тноє вспоможе́ніє;","Ра́дуйся, о́них покро́ве і защище́ніє.","Ра́дуйся, неду́гующих ско́ро предста́тельний ціле́бниче;","Ра́дуйся, унива́ющих благонаде́жноє возбужде́ніє.","Ра́дуйся, скорб'я́щих всежела́тельноє утіше́ніє;","Ра́дуйся, ни́щих ізоби́льноє бога́тство.","Ра́дуйся, боля́щих младе́нцев ісціле́ніє;","Ра́дуйся, ізнемога́ющих укріпле́ніє.","Ра́дуйся, ревну́ющих о благоче́стії помо́щниче;","Ра́дуйся, пребива́ющих в пості́ і моли́тві споспі́шниче.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 7","ps":["Хотя́ человіколю́бець Госпо́дь яви́ти щедро́т Свої́х оби́ліє страні́ Росси́йстій, дарова́ нам тебе́ страстоте́рпця но́ваго і моли́твенника богоприя́тнаго, чуде́с благода́ть істоча́юща і неду́жних безме́здно врачу́юща; ті́мже благодари́м тобо́ю благоді́ющаго нам Го́спода і сві́тло пра́зднуєм честни́х моще́й твої́х пренесе́ніє, к ним с любо́вію припа́дающе і Христу́ зову́ще: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя му́ченика і до́бляго страда́льця, Христо́ва іспові́дника і чудотво́рця сла́внаго, любо́вію ублажа́єм, і ра́дующеся о твоє́м к нам прише́ствії, глаго́лем:","Ра́дуйся, денни́це лучеза́рная, от бо́лгар во Влади́мир град прите́кшая;","Ра́дуйся, лучу́ немерца́ющий со́лнця пра́вди Христа́.","Ра́дуйся, уго́дниче Госпо́день, преди́вний в чудесі́х;","Ра́дуйся, пра́ведниче, просла́вленний на небесі́ і на землі́.","Ра́дуйся, нетлі́нієм моще́й твої́х в і́стині воскресе́нія ме́ртвих увіря́яй;","Ра́дуйся, о́браз безсме́ртія в сме́ртнім тілесі́ показу́яй.","Ра́дуйся, я́ко тебі́ дана́ бисть благода́ть за ни моли́тися і возбужда́ти нас ко благи́м діло́м;","Ра́дуйся, я́ко і по преставле́нії твоє́м благодія́ніє тре́бующим подава́єши.","Ра́дуйся, от смертоно́сних язв і болі́зней притека́ющих к тебі́ сохраня́яй;","Ра́дуйся, бе́дствующим і оби́димим помога́яй.","Ра́дуйся, боголюби́вих душ непости́дноє упова́ніє;","Ра́дуйся, лю́б'ящих тя при́сноє утіше́ніє.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 8","ps":["Стра́нно єсть ви́діти ме́ртвенноє ті́ло, жизнь присносу́щную явля́ющеє, во гро́бі лежа́щеє і неду́ги врачу́ющеє; но, му́чениче Христо́в Авраа́міє, моща́ми твої́ми святи́ми в хра́мі сем почива́яй, ві́руєм несомні́нно, я́ко і ду́хом твої́м не отлуча́єшися от нас недосто́йних, честну́ю ра́ку твою́ с любо́вію обстоя́щих і Христу́ благода́рні зову́щих: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь во ви́шніх єси́, свя́тче Бо́жий, во сві́тлості святи́х торжеству́єши і наслажда́єшися неізрече́нних благ небе́сних; ві́ми же, я́ко і нас земни́х і пе́рстних не забива́єши, но от го́рних висо́т ми́лостивно к нам приника́єши, подвиза́я нас че́ствовати тя си́ми похвала́ми:","Ра́дуйся, благоче́стія утвержде́ніє;","Ра́дуйся, правосла́вія похвало́.","Ра́дуйся, землі́ Россі́йськия благода́тноє осіне́ніє;","Ра́дуйся, гра́да Влади́мира сві́тлоє ра́дованіє.","Ра́дуйся, многострада́льная розго́ виногра́да Христо́ва;","Ра́дуйся, граждани́не го́рняго гра́да, Ієрусали́ма Небе́снаго.","Ра́дуйся, в пресла́вном му́ченичеськом ли́кі пребива́яй;","Ра́дуйся, рая́ жи́телю всеблаже́нний.","Ра́дуйся, Ца́рствія Христо́ва наслі́дниче;","Ра́дуйся, ві́чния блаже́нния жи́зні соприча́стниче.","Ра́дуйся, прибі́жище на́ше і защище́ніє;","Ра́дуйся, ско́роє і безме́здноє неду́гов врачева́ніє.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 9","ps":["Всі А́нгели Небе́снії восприя́ша тя ра́достно во оби́телі ра́йськия, страда́льче богому́дре Авраа́міє, іді́же свята́я твоя́ душа́, огне́м страда́нія іскуше́нная, по́честь побі́дную восприя́т от Христа́ Бо́га на́шего, пра́веднаго мздовоздая́теля подвиза́ющихся за і́м'я Єго́ свято́є на землі́; прославля́я бо їх на Небесі́, с Го́рніми во́ї у Престо́ла Своєго́ предстоя́нія сподобля́єть, іді́же поє́ться Єму́ немо́лчная піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йством злочести́вим і прельще́нієм лука́вим неуловле́н преби́л єси́, страстоте́рпче, ізво́ливий па́че умре́ти, не́же Христа́ і ві́ри в Него́ святи́я отрещи́ся, ті́мже, я́ко до́бляго іспові́дника Христо́ва, ублажа́єм тя і зове́м:","Ра́дуйся, пречу́дноє му́жество яви́вий;","Ра́дуйся, я́ко просвіще́н бил єси́ заре́ю Пресвята́го Ду́ха.","Ра́дуйся, я́ко страх малоду́шний от себе́ отря́сл єси́;","Ра́дуйся, я́ко щито́м ві́ри огради́лся єси́.","Ра́дуйся, неумолка́ющий благові́стниче си́ли Бо́жия, в не́мощі челові́честій соверша́ющіяся;","Ра́дуйся, і́стинний покло́нниче, ду́хом і і́стиною кла́няяйся Творцю́.","Ра́дуйся, му́жу жела́ній духо́вних, взиска́вий Христа́ в страні́ нече́стія магоме́това;","Ра́дуйся, отри́нувий богопроти́вную о́ную пре́лесть.","Ра́дуйся, ку́плю де́явий вре́менную, вку́пі же і ві́чную, небе́сную;","Ра́дуйся, стра́нники і ни́щія пита́вий от трудо́в твої́х пра́ведних.","Ра́дуйся, єле́єм ми́лости умаще́нная главо́;","Ра́дуйся, горо́ доброді́телей, ороше́нная кро́ве страда́льчеськия ізлія́нієм.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 10","ps":["Спасти́ся нам преі́скренні жела́я, мо́лишися за нас го́ре у Престо́ла Бо́жия, страда́льче Христо́в Авраа́міє, і твої́ми моли́твами посо́бствуєши нам в стра́нствії многотру́днем земна́го житія́, є́же в покая́нії і благоче́стії сконча́ти, да сподо́бимся с тобо́ю воспіва́ти Христу́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну защище́нія стяжа́вше твоя́ святи́я моли́тви, Авраа́міє чу́дне, ра́дуємся грі́шнії і чтем любо́вію па́м'ять твоєго́ усікнове́нія і моще́й твої́х святи́х пренесе́нія, зову́ще:","Ра́дуйся, великоімени́тий наш засту́пниче;","Ра́дуйся, небожи́телю богопросвіще́нний.","Ра́дуйся, чудотво́рче ди́вний і ми́лостивий;","Ра́дуйся, благи́й послу́шателю су́щих в ско́рбіх.","Ра́дуйся, предваря́яй проше́нія призива́ющих тя в біда́х;","Ра́дуйся, грі́шних ко ісправле́нію приведе́ніє.","Ра́дуйся, ми́ро враче́бноє неду́гом многоразли́чним;","Ра́дуйся, не то́кмо тіле́сних, но і душе́вних болі́зней ізря́дний ціли́телю.","Ра́дуйся, духо́в нечи́стих от челові́ков прогони́телю;","Ра́дуйся, даро́в благода́тних незави́стний пода́телю.","Ра́дуйся, благоуха́нієм моще́й твої́х услажда́яй ду́ші на́ша;","Ра́дуйся, чудеси́ твої́ми утвержда́яй нас во і́стині святи́я правосла́вния ві́ри.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє і похвалу́ сію́ смире́нную не пре́зри, му́чениче; се бо ві́рою і любо́вію к тебі́ подвиза́ємі, ра́ку моще́й твої́х собо́рні обстоя́ще, ублажа́єм тя, засту́пника на́шего, і мо́лимся: моли́ся за ни ви́ну ко Го́споду, ві́ми бо к Нему́ твоє́ невозбра́нноє дерзнове́ніє і твої́х моли́тв благода́тноє ді́йство. Іму́ще такова́го предста́теля, благода́рно зове́м ди́вному во святи́х Свої́х Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоно́сним Тро́їчеським сія́нієм го́ре осія́нний, Авраа́міє свя́те, озари́ на́ша сердця́, тьмо́ю гріхо́вною покрові́нная; да єле́єм благи́х діл возже́гши уга́сшия світи́льники на́ша, сподо́бимся бра́чнаго Христо́ва черто́га, іді́же ти вселя́єшися со святи́ми і сли́шиши сія́ от нас благохвале́нія:","Ра́дуйся, Бо́гом да́нний покрови́телю наш;","Ра́дуйся, ангелоподо́бний челові́че.","Ра́дуйся, нищелю́бче благослове́нний;","Ра́дуйся, странноприї́мниче, дре́внему о́ному пра́отцю Авраа́му уподобля́яйся.","Ра́дуйся, я́ко рука́ твоя́ ізоби́льно помога́ше нужда́ющимся;","Ра́дуйся, я́ко му́дре расточа́л єси́ бога́тство тлі́нноє.","Ра́дуйся, о́ноє преміни́вий на нетлі́нния небе́сния бла́га;","Ра́дуйся, наслажда́яйся блаже́нства ми́лостивих.","Ра́дуйся, предстоя́й А́гнцю Бо́жию в лиці́ му́ченичестім;","Ра́дуйся, ликовству́яй в селе́нії пра́ведних.","Ра́дуйся, во страда́нії твоє́м до́блесть чу́дную яви́вий;","Ра́дуйся, я́зви Го́спода Ісу́са Христа́ на ті́лі твоє́м носи́вий.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 12","ps":["Благода́ть і ми́лость іспроси́ нам у Христа́ і Бо́га на́шего, святи́й і сла́вний страстоте́рпче Авраа́міє; ві́руєм бо несомні́нно, я́ко є́же про́сиши, да́руєть ті всеблаги́й Влади́ка; ті́мже і о нас грі́шних умоля́ти не преста́й Єго́ благоутро́біє і іспроси́ нам дар коєму́ждо благопотре́бен, да зове́м всіх благи́х вино́внику і даропода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м твою́ страда́льчеськую кончи́ну, сла́вим твої́х честни́х моще́й от бо́лгар во Влади́мир пренесе́ніє, от ни́хже то́ки чуде́с істоча́єши непреста́нно, подвиза́я зва́ти тебі́:","Ра́дуйся, арха́нгелов і а́нгелов сослужи́телю;","Ра́дуйся, патріа́рхов і проро́ков спредстоя́телю.","Ра́дуйся, апо́столов єдиноревни́телю;","Ра́дуйся, му́чеников красото́.","Ра́дуйся, святи́телей і преподо́бних собесі́дниче;","Ра́дуйся, пра́ведних і всіх святи́х сожи́телю.","Ра́дуйся, я́ко сви́ше чуде́с дія́нії укра́сился єси́;","Ра́дуйся, в честни́х і многоціле́бних мощеіх свої́х ви́ну с на́ми пребива́яй.","Ра́дуйся, о́ними пресла́вно чудоді́йствуяй;","Ра́дуйся, отра́до на́ша і в ско́рбіх утіше́ніє.","Ра́дуйся, неду́гующих ісціле́ніє;","Ра́дуйся, согріша́ющих ісправле́ніє.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 13","ps":["О пресла́вний страстоте́рпче Христо́в Авраа́міє, ми́лостиво приє́мши сіє́ ма́лоє моле́ніє на́ше, умоли́ Царя́ ца́рствующих і Го́спода госпо́дствующих, Христа́ Бо́га на́шего, ізба́вити нас от вся́кия ско́рби і ну́жди в жи́зні сей і муче́ній ві́чних по сконча́нії на́шем, да сподо́бимся в Ца́рствії Небе́снім вку́пі с тобо́ю пі́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов сожи́тель і челові́ков засту́пник воі́стину яви́лся єси́, му́чениче достохва́льне, благоволе́нієм всіх Творця́ Христа́ Бо́га, Єго́же возлюби́л єси́ і за Него́ же пострада́л єси́ да́же до кро́ве во іспові́данії непоколеби́мім. Ті́мже прийми́ от нас сія́ хвале́нія:","Ра́дуйся, звіздо́ пресві́тлая благоче́стія;","ра́дуйся, світи́ло, во тьмі нече́стія пресла́вно возсія́вшеє.","Ра́дуйся, злові́рія магоме́това обличи́телю;","Ра́дуйся, ві́ри христия́нськия небоя́зненний пропові́дниче.","Ра́дуйся, Єва́нгельськаго уче́нія до́брий послу́шателю;","Ра́дуйся, зако́на Госпо́дня теплі́йший храни́телю.","Ра́дуйся, ку́плю вре́менную преміни́вий на стяжа́ніє ві́чноє небе́сноє;","Ра́дуйся, ві́ри Христо́ви би́сер многоці́нен стяжа́вий.","Ра́дуйся, Христо́вим уче́нієм ду́шу твою́ просвіти́вий;","Ра́дуйся, удосто́ївийся благода́тнаго осіне́нія сви́ше.","Ра́дуйся, яви́вийся доброді́телей жили́ще, преукра́шенноє чистото́ю;","Ра́дуйся, Ду́ха Свята́го оби́тель прекра́сная.","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Кондак 1","ps":["Ізбра́нний страстоте́рпче Христо́в і чудотво́рче преди́вний, во страда́нії твоє́м віне́ць приє́мий от руки́ Вседержи́теля і со а́нгели предстоя́й Єго́ престо́лу, пі́сньми восхваля́єм тя любо́вію і мо́лим ті ся, моли́твами твої́ми от вся́ких бід і скорбе́й свобожда́й нас, тебі́ зову́щих:","Ра́дуйся, му́чениче і чудотво́рче Авраа́міє."]},{"h":"Молитва","ps":["Святи́й му́чениче Авраа́міє, до́блій во́їне Христа́ Царя́ Небе́снаго, в ско́рбіх і напа́стіх пресла́вний наш помо́щниче і защи́тниче! Нічто́же возмо́же отлучи́ти тя от любве́ ко Го́споду Ісу́су: ні ле́стния обіща́нія благ вре́менних, ні преще́нія, ні му́ки от злих враго́в святі́йшия Христо́ви ві́ри; ти, я́ко лев, ізше́л єси́ на брань проти́ву волко́в ми́сленних, духо́в зло́би, подви́гших на тя, ра́ди до́браго твоєго́ іспові́данія, єдиноплеме́нний тебі́ наро́д болга́рський, і, я́ко о́гненная стріла́, тіх порази́л єси́ си́лою благода́ті Свята́го Ду́ха, і крі́пкия, я́ко смерть, любве́ твоєя́ к Бо́гу. А́ще і пролія́л єси́ кров твою́ за Христа́ Бо́га на́шего, погуби́во вре́менную жизнь, оба́че безсме́ртною душе́ю, я́ко оре́л, воспари́л єси́ в го́рнія оби́телі Отця́ на́шего, наслі́довав там ві́чную жизнь, сла́ву і блаже́нство неізрече́нноє, і оста́вив нам нетлі́нния оста́нки твоя́, я́ко крин многоці́нний і благоуха́нний. Ві́руєм, страстоте́рпче святи́й, я́ко предстоя́ со а́нгели і всі́ми святи́ми Престо́лу Сла́ви Триіпоста́снаго Бо́га, усе́рдния і богоприя́тния возно́сиши моли́тви не то́кмо о нас, о святі́й оби́телі сей і гра́де на́шем, но і о всей святі́й Христо́вій Це́ркві і о правосла́вній Ру́ськой держа́ві. Ві́руєм, пресла́вний чудотво́рче, я́ко ти, си́лою всемогу́щаго Го́спода Ісу́са Христа́, чрез святи́я мо́щі твоя́, істоча́єши оби́льния да́ри благода́тния по́мощі во спасе́ніє всім с ві́рою к тебі́ притека́ющим, найпа́че же іспра́шиваєши кончи́ну с покая́нієм тебі́ чту́щим, і благосе́рдно помога́єши немощни́м младе́нцем, да всі от ма́ла до вели́ка єдиноду́шно прославля́єм неісповіди́моє вели́чіє бла́гости Бо́жієй. Тім же ві́рою і любо́вію ко святи́м моще́м твої́м припа́дающе і благогові́йно о́ния лобиза́юще, умоля́єм тя, до́брий на Небесі́ наш моли́твенниче і засту́пниче, помога́й нам грі́шним і смире́нним твої́ми моли́твами во всіх ско́рбіх, ну́ждах і обстоя́ніїх на́ших, сохраня́й нас, святу́ю оби́тель сію́ і град сей от вся́каго зла і вся́кия напа́сти, найпа́че же споспі́шествуй ві́чному спасе́нію на́шему і всіх прося́щих от тебе́ по́мощі і заступле́нія. Єй, смире́нно мо́лим тя, уго́дниче Бо́жий, моли́ Христа́ Бо́га на́шего, да дасть Он мир і тишину́ всім правосла́вним христия́ном і да отврати́ть от нас вся́кий гнів, на ни дви́жимий, да ізба́вить нас от сіте́й вра́жиїх, томле́нія во у́зах гріха́ і муче́ній а́дових, і да сподо́бит нас недосто́йних одесну́ю Себе́ ста́ти на суді́ Своє́м пра́веднім і вни́ти во ві́чний поко́й святи́х Єго́, іді́же пра́зднующих глас непреста́нний і неізрече́нная сла́дость зря́щих добро́ту лиця́ Єго́; і та́ко возмо́жем с тобо́ю і всі́ми святи́ми прославля́ти Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь, благові́рнії лю́діє, соше́дшеся, / восхва́лим до́бляго сего́ му́ченика і страда́льця Авраа́мія, / сей бо, укріпля́єм си́лою Бо́жиєю, / ду́шу свою́ положи́ за Христа́, / мно́го пострада́в от злові́рних болга́р. / Сего́ ра́ди от Го́спода віне́ць прия́т / і ни́ні предстої́ть Єму́ / і мо́литься о гра́ді сем // і о всіх нас, чту́щих па́м'ять єго́."]},{"h":"Кондак, глас 8","ps":["Я́ко многоці́нноє сокро́вище, / принесе́но бисть от Болга́рськия страни́ во град Влади́мир / пречестно́є ті́ло твоє́, му́чениче Авраа́міє, / і́мже подає́ши всім чту́щим пресла́вную па́м'ять твою́ оби́ліє ісціле́ній, / предстоя́ на Небесі́ Христу́ Бо́гу // і моля́ Єго́ о спасе́нії душ на́ших."]},{"h":"Інший кондак, глас 3","ps":["Укріпи́вся, сла́вне, любо́вію Госпо́днею / і Того́ честни́й Крест на ра́мо взем, і́го Госпо́днє, / посрами́л єси́ дия́воля кова́рствія / і пострада́л єси́ да́же до сме́рти, / і сего́ ра́ди, досточу́дне, яви́ся страда́лець вели́к, Авраа́міє, / і ору́жником храбротаї́нник // і уча́стник Бо́жия благода́ті."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпче святи́й Авраа́міє, / і чтим честна́я страда́нія твоя́, / я́же за Христа́ // претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст святому благовірному великому князю Олександру Невському","e":"Akathist to the Holy Right-Believing Grand Prince Alexander Nevsky","secs":[{"h":"Кондак 1","ps":["Ізбра́нному воєво́ді землі́ Россі́йськия, сві́тлому украше́нію Це́ркве Правосла́вния, свято́му благові́рному вели́кому кня́зю Алекса́ндру Не́вскому, похва́льная воспису́юще, я́ко ві́рою враги́, ви́димия же і неви́димия, побіди́вшему, і во ві́рі своє́й, по рече́нію апо́столову, доброді́тель, в доброді́телі же ра́зум, в разумі́ же воздержа́ніє, во воздержа́нії же терпі́ніє, в терпі́нії же благоче́стіє, братолю́біє і любо́в яви́вшему со умиле́нієм і ра́достію возопії́м:","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Ікос 1","ps":["Со А́нгели і всі́ми святи́ми предстої́ши ни́ні Христу́, блаже́нно Алекса́ндре, моля́ся о любо́вію чту́щих тя: ті́мже, помина́юще, я́ко, ізмла́да Христа́ возлюби́в, к небе́сним ду́хом приліпи́лся єси́, бесплотних подража́в житію́, ублажа́єм тя, вопію́ще:","Ра́дуйся, ко́рене благочести́ваго о́трасле пречестна́я;","Ра́дуйся, благові́рія предко́в наслі́дниче.","Ра́дуйся, доброді́телей отця́ боголюби́ваго подража́телю;","Ра́дуйся, кро́тости і благоче́стія ма́терняго преє́мниче.","Ра́дуйся, вождю́ к Небесе́м стада́ своєго́ христолюби́ваго;","Ра́дуйся, в житії́ всіх рабо́в Бо́жиїх дру́же і ревни́телей благоче́стія собесі́дниче.","Ра́дуйся, преподо́бних ли́ка богосві́тлаго соприча́стниче;","Ра́дуйся, ві́ри Христо́ви непобіди́мий іспові́дниче.","Ра́дуйся, во́лею му́чениче, сликовству́яй ни́ні со́нму му́чеников добропобі́дному;","Ра́дуйся, христия́нськаго упова́нія і любве́ всім нам ді́вственний пропові́дниче.","Ра́дуйся, уста́вов і чи́на церко́внаго благолі́пнаго ревни́телю;","Ра́дуйся, ві́рних чад Це́ркве і уго́дников Бо́жиїх сонаслі́дниче.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 2","ps":["Ви́дівше лі́поту лиця́ і тіле́снаго во́зраста твоєго́, новогра́дстії лю́діє ра́довахуся і сла́вляху Бо́га, взира́юще на тя: ми же, помина́юще светлейшия па́че со́лнця доброді́телі твоя́, блаже́нне Алекса́ндре, просла́вившему тя Го́сподеві пої́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́л єси́, богому́дре Алекса́ндре, я́ко прехо́дить о́браз ми́ра сего́, єди́но же єсть на потре́бу челові́ком, є́же благоугоди́ти Го́сподеві: сего́ ра́ди ізмла́да от любве́ к ми́ру і я́же в ми́рі уклони́лся єси́, вожделі́в же зді су́щими стяжа́ти небе́сная, я́ко ві́рний раб Го́споду во всем житії́ нелі́ностно послужи́л єси́. Ті́мже вопіє́м ті:","Ра́дуйся, подви́жниче ві́ри, угожде́ніє Бо́гу па́че всего́ предизбравий;","Ра́дуйся, подо́бні Авраа́му во всем житії́ непоро́чно пред Бо́гом пожи́вий.","Ра́дуйся, Ісаа́ково послуша́ніє показавиї;","Ра́дуйся, путе́м Іа́ковля смиренному́дрія ходи́вий.","Ра́дуйся, Іо́сифову чистоту́ і целому́дріє стяжа́вий;","Ра́дуйся, Мойсе́єву любо́в к лю́дем свої́м в себі́ яви́вий.","Ра́дуйся, я́коже Самуї́л чи́ста себе́ от вся́каго любостяжа́нія соблюда́вий;","Ра́дуйся, кро́тостію Дави́довою враги́ своя́ побіди́вий.","Ра́дуйся, Петро́вой пла́менней ві́рі поревнова́вий;","Ра́дуйся, с Па́влом і́гу Христо́ву себі́ поработи́вий.","Ра́дуйся, богому́дріє Іоа́нново по́двигом поуче́нія в сло́ві Бо́жиєм сниска́вий;","Ра́дуйся, мно́гих святи́х доброді́телі в себі́ совокупи́вий.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 3","ps":["Си́лою ві́ри стяжа́л єси́, блаже́нне Алекса́ндре, ви́сшеє любому́дріє, єго́же ра́ди, презира́я плоть, приліжа́л єси́ о душі́ безсме́ртній: ті́мже ублажа́юще тя, я́ко стяжа́вша ни́ні безсме́ртіє, вопіє́м просла́вившему тя Христу́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй всегда́ пред очи́ма свої́ма Го́спода, тре́звенно пожи́л єси́, блаже́нне Алекса́ндре, і вся я́же твори́л єси́, творя́ во сла́ву Бо́жию, угоди́л єси́ Бо́гу, Єму́же предстої́ши ни́ні с ли́ки от ві́ка угоди́вших: ті́мже ра́дующеся о тебі́, зове́м ті:","Ра́дуйся, і́стиннаго трезві́нія подви́жниче;","Ра́дуйся, спаси́тельнаго созерца́нія люби́телю.","Ра́дуйся, наста́вниче наш в по́двигі от ми́ра удале́нія;","Ра́дуйся, стяжа́телю соверше́ннаго да́ра бо́дрственнаго себі́ внима́нія.","Ра́дуйся, вся́каго безслове́снаго вожделі́нія тве́рдий противобо́рниче;","Ра́дуйся, благоче́стія до́брий подви́жниче, преуспі́вий в разумі́ і дія́нії.","Ра́дуйся, я́ко си́лою моли́тви препобіди́л єси́ диявольськая іскуше́нія;","Ра́дуйся, я́ко себе́ от гріха́ огради́л єси́ послі́дніх воспомина́нієм.","Ра́дуйся, я́ко возлюби́л єси́ душе́ю є́же о небе́сних помишле́ніє;","Ра́дуйся, я́ко преуспі́л єси́ в нелі́ностних я́же к Бо́гу моли́твенних предстоя́ніїх.","Ра́дуйся, я́ко все житіє́ своє́ освяща́л єси́ непреста́нним І́мене Бо́жия призива́нієм;","Ра́дуйся, я́ко угожда́л єси́ Го́сподеві вся́ким благоугожде́нієм.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 4","ps":["Бу́ри іскуше́ній воздвиго́ша вразі́ і проти́ву тебе́, блаже́нне Алекса́ндре. Ти же препобіди́л єси́ сія́ си́лою благода́ті Христо́ви: ті́мже ни́ні, к ти́хому приста́нищу прите́к, с ли́ки іскуше́нних в ми́рі, побіди́вших же мир, вопіє́ши Христу́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав Па́вла, глаго́люща: \"Всяк подвиза́яйся от всіх воздержи́ться\", вся в уме́ти вміни́л єси́, блаже́нне Алекса́ндре, да Христа́ приобря́щеши: по́двигами же отверже́нія себе́ і ко благи́м ді́лом принужде́нія стяжа́л єси́ свобо́ду сла́ви чад Бо́жиїх: ті́мже ублажа́юще тя, вопіє́м ті такова́я:","Ра́дуйся, о́браз отверже́нія себе́ нам показа́вий;","Ра́дуйся, ноше́нію креста́ в послі́дованії Христу́ нас научи́вий.","Ра́дуйся, плоть со страстьми́ і похотьми́ єя́ попра́вий;","Ра́дуйся, житіє́м твої́м суєту́ ми́ра обличи́вий.","Ра́дуйся, вся́коє пристра́стіє земно́є от себе́ отгна́вий;","Ра́дуйся, ра́зум свой в послуша́ніє ві́ри пліни́вий.","Ра́дуйся, во́лею своє́ю благо́є і́го за́повідей Христо́вих под'явий;","Ра́дуйся, се́рдце своє́ от вся́кия стра́сти душевре́дния чи́сто сохрани́вий.","Ра́дуйся, себе́ Бо́гу всесоверше́нні преда́вий;","Ра́дуйся, чрез все житіє́ своє́ Бо́гу послужи́вий.","Ра́дуйся, соверше́нієм за́повідей любо́в к себі́ Бо́жию стяжа́вий;","Ра́дуйся, наслі́діє Ца́рствія благоугожде́нієм Бо́гу улучи́вий.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю преше́л єси́ в ми́рі, блаже́нне Алекса́ндре, блиста́ющ сла́вою і доброді́телію: ті́мже ни́ні сія́єши на Небесі́х сла́вою ві́чною с ли́ки пра́ведник, с ни́миже ви́ну воспіва́єши Христу́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя, блаже́нне Алекса́ндре, ніколи́же во бра́ніх побіжда́єма, всегда́ же побіжда́юща, неві́рнії єди́наго і́мене твоєго́ устраша́хуся, ми же, помина́юще іспо́лненноє ві́ри му́жество твоє́, ублажа́єм тя, глаго́люще:","Ра́дуйся, до́блественний в защи́ту ві́ри і Це́ркве воі́телю;","Ра́дуйся, своєя́ землі́ му́жественний защити́телю.","Ра́дуйся, наві́тов вра́жиїх му́дрий разори́телю;","Ра́дуйся, ми́ра безпомо́щних си́льний огради́телю.","Ра́дуйся, во́їнства сві́йськаго на брега́х Не́вских сла́вний побіди́телю;","Ра́дуйся, безопа́сности всея́ сі́верния страни́ землі́ Россі́йськия охрани́телю.","Ра́дуйся, злих ко́зней інові́рія, подви́гших чужду́ю рать на зе́млю на́шу, разруши́телю;","Ра́дуйся, зако́нов пра́вди богоукріпля́ємий утверди́телю.","Ра́дуйся, Пско́ва, оте́чества святи́я О́льги, свободи́телю;","Ра́дуйся, ненави́дівших ми́ра умири́телю.","Ра́дуйся, бу́йства неустро́єнния в ти́я дні Литви́ укроти́телю;","Ра́дуйся, во всіх сих бра́ніх христолюби́ваго во́їнства своєго́ му́дрий предводи́телю.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 6","ps":["Пропові́дника кро́тости і терпі́нія яви́л єси́ себе́, блаже́нне Алекса́ндре, посреди́ пресла́вних побі́д твої́х: ті́мже і стяжа́л єси́ сугу́бий віне́ць от Царя́ Христа́, Єму́же предстої́ши ни́ні, вопія́: Аллилу́я."]},{"h":"Ікос 6","ps":["Провозсія́л єси́, блаже́нне Алекса́ндре, па́че му́жества, терпі́нієм твої́м, єго́же стяжа́л єси́, взира́я на Нача́льника ві́ри і Соверши́теля Ісу́са, І́же вмі́сто предлежа́щия єму́ ра́досте претерпі́ Крест: ті́мже восхваля́юще тя, усе́рдно вопіє́м:","Ра́дуйся, до конця́ в по́двизіх служе́нія Бо́гу претерпі́вий;","Ра́дуйся, терпі́нію Христо́ву ві́рно подража́вий.","Ра́дуйся, си́лу за́повіді Христо́ви, я́же о любві́ ко враго́м, прему́дро уразумі́вий;","Ра́дуйся, і согрі́шшим проти́ву тебе́ ізба́вленним тобо́ю лю́дем любо́в і́стинную показа́вий.","Ра́дуйся, во іскуше́нії от наро́да своєго́ хи́трость лукавого прозрі́вий;","Ра́дуйся, ми́рним отби́тієм свої́м із землі́ своєя́ зло́бу врага́ попра́вий.","Ра́дуйся, і во всем житії́ своє́м ухищре́нія сатани́ проразумі́вий;","Ра́дуйся, зло́є благи́м, по апо́столу, ви́ну препобіжда́вий.","Ра́дуйся, па́ки, в годи́ну ско́рби, в по́мощ оскорби́вшему тя Нову́граду предуспі́вий;","Ра́дуйся, сего́ ра́ди пла́менную любо́в от наро́да своєго́ себі́ сниска́вий.","Ра́дуйся, Бо́жия посіще́нія, болі́зні і лише́нія, со упова́нієм терпі́вий;","Ра́дуйся, сего́ ра́ди сві́тлий віне́ць от Го́спода стяжа́вий.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 7","ps":["Хотя́й провозсія́ти тебі́ всі́ми доброді́тельми, блаже́нне Алекса́ндре, Влади́ка Христо́с призва́л єсть тебе́ к служе́нію лю́дем свої́м во дні посіще́нія: ти же притяжа́л єси́ к терпі́нію смире́ніє, єго́же ра́ди ни́ні превознесе́н єси́, предстоя́ Бо́гу с пі́снію: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно бі ви́діти, ка́ко непобіди́мий воі́тель смире́нно преклоня́єть главу́ свою́ пред неві́рними, ї́хже посла́ Госпо́дь на лю́ди своя́ ра́ди гріх їх: ди́вно же єсть і воспом'яну́ти непобіди́моє смире́ніє твоє́, блаже́нне Алекса́ндре, і́мже і Го́сподеві благоугоди́л єси́, і лю́ди своя́ спасл єси́. Ті́мже благода́рно вопіє́м ті:","Ра́дуйся, смире́нія Госпо́дня подража́телю;","Ра́дуйся, подоба́ющаго богопоста́вленним власте́м почита́нія учи́телю.","Ра́дуйся, вся́каго превозноше́нія противобо́рче;","Ра́дуйся, і́стиннаго послуша́нія подви́жниче.","Ра́дуйся, всім нам о́бразе ві́рнаго Бо́гу служе́нія;","Ра́дуйся, нача́льствующим наста́вниче в богоприя́тном лю́дем предстоя́нії.","Ра́дуйся, подвла́стних руководи́телю в богозапові́данном предержащим власте́м повинове́нії;","Ра́дуйся, я́ко мно́гажди ра́ди бла́га люде́й свої́х путьше́ствовал єси́ к безбо́жним, ні во что́же вміня́я я́же от них іспита́нія.","Ра́дуйся, я́ко не устраши́лся єси́, призва́в Бо́га, прийти к Ба́тиєві, ісполня́я єго́ велі́ніє;","Ра́дуйся, я́ко мно́гащи воспринима́л єси́ на себі́ стра́шний отві́т о неразу́мних наро́да своєго́ воста́ніїх.","Ра́дуйся, я́ко огради́л єси́ лю́ди твоя́ от зловре́днаго с неві́рними обще́нія;","Ра́дуйся, я́ко му́дре огради́л єси́ в землі́ своє́й оте́чеськия до́блести і преда́нія.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 8","ps":["Стра́нничеськоє житіє́ преше́л єси́ на землі́, блаже́нне Алекса́ндре, не ві́дий поко́я в труді́х свої́х і не іми́й зді пребива́ющаго гра́да, но гряду́щаго взиску́яй: сего́ ра́ди ни́ні, блаже́нне, всели́лся єси́ во ві́чних оби́теліх, ви́ну поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Все́ю душе́ю послужи́в Го́споду і всім житіє́м свої́м благоугоди́в єму́, просла́вился єси́ благоче́стієм, єго́же ра́ди і іспові́дник яви́лся єси́ ві́ри Христо́ви, блаже́нне Алекса́ндре: помина́юще у́бо по́двиг іспові́дничества твоєго́, вопіє́м ті:","Ра́дуйся, зло́би неві́рних не устраши́вийся;","Ра́дуйся, тва́ри па́че Созда́вшаго не послужи́вий.","Ра́дуйся, со́лнцю і огню́ в ста́ні безбо́жних не поклони́вийся;","Ра́дуйся, ві́ру свою́ во іскуше́нії сохрани́вий.","Ра́дуйся, велі́нію безбо́жному не покори́вийся;","Ра́дуйся, тве́рдий пропові́дник ві́ри пред неві́рними себе́ яви́вий.","Ра́дуйся, с сугу́бою сла́вою, по іспові́данії своє́м, в зе́млю свою́ возврати́вийся;","Ра́дуйся, во всем житії́ ві́рним ві́рі отце́в преби́вий.","Ра́дуйся, от ле́сти інові́рія прему́дре уклони́вийся;","Ра́дуйся, лука́вство пропові́дников лжеві́рія я́ві обличи́вий.","Ра́дуйся, тве́рдий защи́тник правові́рія яви́вийся;","Ра́дуйся, лжеслове́сіє враго́в Правосла́вія сло́вом здра́вим препобіди́вий.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 9","ps":["Всего́ себе́ повину́в Бо́гові, я́ко раб благи́й і ві́рний послужи́л єси́ Єму́, блаже́нне Алекса́ндре, па́че све́рстник твої́х для землі́ твоєя́ потруди́вся: ті́мже і вни́ти сподо́бился єси́ в ра́дость Го́спода своєго́, Єму́же предстої́ши ни́ні, со А́нгели поя́: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствующий язи́к не возмо́гл би восхвали́ти діла́ твоя́, блаже́нне Алекса́ндре, я́же соверши́л єси́, полага́я по бра́тії ду́шу свою́: смире́нно у́бо помина́юще сицева́я ісправле́нія твоя́, умиле́нную піснь прино́сим ті, глаго́люще:","Ра́дуйся, братолю́бія христия́нськаго приі́скренній ревни́телю;","Ра́дуйся, Мойсе́єви і Па́влови любве́ ко бра́тії подража́телю.","Ра́дуйся, за́повідей Христо́вих я́же о любві́ ві́рний ісполни́телю;","Ра́дуйся, і всіх нас в любві́ к присним ди́вний наста́вниче.","Ра́дуйся, приме́ром свої́м па́че сло́ва яви́вийся стяза́ющихся о наслі́дії бра́тії свої́х примири́тель;","Ра́дуйся, о бла́гі наро́да усе́рдно в житії́ своє́м пеки́йся.","Ра́дуйся, о́бщаго ми́ра во днех свої́х устрої́телю;","Ра́дуйся, ізгна́ннаго стра́хом наше́ствій тата́рських наро́да своєго́ собира́телю.","Ра́дуйся, безпомо́щних при́сний защити́телю;","Ра́дуйся, ни́щих і а́лчущих пита́телю.","Ра́дуйся, си́рих си́льний покрови́телю;","Ра́дуйся, і ни́ні всіх скорб'я́щих і нужда́ющихся мо́щний пред Господом предста́телю.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу свою́, ві́дий же, я́ко не іму́щему любве́ к Бо́гу ники́їми же по́двигами і доброді́тельми улучи́ти спасе́ніє возмо́жно єсть, стяжа́л єси́ віне́ць доброді́телей, є́же єсть любо́в к Бо́гу, Єму́же предстоя́ ни́ні, ра́достно вопіє́ши: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго возлюби́в от всего́ се́рдця твоєго́, і от всея́ душі́ твоєя́, і все́ю ми́слію твоє́ю, прине́сл єси́ Єму́, блаже́нне Алекса́ндре, посліди́ многоразли́чних приноше́ній ві́ри і усе́рдія, себі́ самаго́ в же́ртву живу́, свя́ту, благоуго́дну: ті́мже ублажа́юще тя, вопіє́м ті:","Ра́дуйся, в житії́ своє́м всі́ми богоуго́дними ді́ли Го́сподеві послужи́вий;","Ра́дуйся, обі́тами і́ночества свято́є житіє́ своє́ увінча́вий.","Ра́дуйся, мно́гі хра́ми Бо́жії, безбо́жними раззоренния, обнови́вий;","Ра́дуйся, к просія́нію по́двигов по́стничества оби́телі святи́я созидавий.","Ра́дуйся, подвиза́ющихся ізмла́да в благоче́стії ра́ди Бо́га возлюби́вий;","Ра́дуйся, а́нгельський о́браз і себі́ чи́стою душе́ю предизбравий.","Ра́дуйся, в коне́ць житія́ своєго́ всего́ себе́ Бо́гу посвятивий;","Ра́дуйся, прия́тієм схи́ми, с но́вим і́менем Алексі́я, всесоверше́нні себе́ Бо́гу преда́вий.","Ра́дуйся, обі́том ді́вства чистоту́ се́рдця своєго́ яви́вий;","Ра́дуйся, обі́том нестяжа́нія висоту́ ду́ха своєго́ показа́вий.","Ра́дуйся, обі́том послуша́нія всеці́лоє служе́ніє своє́ Єди́ному Бо́гу во ві́ки утверди́вий;","Ра́дуйся, к вінцю́ му́драго і блага́го кня́зя мзду і́нока притяжа́вий.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 11","ps":["Пі́ніє погреба́льноє слеза́ми растворя́шеся у гро́ба твоєго́, блаже́нне Алексадре; лю́діє твої́ пла́кахуся о тебі́, со́лнце землі́ Ру́ськия, в полу́дні заше́дшем, і рида́нія прерива́ху умиле́нную піснь їх к Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ сла́ви небе́сния осія́ тя вско́рі, блаже́нне Алекса́ндре, утіша́я плачущия лю́ди твоя́: ті́мже ви́дяще при гро́бі твоє́м зна́менія і чудеса́, си́нове росси́йстії досто́йні призива́ху тя, я́ко в моли́твах предста́теля; ми же, понимающе ско́роє заступле́ніє твоє́, вопіє́м ті:","Ра́дуйся, уго́дниче Бо́жий, в само́м погребе́нії прославле́ніє от Бо́га получи́вий;","Ра́дуйся, ско́рий предста́телю наш, єго́же призива́ху отці́ на́ші в ну́ждіх і озлобле́ніїх.","Ра́дуйся, в борбі́ с татари кня́зю Дими́трію Донсько́му вспоможе́ніє яви́вий;","Ра́дуйся, царю́ Іоа́нну і каза́нці одолі́ніє ісхода́таївий.","Ра́дуйся, ісціле́нія многоразли́чния всім подава́яй;","Ра́дуйся, сліпи́м зрі́ніє моли́твою твоє́ю возвраща́яй.","Ра́дуйся, хроми́м, припадающим ко гро́бу твоєму́, хожде́ніє да́руяй;","Ра́дуйся, разсла́бленних неможе́ніє врачу́яй.","Ра́дуйся, одержи́мим от бісо́в свобожде́ніє подава́яй;","Ра́дуйся, безнаде́жних наде́ждою спасе́нія оживля́яй.","Ра́дуйся, в погу́бльших ра́зум разумі́ніє возставля́яй;","Ра́дуйся, от гро́ба твоєго́ многообра́зния чудотворе́нія при́сно істоча́яй.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 12","ps":["Благода́ть позна́вше, живу́щую в нетлі́нних мощеіх твої́х, лю́діє влади́мирстії с любо́вію прихожда́ху ко святі́й ра́ці твоє́й і, ра́достно лобиза́юще ю, сла́вляху о тебі́ Бо́га, прославля́ющаго святи́я Своя́, со умиле́нієм вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще доброді́телі і чудеса́ твоя́, ра́достію сріта́ху і провожда́ху отці́ на́ші свято́є ті́ло твоє́, єгда́, преселя́хуся святи́я мо́щі твоя́ на но́воє мі́сто поко́їща в сла́вном свята́го Петра́ гра́де: і ми ни́ні, ра́дующеся о небе́сній сла́ві твоє́й і обита́нії нетлі́нних моще́й твої́х в богоізбранном гра́ді сем со о́німи вопіє́м ті:","Ра́дуйся, россі́йський Іо́сифе, на но́воє мі́сто упокоє́нія пресели́вийся;","Ра́дуйся, всіх конце́в землі́ Россі́йськия покрови́телю.","Ра́дуйся, Петро́ва гра́да благонаде́жноє утвержде́ніє;","Ра́дуйся, того́же во бра́ніх Небе́сний защити́телю.","Ра́дуйся, сі́верния столи́ці неоціне́нноє украше́ніє;","Ра́дуйся, тезоімени́тия тебі́ оби́телі сла́во і утвержде́ніє.","Ра́дуйся, наро́ду ру́ському здра́віє же і спасе́ніє моли́твами твої́ми подава́яй;","Ра́дуйся, всіх упова́ніє на тя возложи́вших, богому́дрий учи́телю.","Ра́дуйся, і́ноком, я́ко і́нок, поле́зноє, приме́ром жи́зні своєя́, наставле́ніє преподава́яй;","Ра́дуйся, мирськи́м лю́дем, я́ко в ми́рі потруди́вийся, к доброді́телем общежи́тія руководи́телю.","Ра́дуйся, нетлі́нієм свої́м всім нам наде́жду воскресе́нія подава́яй;","Ра́дуйся, всіх нас в напа́стіх і ско́рбіх побо́рниче, храни́телю і свободи́телю.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 13","ps":["О, святи́й благові́рний вели́кий кня́же Алекса́ндре! От благогові́йних серде́ць приноси́мую ті, а́ще і недосто́йную, хвале́бную піснь сію́, прийми́ от нас, я́ко усе́рдную же́ртву серде́ць, лю́б'ящих тя і ублажа́ющих святу́ю па́м'ять твою́. Охраня́й всіх нас моли́твами твої́ми: огради́ хода́тайстви твої́ми град твой і вся лю́ди землі́ Россі́йськия, да ти́хоє і безмо́лвноє житіє́ пожи́вше в ни́нішнем ві́ці блаже́нство ві́чноє наслі́дим і ку́пно с тобо́ю і всі́ми святи́ми ви́ну сподо́бимся воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Со А́нгели і всі́ми святи́ми предстої́ши ни́ні Христу́, блаже́нно Алекса́ндре, моля́ся о любо́вію чту́щих тя: ті́мже, помина́юще, я́ко, ізмла́да Христа́ возлюби́в, к небе́сним ду́хом приліпи́лся єси́, бесплотних подража́в житію́, ублажа́єм тя, вопію́ще:","Ра́дуйся, ко́рене благочести́ваго о́трасле пречестна́я;","Ра́дуйся, благові́рія предко́в наслі́дниче.","Ра́дуйся, доброді́телей отця́ боголюби́ваго подража́телю;","Ра́дуйся, кро́тости і благоче́стія ма́терняго преє́мниче.","Ра́дуйся, вождю́ к Небесе́м стада́ своєго́ христолюби́ваго;","Ра́дуйся, в житії́ всіх рабо́в Бо́жиїх дру́же і ревни́телей благоче́стія собесі́дниче.","Ра́дуйся, преподо́бних ли́ка богосві́тлаго соприча́стниче;","Ра́дуйся, ві́ри Христо́ви непобіди́мий іспові́дниче.","Ра́дуйся, во́лею му́чениче, сликовству́яй ни́ні со́нму му́чеников добропобі́дному;","Ра́дуйся, христия́нськаго упова́нія і любве́ всім нам ді́вственний пропові́дниче.","Ра́дуйся, уста́вов і чи́на церко́внаго благолі́пнаго ревни́телю;","Ра́дуйся, ві́рних чад Це́ркве і уго́дников Бо́жиїх сонаслі́дниче.","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Кондак 1","ps":["Ізбра́нному воєво́ді землі́ Россі́йськия, сві́тлому украше́нію Це́ркве Правосла́вния, свято́му благові́рному вели́кому кня́зю Алекса́ндру Не́вскому, похва́льная воспису́юще, я́ко ві́рою враги́, ви́димия же і неви́димия, побіди́вшему, і во ві́рі своє́й, по рече́нію апо́столову, доброді́тель, в доброді́телі же ра́зум, в разумі́ же воздержа́ніє, во воздержа́нії же терпі́ніє, в терпі́нії же благоче́стіє, братолю́біє і любо́в яви́вшему со умиле́нієм і ра́достію возопії́м:","Ра́дуйся, святи́й благові́рний вели́кий кня́же Алекса́ндре."]},{"h":"Молитва","ps":["Ско́рий помо́щниче всіх усе́рдно к тебі́ прибіга́ющих і те́плий наш пред Го́сподем предста́телю, святи́й благові́рний кня́же Алекса́ндре! При́зри ми́лостивно на ни недосто́йния мно́гими беззако́нії непотре́бни себі́ сотворшія, к ра́ці моще́й твої́х ни́ні притекающия і із глубини́ се́рдця тебі́ взивающия: ти в житії́ своє́м ревни́тель і защи́тник правосла́вния ві́ри бил єси́, і нас в ней те́плими твої́ми моли́твами непоколеби́ми утверди́. Ти вели́коє, возложе́нноє на тя служе́ніє тща́тельно проходи́л єси́, і нас твоє́ю по́мощію пребива́ти коєго́ждо, в не́йже при́зван єсть, наста́ви. Ти, побіди́в полки́ супоста́тов, от преді́лов Россі́йських отгна́л єси́, і на нас ополча́ющихся всіх ви́димих і неви́димих враго́в низложи́. Ти, оста́вив тлі́нний віне́ць ца́рства земна́го, ізбра́л єси́ безмо́лвноє житіє́, і ни́ні пра́ведно вінце́м нетлі́нним увінча́нний, на небесі́х ца́рствуєши, хода́тайствуй і нам, смире́нно мо́лим тя, житіє́ ти́хоє і безм'яте́жноє і к ві́чному Ца́рствію ше́ствіє неукло́нноє твої́м предста́тельством устро́й нам. Предстоя́ же со всі́ми святи́ми Престо́лу Бо́жию, моли́ся о всіх правосла́вних христия́нах, да сохрани́ть їх Госпо́дь Бог Своє́ю благода́тію в ми́рі, здра́вії, і благоде́нствії, і вся́ком благополу́чії в должа́йшая лі́та, да і при́сно сла́вим і благослови́м Бо́га, в Тро́йці Святі́й сла́вимаго Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Позна́й свою́ бра́тію, россі́йський Іо́сифе, / не в Єги́пті, но на Небесі́ ца́рствующий, / благові́рний кня́же Алекса́ндре, / і прийми́ моле́нія їх, / умножа́я жи́та лю́дем плодоно́сієм землі́ твоєя́, / гра́ди влади́чествія твоєго́ огражда́я моле́нієм, // правосла́вним христия́ном на сопроти́вния спобо́рствуя."]},{"h":"Інший тропар, глас 4","ps":["Я́ко благочести́ваго ко́рене / пречестна́я о́трасль бил єси́, блаже́нне Алекса́ндре, / яви́ бо тя Христо́с я́ко ні́коє Боже́ственноє сокро́вище Росси́йстій землі́, / но́ваго чудотво́рця пресла́вна і Богоприя́тна. / І днесь соше́дшеся в па́м'ять твою́ ві́рою і любо́вію, / во псалмі́х і пі́ніїх ра́дующеся сла́вим Го́спода, / да́вшаго тебі́ благода́ть ісціле́ній. / Єго́же моли́ спасти́ град сей, / і держа́ві Росси́йстій Богоуго́дній би́ти, // і синово́м Россі́йським спасти́ся."]},{"h":"Кондак, глас 8","ps":["Я́ко звізду́ тя пресві́тлу почита́єм, / от восто́ка возсія́вшую, і на за́пад прише́дшую, / всю бо страну́ сію́ чудеси́ і добро́тою обогаща́єши, / і просвіща́єши ві́рою чту́щия па́м'ять твою́, Алекса́ндре блаже́нне. / Сего́ ра́ди днесь пра́зднуєм твоє́ успе́ніє, лю́діє твої́ су́щії, / моли́ спасти́ Оте́чество твоє́, і вся притека́ющия к ра́ці моще́й твої́х, / і ві́рно вопію́щия ті: // ра́дуйся, гра́ду на́шему утвержде́ніє."]},{"h":"Інший кондак, глас 4","ps":["Я́коже сро́дниці твої́, Бори́с і Гліб, / яви́шася тебі́ с Небесе́ в по́мощ, / подвиза́ющемуся на Ве́лгера Сві́йськаго і во́єв єго́, / та́ко і ти ни́ні, / блаже́нне Алекса́ндре, / прийди́ в по́мощ твої́м сро́дником // і побори́ борю́щия ни."]},{"h":"Величання","ps":["Велича́єм тя, / благові́рний кня́же Алекса́ндре, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]},{"h":"Інше величання (на успіння)","ps":["Велича́єм тя, / благові́рний кня́же Алекса́ндре, / і чтим свято́є успе́ніє твоє́, / і ни́ні мо́лиши за нас // Христа́, Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобним Кирилу і Марії, батькам преподобного Сергія Радонезького","e":"Akathist to the Venerable Cyril and Maria, parents of St Sergius of Radonezh","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці і вели́ції уго́дниці Госпо́дні, оби́телі на́шея засту́пниці і при́снії о душа́х на́ших моли́твенниці, преподо́бнії схимона́ше Кири́лле і схимона́хине Марі́є! Пі́ніє похва́льноє вам принося́ще, мо́лим ви усе́рдно: я́ко іму́щії дерзнове́ніє ко Го́споду, предста́тельством ва́шим от вся́ких бід нас свободи́те і наслі́дники Ца́рствія Небе́снаго нас соді́лайте, да зове́м вам ра́достно:","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци небе́снії воі́стину яви́стеся преподо́бнії Кири́лле і Марі́є, от ю́ности ва́шея чи́стую со́вість іму́щії к Бо́гу, і до́брі во благоче́стії і чистоті́ вку́пі пожи́вшії, нам же оста́вльшії в примі́р подража́нія житіє́ ва́ше богоуго́дноє, єму́же чудя́щеся і чудеси́ ва́шими озаря́ємі, зове́м вам гла́си хвале́бними си́це:","Ра́дуйтеся, от ю́ности ва́шея Христа́ возлюби́вшії і Тому́ от душі́ порабо́тавшії;","Ра́дуйтеся, цілому́дрія храни́тели і душе́вния і тіле́сния чистоти́ рачи́тели.","Ра́дуйтеся, ду́ші ва́ші і тілеса́ на землі́ в обита́лище Ду́ха Свята́го угото́вившії;","Ра́дуйтеся, іспо́лненнії прему́дрості і ра́зума Боже́ственнаго.","Ра́дуйтеся, я́ко от землі́ на не́бо прейдо́сте і та́мо со А́нгели Тро́йце предстої́те;","Ра́дуйтеся, я́ко со безпло́тними ли́ки трисвяту́ю піснь Єй воспіва́єте.","Ра́дуйтеся, на небесі́ і на землі́ от Го́спода просла́вленнії;","Ра́дуйтеся, обрі́тшії ві́чноє всесві́тлоє мі́сто упокоє́нія.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 2","ps":["Ви́дя всеви́дящеє о́ко Отця́ сві́тов вельми́ благоуго́дноє Бо́гу ва́ше житіє́, благоволи́ ізбра́ти вас, блаже́ннії, да яві́те ми́рові світи́льник пресві́тлий Се́ргия преподо́бнаго, да о нем і ва́ші імена́ просла́в'яться і всі ві́рнії воспою́ть просла́вльшему вас Го́сподеві: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зума Боже́ственнаго преіспо́лненнії, Кири́лле і Марі́є, неуста́нно рабо́тасте Го́сподеві, наставля́я ча́да своя́ в послуша́нії і кро́тости. Умудрі́те у́бо і нас, преподо́бнії, непреста́нно оправда́нієм Госпо́днім слі́довати нело́жно, да обря́щем вку́пі с ва́ми спасе́ніє ві́чноє і принесе́м вам благохвале́нія такови́я:","Ра́дуйтеся, блаже́ннії, в боголю́бії пожи́вшії і благові́ріє сохра́ншії;","Ра́дуйтеся, ми́лості і сострада́нія преіспо́лненнії.","Ра́дуйтеся, ми́лостинею і моли́твами Небе́сноє Ца́рствіє стяжа́вшії;","Ра́дуйтеся, смире́нієм і поще́нієм ві́чноє блаже́нство улучи́вшії.","Ра́дуйтеся, я́ко мзда ва́ша мно́га на Небесі́х єсть;","Ра́дуйтеся, я́ко моли́твами ва́шими і ми наде́жди Ца́рствія Христо́ва не лиша́ємся.","Ра́дуйтеся, я́ко ра́дость ва́ша ві́чна во сві́тлостіх святи́х;","Ра́дуйтеся, я́ко тоя́жде сві́тлости вас ра́ди і ми наслі́дниками явля́ємся.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю огражда́єм преподо́бний Кири́лл кня́зю Росто́вському со вся́ким усе́рдієм служа́ше і вку́пі с ним во орду́ Ага́рянськую, ми́ра ра́ди, хожда́ше, да лю́ди ру́сскиє осла́бу от і́га їх і́муть і Бо́гу непреста́нно пою́ть: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи помишле́ніє преподо́бнії Кири́лл і Марі́я і лю́діє о трикра́тном во чре́ві Марі́їном в це́ркве плода́ глаше́нії і уди́вльшеся, разумі́ша ні́что пресла́вноє і чу́дноє би́ти; і по сих уві́дівше ра́достноє си́на рожде́ніє, ра́довахуся і ра́достная вам приноша́ху глаго́люще:","Ра́дуйтеся, дво́їце пресві́тлая, Бо́гом совокупле́нная;","Ра́дуйтеся, зві́зди непреле́стнії, путь супру́жеськаго житія́ богоуго́днаго ві́рно указу́ющії.","Ра́дуйтеся, роди́телі благі́ї до́браго і ізбра́ннаго плода́;","Ра́дуйтеся, вся́кия благода́ті Бо́жия єго́ іспо́лнившії.","Ра́дуйтеся, супру́гов христия́н ко благоче́стію наста́вници;","Ра́дуйтеся, до́брому богобоя́зненному чад воспита́нію їх науча́ющії.","Ра́дуйтеся, цілому́дрія і воздержа́нія супру́жеськаго о́бразі преізя́щнії;","Ра́дуйтеся, хотя́щих богоуго́дно жи́ти богому́дрії учи́теліє.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 4","ps":["Бу́ря скорбе́й і напа́стей, воздвиза́ємая намі́стником Вели́каго Кня́зя, не осла́би крі́пкия любве́ ва́шея я́же к Бо́гу, Кири́лле і Марі́є блаже́ннії, но па́че научи́ ви ізря́дніє отража́ти разже́нния стрі́ли лука́ваго. Научі́те у́бо і нас вся ско́рбі ми́ра сего́ с кро́тостію преноси́ти, во весе́лії вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше, блаже́ннії, Варфоломе́я, ди́вноє ча́до ва́ше, ні́когда гра́моте неіску́сна, чту́ща богодухнове́нния писмени́, удиви́шася зіло́, і ста́рця-схи́мника, прему́дрость єму́ дарова́вшаго, в дом свой прия́ша, за́повідь Апо́стола Па́вла храня́ше: страннолю́бія не забива́йте; тім бо не ві́дяще ні́ції странноприя́ша А́нгели. Такову́ю доброді́тель ва́шу воспіва́юще, вопіє́м вам си́це:","Ра́дуйтеся, за́повідей Христо́вих ві́рнії ісполни́тели;","Ра́дуйтеся, уче́нія Єва́нгельськаго і́стиннії послі́дователі.","Ра́дуйтеся, уго́дниці Бо́жії, житію́ вели́ких святи́х соприча́стници;","Ра́дуйтеся, страннопри́їмства дре́вняго пра́отця Авраа́ма подража́телі.","Ра́дуйтеся, сві́том благоче́стнаго житія́ ва́шего, я́ко світи́ла богосві́тлая, просія́вшії;","Ра́дуйтеся, любо́в і милосе́рдіє к бі́дним і си́рим яви́вшії.","Ра́дуйтеся, безпомо́щним ско́рії помо́щници;","Ра́дуйтеся, я́ко і нам при́сно помога́єте і к Небе́сному Оте́честву руково́дствуєте.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 5","ps":["Боготе́чним звізда́м подо́бни би́сте, преблаже́ннії Кири́лле і Марі́є, єгда́ прише́дше от страни́ Росто́вськия в преді́ли кня́жества Моско́вськаго і во гра́ді Ра́донеже посели́стеся, та́мо су́щих бо люде́й благоче́стієм свої́м удиви́сте, подвиза́я пі́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше, святі́ї, тща́ніє си́на своєго́, преподо́бнаго Се́ргия, к і́ночеському житію́, моля́ху єго́, да пребу́деть с ва́ми до кончи́ни ва́шея. Он же, я́ко син послуша́нія, ізді́тська науче́нний ва́ми за́повіді Госпо́дні ісполня́ти, покори́ся во́лі ва́шей, Кири́лле і Марі́є, я́коже Бо́жієй, науча́я всіх вопи́ти вам та́ко:","Ра́дуйтеся, блаже́нств Христо́вих прича́стници;","Ра́дуйтеся, честна́го супру́жества і попече́нія о ча́діх до́брії о́бразі.","Ра́дуйтеся, ангелонра́внії челові́ци;","Ра́дуйтеся, преподо́бних і пра́ведних соприча́стници.","Ра́дуйтеся, Пресвяти́я Тро́йці ві́рнії уго́дниці;","Ра́дуйтеся, я́ко і чад ва́ших угожда́ти Єй научи́вшії.","Ра́дуйтеся, того́ ра́ди син ваш Трийпоста́сному Божеству́ оби́тель ди́вную устро́ївий;","Ра́дуйтеся, сего́ ра́ди і ва́ша святи́я імена́ просла́влени єсть по всей Русі́.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 6","ps":["Пропові́дници ві́ри правосла́вния і ревни́тели благоче́стія не сло́вом то́кмо, но і житіє́м ва́шим, би́сте во гра́ді Ра́донеже, прехва́льнії Кири́лле і Марі́є: ті́мже і свята́я Це́рков досто́йно почита́єть вас, немо́лчно воспіва́я Ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ во гра́ді Ра́донеже світ доброді́тельнаго ва́шего житія́, преблаже́ннії Кири́лле і Марі́є; єгда́ же дости́гше во́зраста прекло́нна, во оби́тель Хотько́вськую устреми́шася под покро́в Бо́жієй Ма́тері прите́кше, та́мо ве́лій о́браз А́нгельський на ся восприя́ли єсте́, ті́мже о́браз ви́шшаго нам смире́нія показу́я, єму́же поуча́яся, с любо́вію вопіє́м вам такова́я:","Ра́дуйтеся, я́ко любве́ ра́ди Го́спода ми́ра сего́ сла́ву оста́висте;","Ра́дуйтеся, я́ко і́ночеськоє равноа́нгельноє житіє́ усе́рдно восприя́сте.","Ра́дуйтеся, во оби́тель дре́внюю прише́дшії і та́мо поко́й себі́ обрі́тшії;","Ра́дуйтеся, Пречи́стій Ді́ві Богоро́диці ду́ші свої́ вручи́вшії.","Ра́дуйтеся, о́браз а́нгельський восприї́мшії і непоро́чно єго́ сохра́ншії;","Ра́дуйтеся, всім і́ноком і і́нокиням до́брії о́бразі.","Ра́дуйтеся, пре́жде кончи́ни ва́шея вся стра́сті умертви́вшії воздержа́нієм;","Ра́дуйтеся, святу́ю схи́му в броню́ спасе́нія восприя́вшії.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь яви́ти в житії́ ва́шем, преподо́бнії Кири́лле і Марі́є, о́браз назида́нія, не то́кмо лю́дем мирськи́м, но і і́ночеському ли́ку, внуши́ вам в ста́рости масти́тій оста́віте сла́ву земну́ю і восприя́ти о́браз і́ночеський, в не́мже посто́м, бді́нієм і моли́твою до́брі подвиза́стеся, неуста́нно воспіва́я Трієди́ному Бо́гу Серафи́мськую піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую благода́ть показа́ всіх Творе́ць і Влади́ка чрез вас, преподо́бнії, єгда́ прешли́ єсте́ от вре́менния сея́ юдо́лі плаче́вния во оби́телі ві́чния. Святи́я мо́щі ва́ша, а́ще і под спу́дом сокрове́нни, мно́гая чудеса́ істоча́ху, мно́гим боля́щим ісціле́нія подава́ху; па́че же приноси́мия к вам младе́нці ісціля́ху. Сего́ ра́ди приймі́те, вра́чеве на́ші блаже́ннії, от нас похвали́ сицеви́я:","Ра́дуйтеся, сме́ртію вре́менною прише́дшії к жи́зні ві́чній;","Ра́дуйтеся, от Го́спода нетлі́нієм і чудеси́ просла́вленнії.","Ра́дуйтеся, я́ко па́м'ять ва́ша с похвала́ми і успе́ніє со святи́ми;","Ра́дуйтеся, я́ко імена́ ва́ша че́стни суть і благослове́нни во Оте́честві ва́шем.","Ра́дуйтеся, боля́щим младе́нцем ісціле́ніє подаю́щії;","Ра́дуйтеся, тя́жко боля́щую діви́цю, с любо́вію к вам прите́кшую, от неду́га ізба́вившії.","Ра́дуйтеся, о лю́б'ящих і чту́щих вас небе́снії предста́телі;","Ра́дуйтеся, приснопрося́щії нам у Го́спода да́ри бла́гости Єго́.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 8","ps":["Стра́шноє і ужа́сноє бі́дствіє при́йде на зе́млю Моско́вськую, єгда́ я́звою морово́ю уя́звлени би́ша лю́діє мно́зі во гра́діх і ве́сіх, і мно́жество їх умро́ша. Тогда́ собо́р освяще́нний со і́нокини моле́бния пі́нія вам приноша́ху і предста́тельстви ва́шими ізбавле́ніє от біди́ получи́ша, вопію́ще благоді́ющему чрез вас Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі боголю́бці ско́рбію ве́лією об'я́ти би́ша, єгда́ во дні лихоле́тій, на зе́млю Россі́йськую прише́дших, оби́тель Покро́ва Пречи́стая Ді́ви в Хо́тькові богобо́рці разоре́нію і запусті́нію преда́ша. Но па́м'ять о вас, преподо́бнії, в лю́діх жи́ва бисть, і сла́вляху ча́да россі́йськия житіє́ ва́ше і чудеса́ благохвале́нії сицеви́ми:","Ра́дуйтеся, чудотво́рці на́ші преди́вния;","Ра́дуйтеся, не оставля́ющії нас в ско́рбния дні.","Ра́дуйтеся, гра́да Хотько́ва і оби́телі на́шея огражде́ніє несокруши́моє;","Ра́дуйтеся, на враги́ ви́димия і неви́димия кре́пції нам спобо́рници.","Ра́дуйтеся, благодія́ній мно́жество нам істоча́ющії;","Ра́дуйтеся, ми́лостію сострада́нія ва́шего всіх об'є́млющії.","Ра́дуйтеся, при́снії всім нам хода́таї спасе́нія;","Ра́дуйтеся, неотсту́пнії гра́да Хотько́ва і оби́телі на́шея храни́тели.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 9","ps":["Всі А́нгели і святи́х ли́ки ра́довахуся ра́достію ве́лією, єгда́ оби́тель ва́ша, преподо́бнії Кири́лле і Марі́є, Це́ркві возвраще́на бисть і мо́щі ва́ша честни́я, от літ дре́вніх Бо́гом сокрове́нния, в хра́мі собо́рнім положе́ни бисть. І возже́нна бя́ху моли́тви лампа́да і лю́діє всі узрі́вше світ єя́ удивля́хуся зіло́, к вам в напа́стіх прибіга́ють і по́мощ от вас получа́ють; єя́же і нас сподо́біте преподо́бнії, о вас вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не довлі́єть к досто́йному прославле́нію чуде́с от моще́й ва́ших і пони́не соверша́ющихся, преблаже́ннії Кири́лле і Марі́є: ста́риця бо немощна́я мона́хиня ко́стноє преломле́ніє претерпі́вшая і от враче́й не уте́шенная, к вам, преподо́бнії, прите́кше і со слеза́ми моля́ху вас. Вско́рі же ісціле́ніє соверше́нноє получи́в, во умиле́нії се́рдця воспі́ша вам:","Ра́дуйтеся, благода́ті Свята́го Ду́ха сосу́ди ізбра́ннії;","Ра́дуйтеся, ра́дости нам ві́чния благоприя́тнії хода́таї.","Ра́дуйтеся, ста́рицю немощну́ю от неду́га ско́ро ісцели́вшії;","Ра́дуйтеся, ісціле́нієм сим іску́сних враче́й удиви́вшії.","Ра́дуйтеся, нетлі́нния благоуха́ющії цві́ти;","Ра́дуйтеся, безсме́ртія немерца́ющії лучи́.","Ра́дуйтеся, на землі́ вели́чієм чуде́с блиста́ющії;","Ра́дуйтеся, на небесі́ со А́нгели Бо́га сла́в'ящії.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 10","ps":["Спасе́ніє ві́чноє унасле́довавше, богоблаже́ннії Кири́лле і Марі́є, душа́ми ва́шими во оби́теліх го́рніх неразлу́чно в Бо́зі пребива́єте, святи́ми же мощми́ ва́шими во оби́телі Пренепоро́чния Ді́ви нетлі́нно вку́пі почива́єте і оби́льная ісціле́нія істоча́єте, нас в Го́рній Ієрусали́м о́ний руково́дствуя, вопію́щих того́ Гра́да Упра́вителю: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і прибі́жище всім к вам притека́ющим ви єсте́, преподо́бнії. Оби́тель бо ва́ша к жи́зні і́ночестей возрожде́нная мно́жество і́щущих спасе́нія собра́, їх же ви от іскуше́ній і собла́знов сохрані́те, блаже́ннії, і мона́шеському ді́ланію научі́те, да улучи́вше жела́ємоє, принесу́ть вам сицеви́я благода́рственния словеса́:","Ра́дуйтеся, чадолюби́вия на́ші предста́теліє;","Ра́дуйтеся, руково́дствующії нас ко Христу́ Бо́гу.","Ра́дуйтеся, наставля́ющії ше́ствовати по за́повідем Госпо́днім;","Ра́дуйтеся, науча́ющії терпіли́во носи́ти крест свой і Влади́ці на́шему послі́довати.","Ра́дуйтеся, я́ко с преподо́бним отце́м на́шим Се́ргиєм іме́єте дерзнове́ніє ко Христу́ Бо́гу на́шему і ко Святі́й Єго́ Богома́тері;","Ра́дуйтеся, я́ко ви єсте́ хода́таї о нас недосто́йних, жи́тельствующих во святі́й оби́телі на́шей, єй же ви і нача́льниці.","Ра́дуйтеся, я́ко Бо́гом собра́нній дружи́ні сей ви помо́щници, засту́пниці і моли́твенниці;","Ра́дуйтеся, я́ко ва́шими моли́твами сохраня́єма невреди́ми от бісо́в і от челові́к злих пребива́єм.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє прино́сять вам, преблаже́ннії Кири́лле і Марі́є, не во оби́телі Хотько́вськой то́кмо, но і во Висо́цькой, сино́м ва́шим основа́нней, многоціле́бних моще́й ва́ших часть іму́щей, сла́в'ять чудеса́ ва́ми соверша́ємия: младе́нець бо неду́г неісці́льний імі́яй, ісціле́ніє от вас получа́єть, роди́телей ра́дости безмі́рния ісполня́я, вопію́щих ісціле́ній пода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том трисія́нним осіява́ємі, Кири́лле і Марі́є, всеблаже́ннії, со всі́ми святи́ми предстої́те ни́ні на Небесі́ Престо́лу Царя́ ца́рствующих і отту́ду, я́ко світи́ла світоза́рнії, при́сно просвіща́єте ду́ші притека́ющих к ра́ці моще́й ва́ших і покая́нію і́стинному науча́єте. Сего́ ра́ди, прославля́юще вас, глаго́лем:","Ра́дуйтеся, я́ко сконча́ли єсте́ жизнь свою́ ті́лом, но ду́хом не отступа́єте от нас;","Ра́дуйтеся, с ві́рою приходя́щих к ра́ці моще́й ва́ших благода́тно освяща́ющії.","Ра́дуйтеся, би́сері сія́ющії і благода́тно просвіща́ющії челові́ков;","Ра́дуйтеся, сві́ти у́мнії, заре́ю Свята́го Ду́ха облиста́ющії.","Ра́дуйтеся, ізві́стнії умилостиви́тели Царя́ Небе́снаго;","Ра́дуйтеся, призива́ющих моли́твенно честна́я імена́ ва́ші ско́рії усли́шателі.","Ра́дуйтеся, упова́ніє на вас по Бо́зі возлага́ющих ди́внії помо́щници;","Ра́дуйтеся, всім правові́рним вся́коє проше́ніє во їх по́льзу ісполня́ющії.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 12","ps":["Благода́ть от Бо́га да́нную вам ві́дяще, прилі́жно мо́лим ви ни́ні, прехва́льнії схимона́си: проле́йте те́плую о нас моли́тву ко Го́споду, да сохрани́ть оби́тель на́шу неврежде́нну от напа́стей і нестроє́ній, і нас да поми́луєть і спасе́ть, вопію́щих Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ва́ше Богоуго́дноє житіє́, преподо́бнії, і на небесі́ от Бо́га прославле́ніє, ублажа́єм пра́ведноє преставле́ніє ва́ше, велича́єм безчи́сленния чудеса́ от святи́х моще́й ва́ших істека́ющия, і на неуси́пния моли́тви ва́ша упова́юще, взива́єм вам сицева́я:","Ра́дуйтеся, житіє́ ва́ше земно́є благоче́стне сконча́вшії;","Ра́дуйтеся, от Царя́ Небе́снаго вінці́ сла́ви приє́мшії.","Ра́дуйтеся, обличе́ннії в ри́зу благода́тнаго нетлі́нія;","Ра́дуйтеся, во благоуха́нії святи́ні нетлі́нно почива́ющії.","Ра́дуйтеся, препоя́саннії си́лою мно́гих чуде́с;","Ра́дуйтеся, я́ко ра́ка ва́ша честна́я враче́бниця яви́ся неду́гом челові́чеським.","Ра́дуйтеся, я́ко от нея́ всяк с ві́рою приходя́й да́ри ціле́бния приє́млеть;","Ра́дуйтеся, я́ко оби́тель на́ша моще́й ра́ди ва́ших по всей земле́ Росси́йстій прославля́ється.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 13","ps":["О, пресла́внії чудотво́рці і уго́дниці Госпо́дні Кири́лле і Марі́є! Приймі́те сія́ моле́нія на́ша от всея́ душі́ вам ни́ні возноси́мия і сподо́біте нас предста́тельстви ва́шими в чи́ні а́нгельськом дости́гнути Небе́снаго Ца́рствія, іді́же всі святі́ї, А́нгели і челові́ци воспіва́ють непреста́нними гла́си хвалу́ Пресвяті́й Тро́йці, Бо́гу на́шему: Аллилу́я, Аллилу́я, Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци небе́снії воі́стину яви́стеся преподо́бнії Кири́лле і Марі́є, от ю́ности ва́шея чи́стую со́вість іму́щії к Бо́гу, і до́брі во благоче́стії і чистоті́ вку́пі пожи́вшії, нам же оста́вльшії в примі́р подража́нія житіє́ ва́ше богоуго́дноє, єму́же чудя́щеся і чудеси́ ва́шими озаря́ємі, зове́м вам гла́си хвале́бними си́це:","Ра́дуйтеся, от ю́ности ва́шея Христа́ возлюби́вшії і Тому́ от душі́ порабо́тавшії;","Ра́дуйтеся, цілому́дрія храни́тели і душе́вния і тіле́сния чистоти́ рачи́тели.","Ра́дуйтеся, ду́ші ва́ші і тілеса́ на землі́ в обита́лище Ду́ха Свята́го угото́вившії;","Ра́дуйтеся, іспо́лненнії прему́дрості і ра́зума Боже́ственнаго.","Ра́дуйтеся, я́ко от землі́ на не́бо прейдо́сте і та́мо со А́нгели Тро́йце предстої́те;","Ра́дуйтеся, я́ко со безпло́тними ли́ки трисвяту́ю піснь Єй воспіва́єте.","Ра́дуйтеся, на небесі́ і на землі́ от Го́спода просла́вленнії;","Ра́дуйтеся, обрі́тшії ві́чноє всесві́тлоє мі́сто упокоє́нія.","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці і вели́ції уго́дниці Госпо́дні, оби́телі на́шея засту́пниці і при́снії о душа́х на́ших моли́твенниці, преподо́бнії схимона́ше Кири́лле і схимона́хине Марі́є! Пі́ніє похва́льноє вам принося́ще, мо́лим ви усе́рдно: я́ко іму́щії дерзнове́ніє ко Го́споду, предста́тельством ва́шим от вся́ких бід нас свободи́те і наслі́дники Ца́рствія Небе́снаго нас соді́лайте, да зове́м вам ра́достно:","Ра́дуйтеся, преподо́бнії Кири́лле і Марі́є, блазі́ї о нас пред Бо́гом засту́пниці."]},{"h":"Молитва","ps":["О раби́ Бо́жії, преподо́бнії Кири́лле і Марі́є! А́ще і сконча́ли єсте́ вре́менную жизнь свою́ ті́лом, но ду́хом не отступа́єте от нас, руково́дствуєте же ни ко Христу́ Бо́гу, наставля́єте ше́ствовати по за́повідем Госпо́днім і носи́ти крест свой і послі́довати Влади́ці на́шему. Ви, преподо́бнії, вку́пі с преподо́бним і Богоно́сним отце́м на́шим Се́ргиєм, ва́шим возлю́бленним си́ном, іме́єте дерзнове́ніє ко Христу́ Бо́гу на́шему і ко Святі́й Єго́ Богома́тері. Бу́діте моли́твенниці і хода́таї о нас, недосто́йних, жи́тельствующих во святі́й оби́телі ва́шей, єй же ви і нача́льниці. Бу́діте помо́щници і засту́пниці Бо́гом собра́нній дружи́ні сей, да жи́тельствующії на мі́сті сем і приходя́щії с ві́рою, ва́шими моли́твами сохраня́ємі, невреди́ми от бісо́в і от челові́к злих пребу́дем, сла́в'яще Святу́ю Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Блаже́нств Христо́вих прича́стници, / честна́го супру́жества і попече́нія о ча́діх до́брий о́бразе, / пра́веднії Кири́лле і Марі́є, / плод благоче́стія, Се́ргия преподо́бнаго, нам яви́вшії, / с ни́мже усе́рдно молі́те Го́спода / низпосла́ти нам дух любве́ і смиренному́дрія, / да в ми́рі і єдиноми́слії // просла́вим Тро́йцю Єдиносу́щную."]},{"h":"Кондак, глас 4","ps":["Днесь, ві́рнії, соше́дшеся, / восхва́лим дво́їцю блаже́нную, благові́рнаго Кири́лла і Марі́ю добронра́вную, / ті́ї бо мо́ляться вку́пі со возлю́бленним си́ном свої́м преподо́бним Се́ргиєм / ко Єди́ному во Святі́й Тро́йці Бо́гу / оте́чество на́ше в правові́рії утверди́ти, / до́ми ми́ром огради́ти, / ю́ния от напа́стей і собла́знов ізба́вити, / ста́рость укріпи́ти // і спасти́ ду́ші на́ша."]},{"h":"Величання","ps":["Ублажа́єм вас, / преподо́бниє Кири́лле і Марі́є, / і чтим святу́ю па́м'ять ва́шу, / наста́вници мона́хов // і собесі́дниці А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Амвросію Оптинському","e":"Akathist to our Venerable Father Ambrose of Optina","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Бо́жий і чудотво́рче, вели́кий ста́рче, Амвро́сіє, О́птинськая похвало́ всея́ Руси́ ди́вний наста́вниче, прославля́юще твоє́ в по́двизіх ізря́дноє житіє́, прино́сим многохва́льноє пі́ніє, ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся о всіх нас, ча́діх твої́х, со умиле́нієм зову́щих:","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Ікос 1","ps":["А́нгельському житію́ подража́я, отве́ргл єси́ вся кра́сная і скоропреходя́щая тлі́ннаго ми́ра сего́ і стопи́ своя́ напра́вил єси́ к духо́вному учи́телю і прозорли́вцю ста́рцю Іларіо́ну, да наста́вить тя на путь і́стиннаго жи́тельства і благослови́ть на по́двиги спасе́нія. Он же, прови́дів гряду́щеє твоє́ богоуго́дноє житіє́, посла́ тя в оби́тель О́птину, і та́мо ти обрі́л єси́ себе́ до́броє приста́нище. Сіє́ уви́дівше таково́є Бо́жиє ізволе́ніє о тебі́, глаго́лем сицева́я:","Ра́дуйся, Бо́гом ізбра́нная о́трасле благоче́стія роди́телей;","Ра́дуйся, ізмла́да літ твої́х Го́спода возлюби́вий.","Ра́дуйся, ко кни́жній му́дрости усе́рдіє от ю́ности імі́вий;","Ра́дуйся, святи́х отце́в духоно́сноє уче́ніє позна́вий.","Ра́дуйся, скороги́бнущих благ ми́ра сего́ отверже́ніє;","Ра́дуйся, нетлі́нних сокро́вищ неосла́бноє жела́ніє.","Ра́дуйся, Бо́жия проізволе́нія о спасе́нії душі́ твоєя́ іска́вий;","Ра́дуйся, благослове́ніє на путь мона́шеський получи́вий.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 2","ps":["Ви́дя се́рдця твоєго́ благо́є намі́реніє, Христо́с предначерта́ у́зький і терни́стий путь твоєго́ спасе́нія, і, єгда́ бил єси́ внеза́пу на сме́ртном одрі́ болі́зні, даде́ Го́споду обіща́ніє: а́ще ісціли́ть тя, всего́ себе́ преда́ти подвиго́м і́ночества. Воста́в же по ми́лості Бо́жієй с одра́ болі́зні, а́біє просла́вил єси́ всеще́драго Бо́га, Врача́ душ і тіле́с, зов'я́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственних писа́ній стяжа́в, в стра́сі Бо́жиєм помишля́л єси́, ка́ко Госпо́дь устро́їть гряду́щий путь твоєго́ спасе́нія і ка́ко вступи́ти на стезю́ многотру́днаго і ско́рбнаго мона́шеськаго жи́тельства. Ми же, див'я́щеся твоєму́ благо́му намі́ренію, воспіва́єм ті:","Ра́дуйся, на Бо́га Промисли́теля всю наде́жду возложи́вий;","Ра́дуйся, то́кмо Єго́ благоізволе́нія взиска́вий.","Ра́дуйся, вся́коє іспита́ніє во спасе́ніє душі́ понести́ гото́вий;","Ра́дуйся, со́вісти своєя́ велі́нію послі́довавий.","Ра́дуйся, увеселе́нія мирська́я возненави́дівий;","Ра́дуйся, бога́тства земна́я не возлюби́вий.","Ра́дуйся, Бо́гу єди́ному порабо́тати всего́ себе́ подви́гнувий;","Ра́дуйся, Тому́ то́чію угоди́ти восхоті́вий.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 3","ps":["Си́лою любве́ утвержда́яся, во ві́рі поревнова́л єси́ Єва́нгельськоє житіє́ стяжа́ти по о́бразу преподо́бних отце́в Це́ркве дре́внія. Єгда́ же даде́ ті Госпо́дь разумі́ніє сего́ благоугожде́нія, воспі́л єси́ со умиле́нієм: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я крі́пкую ві́ру во благо́є промишле́ніє Бо́жиє о спасе́нії челові́ка, прите́кл єси́ к честно́му о́бразу Пресвяти́я Богоро́диці «Тамбо́вськия», є́же бисть тебі́ благослове́ніє роди́тельськоє, і смире́нно моли́л єси́ Влади́чицю, да упра́вить путь твой. Ми же, ви́дяще твоє́ неотсту́пноє упова́ніє на ми́лость Цари́ці Небе́сния, поє́м ті:","Ра́дуйся, Бо́жия Ма́тере ві́рноє і возлю́бленноє ча́до:","Ра́дуйся, Єя́ свяще́ннаго покро́ва си́ли та́йноє постиже́ніє.","Ра́дуйся, благослове́нія роди́тельськаго чрез Єя́ о́браз добронра́вний храни́телю;","Ра́дуйся, Засту́пниці усе́рдния благогові́йний почита́телю.","Ра́дуйся, многоча́стні в нощі́ моли́тви к Ней сле́зно возноси́вий;","Ра́дуйся, небе́сний по́мощі от Нея́ непости́дно восприє́мий.","Ра́дуйся, та́ко утіше́ніє в се́рдці своє́м обріти́й сла́достноє;","Ра́дуйся, я́ко умиле́ніє прия́л єси́ благоти́шноє.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 4","ps":["Бу́рею помишле́ній дви́жимий, прише́л єси́ в оби́тель преподо́бнаго Се́ргия Ра́донежськаго, да укріпи́ть твоє́ се́рдце на по́двиги предстоя́щаго і́ночеськаго по́прища всея́ Россі́ї чудотво́рець і учи́тель мона́шеськаго ді́ланія, преізлива́ющий от ра́ки свої́х честни́х моще́й то́ки благода́тния по́мощі Умили́вся же та́мо се́рдцем взива́л єси́ с ра́достію: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша ве́ліє житіє́ і благоче́стіє богому́дрих отце́в і ста́рцев О́птини пу́стині, та́йно оста́вил єси́ мир і вся, я́же в нем, і прише́л єси́ необину́яся в оби́тель сію́ в смире́нії душі́, во є́же спасти́ся і угоди́ти Бо́гу. Ми же, ви́дяще вя́щшую ре́вность душі́ твоєя́, прино́сим ті хвале́бную піснь:","Ра́дуйся, тлі́нния бла́га ми́ра сего́ ні во что́же вміни́вий;","Ра́дуйся, сла́дость церко́вную позна́вий.","Ра́дуйся, во оби́тель святу́ю всели́вийся;","Ра́дуйся, всего́ себе́ Бо́гу отда́вий.","Ра́дуйся, за́повіді Бо́жия нелі́ностно іспо́лнивий;","Ра́дуйся, плоди́ Христо́ва уче́нія сла́дці вкуси́вий.","Ра́дуйся, подвиго́в святи́х отце́в ревни́телю;","Ра́дуйся, чистоти́ душе́вния неуси́пний храни́телю.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 5","ps":["Богозда́нная пу́стинь прия́ тя, я́ко во об'я́тія о́тча, в ню́же кро́тко всели́лся єси́ і та́мо пе́рвіє поне́сл єси́ труди́ послуша́нія в ке́ллії вели́каго ста́рця богопросвеще́ннаго Льва, їм же наста́влен бил єси́ к духо́вному ді́ланію. Уві́дів же сла́дость отрече́нія во́лі своєя́, возопи́л єси́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще твоє́ і́ночеськоє преуспі́яніє, облеко́ша тя отці́ пу́стині в ри́зи схи́ми вели́кия. І сподо́би тя подвигонача́льник Христо́с благода́ті а́нгельськаго чи́на приобщи́тися, сего́ ра́ди вопіє́м ті:","Ра́дуйся, всім се́рдцем Бо́га возлюби́вий;","Ра́дуйся, все́ю душе́ю Єму́ послужи́вий.","Ра́дуйся, ві́ру чрез мно́гія труди́ непрело́жно утверди́вий;","Ра́дуйся, наде́ждою на по́мощ сви́ше себі́ вооружи́вий.","Ра́дуйся, любве́ Єва́нгельськия сокро́вище;","Ра́дуйся, Ду́ха Свята́го вмісти́лище.","Ра́дуйся, подвиго́в мона́шеських во́їне до́блественний;","Ра́дуйся, равноа́нгельськаго житія́ подража́телю преди́вний.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 6","ps":["Пропові́дник правосла́вний ві́ри і і́стиннаго житія́ во Христі́ Ісу́се яви́лся єси́, проти́вния Єва́нгелію і Це́ркві уче́нія отриця́я, і мно́гія от путі́ заблужде́нія обрати́л єси́ ко Христу́ Жизнода́вцю, поя́ благода́рственно: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко свіща́ многосві́тлая, в землі́ Росси́йстій, просвіща́я вся́каго челові́ка приходя́щаго к тебі́, сві́том і́стини, лю́діє же, обремене́ннії гріхми́ і скорбми́ мно́гими, обріто́ша в тебі́ богоразу́мнаго наста́вника благоче́стія і до́браго отця́ всім немощству́ющим, стра́ждущим і уничиже́нним, воспіва́юще такова́я:","Ра́дуйся, світи́льниче правосла́вния страни́ Россі́йськия;","Ра́дуйся, зерца́ло Боже́ственния любве́.","Ра́дуйся, сто́лпе ві́ри апо́стольськія;","Ра́дуйся, ка́меню наде́жди жи́зні ві́чния.","Ра́дуйся, наста́вниче во вся́ких обстоя́ніях боговдохнове́нний;","Ра́дуйся, пропові́дниче покая́нія рачи́тельний.","Ра́дуйся, врачу́ неду́гов тіле́сних;","Ра́дуйся, ціли́телю болі́зней душе́вних.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 7","ps":["Хотя́ послі́довати самому́ Христу́, подража́л єси́ Єму́ всеусе́рдно, взем і́го Єго́ на себі́, і, научи́вся от Него́ кро́тости і смире́нію, обрі́л єси́ поко́й душі́ своє́й, зову́щей при́сно: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая і ди́вная звізда́ свя́тости яви́ся на не́бі церко́внім, єгда́ возше́л єси́ по лі́ствице духо́вній к соверше́нству ангелоподо́бному, просте́рл єси́ лучи́ любве́ своєя́ по лицю́ всея́ землі́ ру́ськия і привле́кл єси́ к себі́ зна́тния і худоро́дная, му́драя ві́ка сего́ і нему́дрия, вопію́щая к тебі́ сицева́я:","Ра́дуйся, гра́де, верху́ гори́ стоя́й;","Ра́дуйся, світи́ло, мрак неві́дінія прогоня́ющеє.","Ра́дуйся, вся немощна́я врачу́яй;","Ра́дуйся, от бід і прельще́ній вра́жеських ізбавля́яй.","Ра́дуйся, печа́льних уті́шителю;","Ра́дуйся, жа́ждущих духо́вний напоі́телю.","Ра́дуйся, хитрослове́снаго мудрова́нія ві́ка сего́ обличи́телю;","Ра́дуйся, мно́гих заблу́дших на путь і́стини ісправи́телю.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 8","ps":["Стра́нником і прише́льцем в земні́м ми́рі предста́л єси́, взиску́ющим гра́да небе́снаго, і поне́сл єси́ тяготи́ і не́мощі і́щущаго у тебе́ по́мощі бли́жняго, і та́ко іспо́лнил єси́ зако́н Христо́в, поя́ с благодаре́нієм: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь огне́м Боже́ственния любве́ іспо́лненний, крест многотру́дний болі́зней тіле́сних проне́сл єси́ чрез все твоє́ і́ночеськоє житіє́, в терпі́нії стяжа́в ду́шу твою́, по сло́ву Єва́нгелія Христо́ва, і всіх нас научи́л єси́ безро́потному крестоноше́нію, зову́щих ті:","Ра́дуйся, вождю́ і́щущих спасе́нія;","Ра́дуйся, о́бразе і́стиннаго послуша́нія.","Ра́дуйся, сам тя́жкия неду́ги до конця́ претерпі́вий;","Ра́дуйся, приходя́щия к тебі́ в болі́зніх і печа́ліх терпі́нію научи́вий.","Ра́дуйся, па́стви твоєя́ ізря́дний душепопечи́телю;","Ра́дуйся, а́лчущих жи́зні ві́чния пита́телю.","Ра́дуйся, оби́димих покрови́телю;","Ра́дуйся, непоко́рних во́лі Бо́жієй вразуми́телю.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 9","ps":["Все єстество́ челові́чеськоє в болі́зніх і тіле́сних не́мощіх іспита́л єси́, плоть расп'я́в со страстьми́ і похотьми́, і моли́твою неуста́нною отгоня́л єси́ напа́сти і іскуше́нія лука́вих духо́в і тім вся науча́л єси́ противоста́ти ко́знем дия́вольским, взива́я с ві́рою: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йства суєму́дрих, неве́давших си́ли ві́ри правосла́вния, отмета́л єси́ сло́вом Бо́жиїм і чи́стим житіє́м твої́м, і воі́стину возсія́л єси́, я́ко світоза́рний столп благоче́стія і храни́тель святооте́чеськаго преда́нія, усе́рдно прелага́я дре́вняя писа́нія отце́во в письмена́ удобовразуми́тельная. Ми же, див'я́щеся трудо́м твої́м, воспіва́єм си́це:","Ра́дуйся, ві́ри пра́вия адама́нте;","Ра́дуйся, житія́ по ві́рі крі́посте.","Ра́дуйся, ду́ха благоче́стія насади́телю;","Ра́дуйся, доброді́телей христия́нських сі́ятелю.","Ра́дуйся, подвиго́в ста́рчества преуспі́яніє;","Ра́дуйся, мно́жества і́ноков духо́вноє просвіще́ніє.","Ра́дуйся, приведи́й тіх ко спасе́нію;","Ра́дуйся, обрати́вий мно́гія грі́шния к покая́нію.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 10","ps":["Спасти́ся взиску́ющим Ца́рства Небе́снаго вспомоществу́я, ві́рний путеводи́тель яви́лся єси́, мирськи́я і духо́вния управля́я: в коне́ць літ свої́х мно́гія труди́ положи́л єси́, оби́тель Шаморди́нськую убо́гим устроя́я, да сестри́ тоя́ обрету́ть душе́вний поко́й і спасе́ніє, воспіва́юще піснь хвале́бную: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і прибі́жище бил єси́ ча́дом твої́м, моли́твами неуси́пними от де́монських наважде́ній охраня́я; на неви́димую брань с ду́хи зло́би їх вдохновля́л єси́, го́рдость і славолю́біє смире́нієм упраздня́я, ті́мже ра́дующеся, зове́м ті:","Ра́дуйся, стрі́ли вра́жія угаси́вий;","Ра́дуйся, де́монськия полки́ побіди́вий.","Ра́дуйся, плі́нних от духо́в зло́би свободи́вий;","Ра́дуйся, із темни́ці страсте́й мно́гія ду́ші ізведи́й.","Ра́дуйся, любо́вію і моли́твами заблу́дшия к Бо́гу обрати́вий;","Ра́дуйся, сиро́т і вдови́ць до́брий попечи́телю.","Ра́дуйся, води́тельства і́ноков і і́нокинь богоно́сний зижди́телю;","Ра́дуйся, смиренному́дрія і кро́тости доброгла́сний пропові́дниче.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прино́сим ті, ско́рому помо́щнику в ну́ждах і печа́ліх всім, к тебі́ с ві́рою і любо́вію притека́ющим, до конця́ дній свої́х бил єси́ чадолюби́вий оте́ць стра́ждущих і обремене́нних, ча́ющих утіше́нія ду́ші. Ті́мже нело́жно прославля́ється тобо́ю Бог, ди́вний во святи́х Свої́х, зову́щих непреста́нно: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льника доброді́телей ви́діша в тебі́ всі конці́, о́тче наш Амвро́сіє, я́ко в терпі́нії і смире́нії земно́є стра́нствіє сконча́л єси́ і іспо́лнил єси́ вся, я́же запові́да нам Христо́с во Святі́м уче́нії, і пресели́лся єси́ от землі́ на не́бо, вше́дий в ра́дость Го́спода своєго́, я́ко ві́рний раб Христо́в. Ті́мже ра́дующеся, воспіва́єм ті такова́я:","Ра́дуйся, усе́рдний слуго́, сотвори́вий во́лю Господи́на своєго́;","Ра́дуйся, во́їне Христо́в, суєту́ жите́йськую оста́вивий.","Ра́дуйся, Бо́гу єди́ному послужи́вий;","Ра́дуйся, вся за́повіді Бо́жия іспо́лнивий.","Ра́дуйся, оби́телі небе́сния удосто́ївийся;","Ра́дуйся, го́рнія сла́ви приобщи́вийся.","Ра́дуйся, наслі́дниче жи́зні ві́чния;","Ра́дуйся, уго́дниче Бо́жий прехва́льний.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 12","ps":["Благода́ті Бо́жия сокро́вище некра́домоє унаслі́довал єси́ і ти́хоє, безм'яте́жноє приста́нище на небесі́х обрі́л єси́. Ді́йствієм же про́мисла Бо́жия во дні торжеству́ємаго тисящеле́тія Креще́нія Русі́ просла́влен і к ли́ку святи́х причи́слен бил єси́, ублажа́юще па́м'ять твою́ святу́ю, поє́м всі: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ всероссі́йськоє прославле́ніє, возно́сим ті, я́ко благоуха́ніє кади́льноє, смире́нния на́ша моли́тви, не забу́ди чад твої́х, почита́ющих і́м'я твоє́ свято́є і взива́ющих к тебі́ в благодаре́нії:","Ра́дуйся Амвро́сіє, Боже́ственнаго безсме́ртія тезоимени́тий;","Ра́дуйся, Це́ркве Правосла́вния честна́я похвало́.","Ра́дуйся, ли́ка святи́х уго́дников прича́стниче;","Ра́дуйся, со́нма преподо́бних отце́в сотаї́нниче.","Ра́дуйся, пред престо́лом Бо́га Всеви́шняго наш тве́рдий предста́телю;","Ра́дуйся, пред судо́м Бо́жиїм наш те́плий хода́таю.","Ра́дуйся, нас, стра́нствующих в юдо́лі плаче́вній, путеводи́телю;","Ра́дуйся, о всей землі́ Росси́йстій неуси́пний моли́твенниче.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 13","ps":["О ди́вний уго́дниче Христо́в і чудотво́рче, преподо́бне ста́рче наш Амвро́сіє, прийми́ ни́ні ма́лоє моле́ніє недосто́йних чад твої́х, не оста́ви нас в ско́рбіх і болі́зніх, прийди́ і простри́ ру́ку по́мощі, наста́ви нас на путь покая́нія і спасе́нія, во є́же ізба́витися му́ки ві́чния, да тобо́ю при́сно сла́вим Бо́га, вопію́ще: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельському житію́ подража́я, отве́ргл єси́ вся кра́сная і скоропреходя́щая тлі́ннаго ми́ра сего́ і стопи́ своя́ напра́вил єси́ к духо́вному учи́телю і прозорли́вцю ста́рцю Іларіо́ну, да наста́вить тя на путь і́стиннаго жи́тельства і благослови́ть на по́двиги спасе́нія. Он же, прови́дів гряду́щеє твоє́ богоуго́дноє житіє́, посла́ тя в оби́тель О́птину, і та́мо ти обрі́л єси́ себе́ до́броє приста́нище. Сіє́ уви́дівше таково́є Бо́жиє ізволе́ніє о тебі́, глаго́лем сицева́я:","Ра́дуйся, Бо́гом ізбра́нная о́трасле благоче́стія роди́телей;","Ра́дуйся, ізмла́да літ твої́х Го́спода возлюби́вий.","Ра́дуйся, ко кни́жній му́дрости усе́рдіє от ю́ности імі́вий;","Ра́дуйся, святи́х отце́в духоно́сноє уче́ніє позна́вий.","Ра́дуйся, скороги́бнущих благ ми́ра сего́ отверже́ніє;","Ра́дуйся, нетлі́нних сокро́вищ неосла́бноє жела́ніє.","Ра́дуйся, Бо́жия проізволе́нія о спасе́нії душі́ твоєя́ іска́вий;","Ра́дуйся, благослове́ніє на путь мона́шеський получи́вий.","Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Бо́жий і чудотво́рче, вели́кий ста́рче, Амвро́сіє, О́птинськая похвало́ всея́ Руси́ ди́вний наста́вниче, прославля́юще твоє́ в по́двизіх ізря́дноє житіє́, прино́сим многохва́льноє пі́ніє, ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся о всіх нас, ча́діх твої́х, со умиле́нієм зову́щих: Ра́дуйся, преподо́бне Амвро́сіє, богому́дрий учи́телю ві́ри і благоче́стія."]},{"h":"Молитва перша","ps":["О вели́кий ста́рче і уго́дниче Бо́жий, преподо́бне о́тче наш Амвро́сіє, О́птинськая похвало́ і всея́ Руси́ учи́телю благоче́стія! Сла́вим твоє́ во Христі́ смире́нноє житіє́, і́мже Бог превознесе́ і́м'я твоє́, єще́ на землі́ тебі́ су́ща, найпа́че же увінча́ тя небе́сною че́стію по отше́ствії твоє́м в черто́г сла́ви ві́чния. Прийми́ ни́ні моле́ніє нас, недосто́йних чад твої́х, чту́щих тя і призива́ющих і́м'я твоє́ свято́є, ізба́ви нас твої́м предста́тельством пред Престо́лом Бо́жиїм от всіх ско́рбних обстоя́ній, душе́вних і тіле́сних неду́гов, злих напа́стей, тлітво́рних і лука́вих іскуше́ній, низпосли́ Оте́честву на́шему от великодарови́таго Бо́га мир, тишину́ і благоде́нствіє, бу́ди непрело́жний покрови́тель святи́я оби́телі сія́, в не́йже в преуспі́янії сам подвиза́лся єси́ і угоди́л єси́ всі́ми в Тро́йці сла́вимому Бо́гу на́шему, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О преподо́бне і богоно́сне о́тче наш Амвро́сіє! Ти, порабо́тати Го́сподеві жела́я, зді всели́лся єси́ і нелі́ностно во труді́х, бді́ніїх, моли́твах і пості́х подвиза́лся єси́ і бил єси́ наста́вник мона́шествующим, всім же лю́дям учи́тель ре́вностний. Ни́ні у́бо, по отше́ствії твоє́м от земни́х, Небе́сному Царю́ предстоя́, моли́ бла́гость Єго́, є́же уще́дрити мі́сто селе́нія твоєго́, святу́ю оби́тель сію́, іді́же ду́хом любве́ твоєя́ неотсту́пно пребива́єши, і всім лю́дем твої́м, с ві́рою к ра́ці моще́й твої́х припа́дающим, во блага́я проше́нія їх іспо́лнити. Іспроси́ у ми́лостиваго Го́спода на́шего, да низпо́слеть нам оби́ліє благ земни́х, па́че же я́же на по́льзу душ на́ших да да́руєть нам, і сконча́ти житіє́ сіє́ привре́менноє в покая́нії да сподо́бит, в день же су́дний десна́го предстоя́нія і наслажде́нія во Ца́рствії Своє́м да удосто́їть во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О всечестни́й ста́рче пресла́вния і ди́вния О́птини пу́стині, преподо́бне і богоно́сне о́тче наш Амвро́сіє! Це́ркве на́шея до́броє украше́ніє і благода́тний світи́льниче, небе́сним сві́том всіх озаря́яй, кра́сний і духо́вний плод Россі́ї і всея́ подсо́лнечния, ду́ші ві́рних оби́льно услажда́яй і увеселя́яй! Ни́ні с ві́рою і тре́петом припа́даєм пред цільбоно́сною ра́кою святи́х моще́й твої́х, ї́хже на утіше́ніє і по́мощ стра́ждущим ми́лостивно дарова́л єси́, смире́нно мо́лим тя се́рдцем і усти́, о́тче святи́й, я́ко всероссі́йськаго наста́вника і учи́теля благоче́стія, па́стиря і врача́ душе́вних і тіле́сних неду́г на́ших: воззри́ на чад твої́х, зіло́ согріша́ющих в словесі́х і ді́ліх, і посіти́ нас мно́гою і свято́ю своє́ю любо́вію, є́юже сла́вно преуспі́л єси́ єще́ во дні земни́я, найпа́че по пра́ведній твоє́й кончи́ні, наставля́я в пра́виліх святи́х і богопросвеще́нних отце́в, вразумля́я нас в за́повідіх Христо́вих, в ни́хже до́брі поревнова́л єси́ до послі́дняго часа́ твоєя́ многотру́дния і́ночеськия жи́зні; іспроси́ нам, немощству́ющим душе́ю і бе́дствующим в ско́рбіх, благоприя́тноє і спаси́тельноє вре́м'я на покая́ніє, і́стинноє ісправле́ніє і обновле́ніє на́шего житія́, в не́мже ми, грі́шнії, осуєти́хомся умо́м і се́рдцем, преда́хом себі́ непотре́бним і лю́тим страсте́м, поро́ком і беззако́нієм, і́мже ність числа́; прийми́ у́бо, соблюди́ і покри́й нас кро́вом твоєя́ мно́гія ми́лости, низпосли́ нам благослове́ніє от Го́спода, да понесе́м благо́є і́го Христо́во в долготерпі́нії до конця́ дній на́ших, ча́юще бу́дущаго живота́ і Ца́рствія, іді́же ність печа́ль, ні воздиха́ніє, но жизнь і ра́дость безконе́чная, ізоби́льно проістека́ємая от Єди́наго, Всесвята́го і Блаже́ннаго Істо́чника безсме́ртія в Тро́йці покланя́ємаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Я́ко к ціле́бному істо́чнику / притека́єм к тебі́, Амвро́сіє, о́тче наш. / Ти бо на путь спасе́нія нас ві́рно наставля́єши, / моли́твами от бід і напа́стей охраня́єши, / в ті́лесних і душе́вних ско́рбіх утіша́єши, / па́че же смире́нію, терпі́нію і любві́ науча́єши. / Моли́ Человіколю́бця Христа́ / і Засту́пницю усе́рдную // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Заві́т Пастиренача́льника іспо́лнив / ста́рчества благода́ть наслі́довал єси́, / болі́знуя се́рдцем о всіх, с ві́рою притека́ющих к тебі́, / ті́мже і ми, ча́да твоя́, с любо́вію вопіє́м ті: / о́тче святи́й Амвро́сіє, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче Амвро́сіє, і чтим святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче а́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Севастіану Карагандинському","e":"Akathist to our Venerable Father Sebastian of Karaganda","secs":[{"h":"Кондак 1","ps":["Ізбра́нний преє́мниче благода́ті ста́рчества О́птинськаго, в годи́ну гоне́ній лю́тих кро́ткий за ві́ру правосла́вную страда́льче, гра́ду Караганде́ богодарова́нний світи́льниче і всея́ страни́ Казахста́нськия неуси́пний храни́телю, Це́ркве Ру́ськия похвало́ і всіх христоімени́тих люде́й ра́дованіє, ублажа́єм по́двиги твоя́ і с любо́вію вопіє́м ті:","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць в послі́дняя времена́ показа́ тя, преподо́бне о́тче, ра́вна А́нгелом невеще́ственним твої́м житіє́м, священнотаї́нника же благода́ті, бу́дущая я́ко настоя́щая прозира́юща, і іспові́дника тве́рда, гоне́нія бо і муче́нія за Христа́ претерпі́л єси́; ті́мже воспіва́єм тебі́ сицева́я:","Ра́дуйся, роди́телей благочести́вих о́трасле благоуха́нная;","ра́дуйся, ізді́тська благода́тію Ду́ха Свята́го просвіще́нний.","Ра́дуйся, благоче́стію роди́тельському ізмла́да поревнова́вий;","ра́дуйся, во о́трочестві ко ста́рцю О́птинському Амвро́сію на благослове́ніє приведе́нний.","Ра́дуйся, притру́дноє і́ночеськоє житіє́ вседу́шні возлюби́вий;","ра́дуйся, храни́ти чи́сті за́повіді Бо́жия ізмла́да себі́ положи́вий.","Ра́дуйся, от ю́ности твоєя́ вся ми́ра сего́ кра́сная Бо́га ра́ди презрі́вий;","ра́дуйся, во оби́тель О́птинськую ста́рчеськаго ра́ди наставле́нія прише́дий.","Ра́дуйся, во́лі своєя́ всесоверше́нноє отверже́ніє показа́вий;","ра́дуйся, наста́вником духо́вним смире́нно себі́ покори́вий.","Ра́дуйся, преподо́бнаго Іо́сифа кро́ткий учениче́ і послу́шниче;","ра́дуйся, ста́рця богоно́снаго Некта́рія сподви́жниче і сотаї́нниче.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 2","ps":["Ви́дя преди́вний Некта́рій, я́ко кро́тости ра́ди твоєя́ і смире́нія дарова́ ті Небе́сний Дарода́тель благода́ть прозрі́нія духо́внаго, преє́мника своєго́ тя нарече́, \"лі́то\" імену́я, милосе́рден бо к стра́ждущим яви́лся єси́; ті́мже науча́ємся всіх благи́х Промисли́телю пі́ти: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум благода́тію Ду́ха Свята́го просвіще́н імі́я, єва́нгельськи Бо́га возлюби́л єси́, су́єтную же сла́ву мирську́ю оста́вль, О́птинськия при́стани дости́гл єси́, іді́же послі́довал єси́ Христу́ со духо́вними наста́вники твої́ми, житію́ по́стничеському приліжа́ во смире́нії; сего́ ра́ди ві́рнії воспіва́єм ті:","Ра́дуйся, ті́сний і приско́рбний путь па́че простра́ннаго возлюби́вий;","ра́дуйся, многом'яте́жіє ми́ра ле́стнаго презрі́вий.","Ра́дуйся, я́ко боголюбе́зную чистоту́ душе́вную і тіле́сную сохрани́л єси́;","ра́дуйся, я́ко посто́м і моли́твою тлі́нная на нетлі́нная преміни́л єси́.","Ра́дуйся, я́ко по́стним воздержа́нієм плоть твою́ ду́хові покори́л єси́;","ра́дуйся, я́ко послуша́нієм і безмо́лвієм стра́сті душе́вния умертви́л єси́.","Ра́дуйся, я́ко слеза́ми покая́нія зе́млю се́рдця твоєго́ напої́л єси́;","ра́дуйся, я́ко земна́я отри́нув, ум твой к Небе́сним возве́л єси́.","Ра́дуйся, я́ко сладча́йшеє і́м'я Ісу́сово во умі́ твоє́м при́сно носи́л єси́;","ра́дуйся, я́ко святи́х Святі́йшим Сло́вом, Христо́м, Преві́чнаго Бо́га Отця́ позна́л єси́.","Ра́дуйся, я́ко благода́ть Уті́шителя чистото́ю се́рдця твоєго́ стяжа́л єси́;","ра́дуйся, я́ко си́лу прозрі́нія і ста́рчества от Бо́га прия́л єси́.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 3","ps":["Си́лою благода́ті Бо́жия ста́рці святі́ї О́птинстії вожда́ху тя ті́сним путе́м житія́ і́ночеськаго, да і жре́бій па́стирський і по́двиг іспові́данія Христа́ расп'я́таго і воскре́сшаго по́сліжде воспри́ймеши, Єму́же во всем житії́ твоє́м воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іми́й в се́рдці твоє́м ві́ру тве́рду, наде́жду же несумне́нну і любо́в і́стинну ко Христу́ Бо́гу на́шему, єгда́ воздвиго́ша богобо́рнії гоне́ніє на Це́рков Госпо́дню, смире́нні і со тре́петом свяще́нства дар чрез возложе́ніє рук архієре́йських прия́л єси́, да спасу́ться от злосмра́днаго безбо́жия ги́бнущії; ті́мже воспису́єм ті такова́я:","Ра́дуйся, Христу́, До́брому Па́стирю, усе́рдні послужи́вий;","ра́дуйся, священнотаї́нниче Христо́в, дара́ми Ду́ха Свята́го просія́вий.","Ра́дуйся, ду́шу твою́ за слове́сния о́вці Госпо́дні полага́вий;","ра́дуйся, путь спаси́тельний взиску́ющим Ца́рствія пропові́давий.","Ра́дуйся, ко го́рнему Ієрусали́му лю́дем вождю́ богому́дрий;","ра́дуйся, во благоче́стії тружда́ющимся наста́вниче богодарова́нний.","Ра́дуйся, обурева́ємим страстьми́ гріхо́вними до́брий ко́рмчий;","ра́дуйся, немощни́м і неіску́сним учи́телю терпіли́вий.","Ра́дуйся, ізнемога́ющим от уни́нія і печа́лі благода́тноє утіше́ніє;","ра́дуйся, безпомо́щним скоропослу́шливий помо́щниче.","Ра́дуйся, чернори́зцем преди́вний оте́ць і ста́рець прозорли́вий;","ра́дуйся, уста́вов О́птинських храни́телю ре́вностний.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 4","ps":["Бу́ри гоне́ній лю́тих, безбо́жною вла́стію воздвиза́ємия, не убоя́вся, со всі́ми новому́ченики і іспові́дники Це́ркве Ру́ськия і́го на себі́ благо́є Христо́во под'я́л єси́ і суро́вих степе́й Казахста́нських дости́гл єси́, іді́же безчи́сленноє мно́жество страда́лець безви́нних го́ркою сме́ртію сконча́шася; о ї́хже упокоє́нії А́гнцю Бо́жию, о́тче благосе́рде, моли́тви приноси́л єси́, надгро́бноє рида́ніє творя́ піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша, я́ко по всей землі́ Ру́сстій ча́да церко́вная смерть лю́тую і жесто́кая гоне́нія за ві́ру оте́чеськую правосла́вную приє́млють, смире́нні в путь ско́рбний поте́кл єси́ і зи́му го́ркую, і пусти́нную тяготу́ лі́тнюю, і я́рость о́гненную муче́ній узи́лищних терпі́нієм твої́м препобіди́л єси́, сла́дости духо́внаго блаже́нства ві́чнаго вкуси́в; сего́ ра́ди вопіє́м ті сицева́я:","Ра́дуйся, нището́ю духо́вною Ца́рство Небе́сноє наслі́дивий;","ра́дуйся, пла́чем о грісі́х утіше́ніє Христо́во приє́мий.","Ра́дуйся, я́ко а́лчбою і жа́ждею пра́вди Бо́жия нетлі́нния пи́щі Небе́сния наси́тился єси́;","ра́дуйся, я́ко ми́лостію є́же к бли́жнім сострада́нія ми́лость Бо́жию восприя́л єси́.","Ра́дуйся, во страда́ніїх твої́х чи́стим се́рдцем Бо́га узрі́вий;","ра́дуйся, вражду́ющия умиротворя́яй, ті́мже і син Бо́жий нарече́нний.","Ра́дуйся, ізгна́нієм пра́вди ра́ди Ца́рства Небе́снаго приобщи́вийся;","ра́дуйся, в поноше́нії і злосло́вії от нечести́вих во Христа́ облеки́йся.","Ра́дуйся, Боже́ственному Промишле́нію себі́ коне́чні вручи́вий;","ра́дуйся, во ізгна́нії от земна́го оте́чества Іо́сифу прекра́сному подража́вий.","Ра́дуйся, в терпі́нії болі́зней і скорбе́й І́овлеву крі́пость показа́вий;","ра́дуйся, в кро́тком терпі́нії гоне́ній Дави́дово смире́ніє яви́вий.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́, О́птинськими ста́рці возжже́нная, яви́лся єси́, о́тче Севастія́не досточу́дне: умо́м бо чи́стим, се́рдцем же смире́нним і душе́ю кро́ткою слу́жбу Бо́гу принося́, біди́ претерпі́л єси́, і гоне́нія, і болі́зні, іспові́данія ра́ди Боже́ственния І́стини, ю́же житіє́м і словеси́ твої́ми всім во у́зах і ізгна́нії су́щим явля́л єси́, немощни́я укріпля́я і ві́рния воздвиза́я благода́рні пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше у́зници кро́тость і любо́в твою́, удивля́хуся кра́йнему терпі́нію твоєму́. Ми же, ві́дяще многотру́дная страда́нія твоя́ і болі́зні, ублажа́єм тя, апо́стольськи во узи́лищі благовісти́вшаго, і помраче́нния сми́сли челові́ков просвіти́вшаго, і я́же пре́жде дия́волом уловле́нния ко Христу́ приве́дшаго, і благода́рні зове́м ті:","Ра́дуйся, кри́не благоуха́нний, в пусти́нях Караганди́нських процвіти́й;","ра́дуйся, христоподража́тельними доброді́тельми ізсо́хшия ду́ші ісціли́вий.","Ра́дуйся, неяде́нієм і жа́ждею надо́лзі в темни́ці томи́мий;","ра́дуйся, в лише́ніїх сих Христа́ тебі́ посо́бствующа обріти́й.","Ра́дуйся, ніколи́же по́стнаго воздержа́нія оста́вивий;","ра́дуйся, моли́твою к Бо́гу при́сно пламене́яй.","Ра́дуйся, благода́тію Ду́ха Свята́го неви́димо укріпля́ємий;","ра́дуйся, си́лою єя́ лю́ди заблу́ждшия от дия́вольськия сі́ті ізима́яй.","Ра́дуйся, ко єди́ній, Святі́й, Собо́рній і Апо́стольстій Це́ркві заблужда́ющия приводя́й;","ра́дуйся, покая́нію і́стинному і благочести́вой жи́зні їх науча́яй.","Ра́дуйся, пре́жде бісово́м служи́вшия ко Христу́ обрати́вий і спаси́й;","ра́дуйся, тім плач неуті́шний духово́м зло́би поднебе́сним наведи́й.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 6","ps":["Пропові́дуєть страна́ Казахста́нськая, приє́мши в зе́млю свою́ то́ки крове́й новому́чеников Це́ркве Ру́ськия, равноа́нгельноє твоє́ житіє́, равноапо́стольния труди́ твоя́ і чуде́с мно́жество, преподо́бне ста́рче Севастія́не іспові́дниче, науча́ющи ві́рних Подвигополо́жнику Христу́ Ісу́су пі́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ всім лю́дем казахста́нським от гра́да Караганди́ світи́льник доброді́телей твої́х, о́тче Севастія́не: ти бо я́ко о́блак сві́тел і росоно́сен яви́лся єси́, пла́мень пра́ведно дви́жимаго на ни за гріхи́ на́ша гні́ва небе́снаго утиша́я, ізсо́хшая сердця́ на́ша оживля́я і плоди́ доброді́телей приноси́ти помога́я всім воспіва́ющим ті такова́я:","Ра́дуйся, безпло́дную пусти́ню Казахста́нськую плода́ми доброді́телей твої́х облагоуха́вий;","ра́дуйся, град Караганду́, я́ко мі́сто страда́ній христия́н благочести́вих, се́рдцем возлюби́вий.","Ра́дуйся, во і́м'я Пресвяти́я Богоро́диці пречу́дний храм та́мо устро́ївий;","ра́дуйся, в том в па́м'ять скита́ О́птинськаго приде́л Крести́телю Іоа́нну воздви́гнувий.","Ра́дуйся, в хра́мі сем, я́ко в но́вій оби́телі О́птиной, вся благолі́пно учини́вий;","ра́дуйся, в моли́тві і ста́рчестем о душа́х попече́нії неле́стно подвиза́вийся.","Ра́дуйся, я́ко во дні і в нощі́ во бді́нії при́снім пребива́л єси́;","ра́дуйся, я́ко мно́гия і́ноки і ієре́ї, от гони́телей разсі́янния, на мі́сті сем собра́л єси́.","Ра́дуйся, я́ко миря́н мно́жество под благода́тний кров Цари́ці Небе́сния приве́л єси́;","ра́дуйся, я́ко мона́хом наста́вник прему́дрий яви́лся єси́.","Ра́дуйся, я́ко і всему́ ста́ду твоєму́ па́стир і учи́тель предо́брий бил єси́;","ра́дуйся, не я́ко господствуяй, но я́ко служа́й со обраще́нними тобо́ю пожи́л єси́.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 7","ps":["Хотя́ Оте́чества Небе́снаго дости́гнути, а́ще і пе́рстною пло́тію обложе́н, оба́че дух твой моли́твою воскриля́л єси́ і, к Бо́гу умо́м твої́м восходя́, го́рнія добро́ти зрел єси́ сла́ву, со всі́ми А́нгельськими си́лами воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя граждани́на Ієрусали́ма го́рняго Ви́шній Цар показа́, ми́ра бо кра́сная вся, я́ко тлі́нная, ні во что́же вміни́л єси́, пусти́нноє житіє́ со ста́рці равноа́нгельними предпочита́юща, і душі́ одія́ніє чистото́ю убіли́в, і в ри́зу свяще́нства обле́кся, поноше́нія і гоне́нія Христа́ ра́ди с ра́достію претерпі́л єси́, зане́же украси́лся єси́ дара́ми Ду́ха преди́вними; отню́дуже ві́рнії научи́шася пі́ти ті:","Ра́дуйся, от ю́ности в зако́ні Госпо́дні поуча́вийся;","ра́дуйся, во і́ночестім житії́ невеще́ственним чино́м уподо́бивийся.","Ра́дуйся, духоно́сних ста́рцев О́птинських і всіх преподо́бних слико́вниче;","ра́дуйся, добропобе́дним му́чеником і іспові́дником Христо́вим соприча́стниче.","Ра́дуйся, Бо́жиїх священнотаї́нников благогові́йний сослужи́телю;","ра́дуйся, страда́льцев безви́нних му́жественний предста́телю.","Ра́дуйся, па́стирю, ду́шу за ста́до твоє́ положи́ти гото́вий;","ра́дуйся, мно́гія му́ки і злохуле́нія за Христа́ претерпі́вий.","Ра́дуйся, тве́рдоє ві́ри іспові́даніє непрекло́нне яви́вий;","ра́дуйся, вся ві́рния во благоче́стії ізря́дне укріпи́вий.","Ра́дуйся, скорбми́ мно́гими в ра́дость Го́спода вше́дий;","Ра́дуйся, ра́дость о́ную всім приходя́щим к тебі́ оби́льно подая́й.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 8","ps":["Стра́нно чу́до бі, преподо́бне о́тче Севастія́не, моли́тва твоя́, кро́тости і смире́нія іспо́лнена: тоя́ бо сві́том ви́ну озаря́єм, Христо́в ум стяжа́л єси́, неізглаго́ланная та́їнства познава́я і бу́дущая прозира́я, всіх же притека́ющих к тебі́ от бісо́вських нападе́ній свобожда́я і на путь і́стини наставля́я, вопію́щих к Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь жела́нієм боже́ственним об'я́т бил єси́, свяще́нне, і в світоза́рния дні Пасха́льнаго торжества́ богоно́сною душе́ю твоє́ю в Небе́сния оби́телі возше́л єси́, іді́же Престо́лу Пресвяти́я Тро́йці со всі́ми святи́ми предстої́ши і сли́шиши от нас похва́льная сія́:","Ра́дуйся, от земна́го торжества́ Пасха́льнаго в ра́дость Па́схи ві́чния возше́дий;","ра́дуйся, на землі́ всеконе́чні гріху́ уме́рий і на Небесі́ нетлі́нній жи́зні приобщи́вийся.","Ра́дуйся, я́ко святи́х Святі́йшему Ісу́су Сладча́йшему во сла́ві ві́чній предстої́ши;","ра́дуйся, я́ко о всіх чту́щих па́м'ять твою́ пред Ним хода́тайствуєши.","Ра́дуйся, сугу́бую благода́ть от Христа́ приє́мий і́щущим спасе́нія помога́ти;","ра́дуйся, да́ра сподо́бивийся неду́ги душе́вния і тіле́сния врачева́ти.","Ра́дуйся, ми́лости Бо́жия струє́ неізсяка́ємая;","ра́дуйся, ра́дости духо́вния, тишини́ же і ми́ра істо́чниче неісчерпа́ємий.","Ра́дуйся, сві́тлий о́блаче, зной страсте́й гріхо́вних утоля́яй;","ра́дуйся, росо́ благода́тная, сердца́ ві́рних ороша́ющая і веселя́щая.","Ра́дуйся, світи́льниче, сві́том доброді́телей в нощі́ ми́ра сего́ нам при́сно сія́яй;","ра́дуйся, гро́зде виногра́да Христо́ва, благода́тію Ду́ха Всесвята́го пита́яй нас і веселя́й.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє удиви́ся твоєму́ пресла́вному в го́рняя восхожде́нію, пресві́тлия бо оби́телі Небе́сния прия́ша тя, Севастія́не прозорли́ве, я́ко но́ваго насе́льника, іді́же с безпло́тними Си́лами і всі́ми святи́ми водворя́єшися і лику́єши, ко Го́споду взива́я: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї суєму́дреннії послу́шаша гла́са человікоуби́йці су́ща іскони́ і отця́ лжі вся́кия дия́вола, і звіре́м ди́віїм подо́б'яся, устреми́шася на Неві́сту чи́стую Христо́ву, Це́рков Правосла́вную, єя́же яви́ тя Подвигополо́жник тогда́ світи́льника і ізря́дна іспові́дника; ті́мже воспіва́єм ті любо́вію:","Ра́дуйся, муче́ній за іспові́даніє і́стиннаго Бо́га не устраши́вийся;","ра́дуйся, ду́шу твою́ за ві́ру правосла́вную положи́ти не отреки́йся.","Ра́дуйся, преще́ній безбо́жния вла́сті не убоя́вийся;","ра́дуйся, к позна́нію Бо́га во ізгна́нії твоє́м і мучи́телей привести́ потща́вийся.","Ра́дуйся, ізсо́хшую серде́ць їх пусти́ню сле́зною моли́твою твоє́ю напоі́вий;","ра́дуйся, кро́тостію і терпі́нієм сі́мена Єва́нгельськая в ду́ші їх посе́явий.","Ра́дуйся, гро́зния ту́чі те́мних їх помисло́в си́лою моли́тв твої́х разсі́явий;","ра́дуйся, к покая́нію і сокруше́нію серде́чному тіх приводи́вий.","Ра́дуйся, врата́ Ца́рствія Небе́снаго тім отверза́вий;","ра́дуйся, водо́ю от кла́дязя тіх напоя́я, во́ду нетлі́нную їм подава́вий.","Ра́дуйся, от него́же у́зници пи́щу і оде́жду ще́дре прийма́ху;","ра́дуйся, єго́же і ско́ти в зи́мній мраз тепло́м свої́м ізря́дне согріва́ху.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 10","ps":["Спасе́нія іски́й, послі́довал єси́ Влади́ці Христу́, іспові́дниче святи́й Севастія́не, отве́ргся себе́ і взем крест свой, я́коже Госпо́дь рече́; ті́мже смире́нія путе́м пости́гл єси́ висоту́ Небе́сную, Бо́гові любо́вію поя́: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну несокруши́му обріто́ша тя христоимени́тії лю́діє землі́ Ру́ськия, по кончи́ні бо сла́вній твоє́й повсю́ду чудеса́ соверша́єши ізря́дна, я́ко от Бо́га приє́м віне́ць нетлі́нен і сла́ву ві́чну; ті́мже всі ві́рнії благода́рні воспіва́ють тебі́ си́це:","Ра́дуйся, Христа́, Бо́жию Си́лу і Прему́дрость, тве́рдо пред челові́ки іспові́давий;","ра́дуйся, я́ко і Госпо́дь іспові́да тя пред Отце́м Свої́м Небе́сним і святи́ми А́нгели.","Ра́дуйся, блиста́нієм Трисо́лнечнаго Сві́та ни́ні осія́нний;","ра́дуйся, сокро́вище моще́й твої́х в наслі́діє ча́дом оста́вивий.","Ра́дуйся, я́ко мо́щі твоя́ вся́кия ско́рби і болі́зні ісціля́ють;","ра́дуйся, я́ко ти́я в печа́лі су́щим і смуще́нії весе́ліє прети́хоє бива́ють.","Ра́дуйся, я́ко ти́я Воскресе́ніє всео́бщеє немо́лчно возвіща́ють;","ра́дуйся, я́ко от моще́й твої́х уя́звленнії бі́си отбіга́ють.","Ра́дуйся, ча́ше, да́ри Бо́жия преізоби́льно ізлива́ющая;","ра́дуйся, сосу́де, ми́ро цельбоно́сноє боля́щим істоча́яй.","Ра́дуйся, світи́льниче, су́щих во тьмі і сі́ні сме́ртній сві́том Христо́вим озаря́ющий;","ра́дуйся, кади́ло, фимія́м моли́тв богоприя́тних при́сно вознося́щеє.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственно Зижди́телю прино́сим, я́ко дарова́ тя всім і́щущим спасе́нія тве́рда засту́пника; ті́мже, препо́добне Севастія́не, ру́ку по́мощі нам ско́ро низпосли́, і гріхми́ при́сно погружа́ємих із глубини́ губи́тельния ізведи́, і про́чеє вре́м'я житія́ в покая́нії сконча́ти сподо́би, да при́сно Бо́гові поє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє світи́ло, заря́ми немерца́ющаго сві́та Пресвяти́я Тро́йці сія́ющеє, всей землі́ Казахста́нстей яви́лся єси́, преди́вне, луча́ми доброді́телей твої́х тьму поги́бельную разгоня́я і теплото́ю богоприя́тних моли́тв твої́х сердца́ ві́рних согріва́я, і́же с любо́вію воспису́ють ті сицева́я:","Ра́дуйся, Казахста́нськия страни́ благода́тноє сокро́вище і украше́ніє;","ра́дуйся, Русі́ Правосла́вния ра́дованіє і утіше́ніє.","Ра́дуйся, пу́стині О́птинськия благопло́дноє прозябе́ніє;","Ра́дуйся, гра́да Караганди́ покро́ве і удобре́ніє.","Ра́дуйся, многотеку́щая ріко́, сердця́ на́ша спаси́тельним уче́нієм напоя́ющая;","ра́дуйся, в мо́рі многоразли́чних напа́стей погиба́ющим наде́жноє приста́нище.","Ра́дуйся, злосмра́діє страсте́й от приходя́щих к тебі́ прогоня́яй;","ра́дуйся, от іскуше́ній ми́ра, пло́ті і дия́вола хода́тайством твої́м свобожда́яй.","Ра́дуйся, нераска́янних грі́шников к соверше́нному покая́нію воздвиза́яй;","ра́дуйся, лука́вая по́лчища бісо́вськая пресла́вне побіжда́яй.","Ра́дуйся, ран гріхо́вних врачу́ благоїску́снейший;","ра́дуйся, сія́нієм благода́ті Бо́жия ду́ші на́ша озаря́ющий.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 12","ps":["Благода́ть, от Бо́га ті да́нную, сві́дуще, о́тче ми́лостивий, я́ко скоропослу́шлива тя прилі́жно умоля́єм: вознеси́ дерзнове́нноє моле́ніє твоє́ ко Престо́лу Тро́йці Живонача́льния, да сподо́бимся безпреткнове́нно прейти́ от землі́ на Не́бо; моли́ же, свя́те, Всеблага́го Бо́га і о гра́ді твоє́м, і о святі́м хра́мі, єго́же преподо́бничеськима рука́ма твої́ма созда́л єси́, і о хра́мі, в не́мже чудото́чния мо́щі твоя́ почива́ють, да всі ві́рою, благогові́нієм і стра́хом Бо́жиїм воспіва́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́вная діла́ Бо́жия і промишле́ніє Єго́ о Це́ркві Ру́сстій, зрим О́птину пу́стинь, мно́гая лі́та в поруга́нії і разоре́нії би́вшу, па́ки ни́ні украси́вшуся і мо́щі цільбоно́сния ста́рцев свої́х обрі́тшу; град Караганда́ оби́телі сей свесели́ться, стяжа́ бо сокро́вище себі́, мо́щі єди́наго от собо́ра О́птинськаго; ті́мже, чудя́щеся, с любо́вію тебі́, іспові́дниче, вопіє́м:","Ра́дуйся, Бо́га Отця́ Безнача́льнаго служи́телю ізбра́нний;","ра́дуйся, А́гнця Бо́жия Христа́ му́жественний іспові́дниче.","Ра́дуйся, Бо́га Ду́ха Всесвята́го хра́мі нерукотво́рний;","ра́дуйся, честно́є Пресвяти́я Тро́йці носи́ло і похвале́ніє.","Ра́дуйся, в невече́рнім дні Ца́рствія Бо́жия почива́яй;","ра́дуйся, трисвяту́ю піснь со А́нгели і всі́ми святи́ми воспіва́яй.","Ра́дуйся, заря́ми о́гненними благода́ті Бо́жия сія́яй;","ра́дуйся, я́ко світи́ло світоза́рноє го́рняго Ца́рствія блиста́яй.","Ра́дуйся, сві́том благода́ті всіх чту́щих па́м'ять твою́ просвіща́яй;","ра́дуйся, рая́ Ісу́сова дре́во чудото́чноє, мног плод на по́льзу правосла́вним творя́щеє.","Ра́дуйся, виногра́да Христо́ва розго́ благопло́дная, пита́ющая нас і веселя́щая;","ра́дуйся, Свята́го Правосла́вія непоколеби́мий сто́лпе і крі́пкоє утвержде́ніє.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 13","ps":["О преподо́бне о́тче Севастія́не, ві́ри благочести́вия іспові́дниче і кро́тости преди́вния сокро́вище! Прийми́ ни́ні сіє́ в похвалу́ твою́ от усе́рдія на́шего приноси́моє благодаре́ніє, і дерзнове́нним твої́м хода́тайством іспроси́ нам ві́ри непоро́чни соблюде́ніє, ми́ра умире́ніє, от гла́да і па́губи ізбавле́ніє, гріхо́в оставле́ніє і блаже́нния ві́чния жи́зні наслі́діє, да с тобо́ю і со всі́ми святи́ми поє́м ра́достно: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць в послі́дняя времена́ показа́ тя, преподо́бне о́тче, ра́вна А́нгелом невеще́ственним твої́м житіє́м, священнотаї́нника же благода́ті, бу́дущая я́ко настоя́щая прозира́юща, і іспові́дника тве́рда, гоне́нія бо і муче́нія за Христа́ претерпі́л єси́; ті́мже воспіва́єм тебі́ сицева́я:","Ра́дуйся, роди́телей благочести́вих о́трасле благоуха́нная;","ра́дуйся, ізді́тська благода́тію Ду́ха Свята́го просвіще́нний.","Ра́дуйся, благоче́стію роди́тельському ізмла́да поревнова́вий;","ра́дуйся, во о́трочестві ко ста́рцю О́птинському Амвро́сію на благослове́ніє приведе́нний.","Ра́дуйся, притру́дноє і́ночеськоє житіє́ вседу́шні возлюби́вий;","ра́дуйся, храни́ти чи́сті за́повіді Бо́жия ізмла́да себі́ положи́вий.","Ра́дуйся, от ю́ности твоєя́ вся ми́ра сего́ кра́сная Бо́га ра́ди презрі́вий;","ра́дуйся, во оби́тель О́птинськую ста́рчеськаго ра́ди наставле́нія прише́дий.","Ра́дуйся, во́лі своєя́ всесоверше́нноє отверже́ніє показа́вий;","ра́дуйся, наста́вником духо́вним смире́нно себі́ покори́вий.","Ра́дуйся, преподо́бнаго Іо́сифа кро́ткий учениче́ і послу́шниче;","ра́дуйся, ста́рця богоно́снаго Некта́рія сподви́жниче і сотаї́нниче.","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Кондак 1","ps":["Ізбра́нний преє́мниче благода́ті ста́рчества О́птинськаго, в годи́ну гоне́ній лю́тих кро́ткий за ві́ру правосла́вную страда́льче, гра́ду Караганде́ богодарова́нний світи́льниче і всея́ страни́ Казахста́нськия неуси́пний храни́телю, Це́ркве Ру́ськия похвало́ і всіх христоімени́тих люде́й ра́дованіє, ублажа́єм по́двиги твоя́ і с любо́вію вопіє́м ті:","Ра́дуйся, преподо́бне о́тче Севастія́не, ві́ри правосла́вния іспові́дниче."]},{"h":"Молитва","ps":["О пречестна́я і свяще́нная главо́ і благода́ті Свята́го Ду́ха іспо́лненная, Спа́сово со Отце́м обита́лище, ста́рцев О́птинських учениче́ і преє́мниче, гра́да Караганди́ світлі́йшеє украше́ніє, Казахста́нськия страни́ богодарова́нний моли́твенниче, Це́ркве Ру́ськия па́стирю богопросла́вленний, си́рим і вдови́цям засту́пниче, немощни́м врачу́ безме́здний, пра́вило ві́ри і благоче́стія, преподо́бних сожи́телю і му́чеников соприча́стниче, богоно́сне о́тче наш Севастія́не досточу́дне! К тебі́ усе́рдно прибіга́юще, моле́ніє те́плоє прино́сим: от сокро́вищници твоєя́ пода́ждь і на́шему убо́жеству; смире́нієм твої́м на́шу горди́ню низложи́; безстра́стієм на́ша стра́сті попали́; бо́дрствованієм на́вик лі́ності от нас отжени́; сле́зними то́ки на́ше нечу́вствіє пробуди́; бді́нієм от нераде́нія нас возста́ви; моли́твами і в нас пла́мень моли́тви возжзи́; любо́вію нас братолю́бни сотвори́; пода́ждь же нам дух кро́тости і смире́нія, дух чистоти́ і благоче́стія; от страсте́й многонеду́жія нас свободи́ і ко і́стинному покая́нію приведи́. Ти бо во умі́ твоє́м непреста́нно імі́л єси́ на Кресті́ распе́ншагося за нас Си́на Бо́жия, Того́ сладча́йшеє і́м'я во умі́ і в се́рдці непреста́нно імі́ти і нас научи́, да любо́вію Тому́ пламені́юще, стра́шний о́ний день Су́дний сре́тити угото́вимся, і в Ца́рствіє Небе́сноє вни́ти с тобо́ю сподо́бимся, сла́вити і воспіва́ти Трієди́ную держа́ву Бо́га на́шего: Отця́, і Си́на, і Ду́ха Свята́го, во ві́ки. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Тро́йці Святи́я служи́телю, / земни́й а́нгеле і небе́сні челові́че, / духо́внаго О́птинськаго ста́рчества преє́мниче, / Христо́в священнотаї́нниче і іспові́дниче, / Ду́ха Свята́го оби́тель всечестна́я, / преподо́бне о́тче Севастія́не, досточти́ме, / іспроси́ ми́рові мир // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 3","ps":["В ра́дость Го́спода Воскре́сшаго вше́дшаго, / преподо́бним Оптинським ста́рцем слико́вника, / му́чеников і іспові́дников соприча́стника, / священнотаїнникам Бо́жиїм сослужи́теля, / зе́мна А́нгела і небе́сна челові́ка, / гра́да Караганди боголі́пноє украше́ніє, / Казахстанськия страни́ богомольця ізря́дна, / Це́ркві Ру́ськия похвалу́ / ублажи́м, ві́рнії, / с весе́лієм єму́ вопія́: / ра́дуйся, Севастія́не, преподо́бне о́тче наш."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче Севастія́не, і чтим святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче а́нгелов."]}],"notes":[]},{"u":"Акафіст священномученику Харалампію","e":"Akathist to the Hieromartyr Charalampus","secs":[{"h":"Кондак 1","ps":["Ізбра́нному страстоте́рпцю і уго́днику Бо́жию, ороси́вшему зе́млю честно́ю своє́ю кро́вію і плодоро́діє землі́ от Бо́га іспроси́вшему, похва́льная із глубини́ душі́ возглаша́єм пі́нія. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, священному́чениче Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгели на Небесі́ ра́довахуся непоро́чному житію́ твоєму́, священному́чениче Харала́мпіє, ти бо послі́довал єси́ святи́м проро́ком і апо́столом, наставля́я лю́ди на путь спасе́нія. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, вели́кий світи́льниче Це́ркве;","ра́дуйся, пропові́дниче пра́вди.","Ра́дуйся, слове́с жи́зні ві́чния учи́телю;","ра́дуйся, ідолослуже́нія обличи́телю.","Ра́дуйся, і́мже сатана́ посрамля́ється;","ра́дуйся, і́мже ві́ра Христо́ва прославля́ється.","Ра́дуйся, я́ко і́менем Христо́вим вра́жию си́лу низложи́л єси́;","ра́дуйся, я́ко си́лою Бо́жиєю ко́зні бісо́вськия разруши́л єси́.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще житіє́ твоє́, благоче́стія і чистоти́ іспо́лненноє, і сли́шаще пла́менную про́повідь твою́, служи́теліє Го́спода Ісу́са Христа́, укріпле́ни би́вше во ві́рі і благоче́стії, возра́довашася, пою́ще всіх Творцю́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом, просвіще́нним от Го́спода, іспо́лнен бив і долголе́тія му́дростію укра́шен, не восхоті́л єси́ послу́шати сові́та Лукія́на іге́мона є́же приступи́ти с же́ртвами к бого́м безду́шним, і ве́ліїх муче́ній не убоя́лся єси́. Ті́мже вопіє́м ті:","Ра́дуйся, угро́зи Лукія́на презрі́вий;","ра́дуйся, посто́м і моли́твою долголі́тіє стяжа́вий.","Ра́дуйся, благ неви́димих взиска́телю;","ра́дуйся, креста́ Христо́ва побі́дний носи́телю.","Ра́дуйся, мучи́телі твоя́ возлюби́вий;","ра́дуйся, сердця́ їх ко Христу́ обрати́вий.","Ра́дуйся, і́мже і́стинная ві́ра утверди́ся;","ра́дуйся, і́мже пре́лесть бісо́вськая посрами́ся.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укріпле́н бив, побіди́л єси́ ве́лія муче́нія, і стру́жем ногтьми́ желі́зними, моли́лся єси́ ко Го́споду, ісціля́я болі́зні твої́х мучи́телей і воспіва́я Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй ве́лію ми́лость Госпо́дню, удосто́їлся єси́, священному́чениче Харала́мпіє, гла́са Бо́жия, от о́блака ісходя́ща, Єму́же вне́млюще, благогові́йно рцем:","Ра́дуйся, світи́льниче земни́й;","ра́дуйся, в Небе́сния оби́телі пресели́вийся.","Ра́дуйся, собесі́дниче А́нгелом;","ра́дуйся, сожи́телю проро́ком.","Ра́дуйся, апо́столом сопресто́льниче;","ра́дуйся, сової́нственниче му́чеником.","Ра́дуйся, бесі́ди Госпо́дні удосто́ївийся;","ра́дуйся, я́ко усли́ша Госпо́дь моли́тви твоя́.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́ря ве́лія гра́ди, ві́си і всяк злак се́льний разруша́єть; го́ршія бу́ри жите́йськія зло́би, неві́рія і злодія́ній челові́чеських душі́ на́ша смуща́ють і житіє́ на́ше мра́ком покрива́ють. Но помози́ нам, пресла́вний священному́чениче, почита́ющим по́двиги і страда́нія твоя́ і пою́щим о тебі́ ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав нечести́вий цар ри́мський Севи́р, я́ко в муче́ніїх неодоле́н яви́лся єси́, іспо́лнися гні́ва; ти же, долготерпіли́во, єгда́ о́строє желі́зноє гво́здіє вби́то бисть в честно́є ті́ло твоє́, нічто́же глаго́ля вопре́ки мучи́телем твої́м, вся сія́ во весе́лії і ра́дости претерпі́л єси́. Сего́ ра́ди ублажа́єм долготерпі́ніє твоє́ зва́нії си́ми:","Ра́дуйся, о́бразе кро́тости духо́вния;","ра́дуйся, долготерпі́нієм Го́споду Ісу́су Христу́ подража́вий.","Ра́дуйся, я́ко і безслове́сная твар преди́вному терпі́нію твоєму́ ужаса́шеся;","ра́дуйся, я́ко Госпо́дь Бог с тобо́ю в муче́ніїх твої́х преби́л єсть.","Ра́дуйся, мно́жество люде́й долготерпі́нієм твої́м приведи́й ко Го́споду;","ра́дуйся, от Го́спода просла́вленний.","Ра́дуйся, ісціле́ній істо́чниче;","ра́дуйся, челові́ком помо́щниче.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ бил єси́ жені́ ні́коєй, я́же, ви́дящи страда́нія твоя́ і умили́вшися се́рдцем, велегла́сно возгласи́: челові́че Бо́жий, честна́ єсть ста́рость твоя́, і Бог с тобо́ю єсть, в Него́же ві́ровати і́мам, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя цар Севи́р во ісціле́нії ні́коєго челові́ка, бісо́м одержи́ма, чудоде́йственную си́лу Христо́ву, в тебі́, досточу́дний священному́чениче, обита́ющую, зіло́ удиви́ся і рече́: воі́стину вели́к єсть Бог христия́нський! Сего́ ра́ди і ми, восхваля́юще страда́нія і чудеса́ твоя́, пресла́вний іспові́дниче Христо́в, взива́єм ті ра́достно:","Ра́дуйся, чудотво́рче преди́вний;","ра́дуйся, ві́ри побо́рниче побідоно́сний.","Ра́дуйся, от о́гненнаго жже́нія невреди́м преби́вий;","ра́дуйся, чудеси́ твої́ми неві́рующія лю́ди сві́том Богопозна́нія озари́вий.","Ра́дуйся, житіє́м твої́м і́м'я Бо́жиє просла́вивий;","ра́дуйся, єго́же, я́ко до́браго во́їна Христо́ва, дия́вол трепе́щеть.","Ра́дуйся, єго́же моли́твою неду́зі врачу́ються;","ра́дуйся, єго́же предста́тельством ві́рнії жизнь ві́чную наслі́дствують.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник му́жественний бил єси́, всехва́льний Харала́мпіє, єгда́ глаго́лал єси́ царе́ві: мно́го м'я по́льзують му́ки; єли́ко бо ті́ло моє́ ра́нами раздробля́ється, толи́ко ра́дується во мні дух мой. Вне́млюще словесе́м сим, мно́гоє мно́жество люде́й іспові́даху Го́спода Ісу́са Христа́ і віне́ць му́ченичеський прия́ша, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ Бо́жиє всемогу́щество і яви́ся стра́шноє Бо́жиє преще́ніє, єгда́ нечести́вії твої́ мучи́теліє хули́ на Христа́ Го́спода глаго́лаша безсту́дно: земля́, я́ко лист, колеба́шеся, і сли́шахуся сви́ше от о́блак стра́шнії гла́си, і бя́ху блиста́нія і гро́ми; моли́тву же тебі́ сотво́ршу, преста́ Бо́жиє стра́шноє преще́ніє. Ті́мже вопіє́м ті:","Ра́дуйся, го́рдих обличи́телю;","ра́дуйся, нищети́ духо́вния учи́телю.","Ра́дуйся, ху́льников і́мене Госпо́дня низложи́телю;","ра́дуйся, от гні́ва Госпо́дня челові́ки ізбавля́яй.","Ра́дуйся, блиста́нія і гро́ми небе́сния моли́твою утиша́яй;","ра́дуйся, омертве́вшия от стра́ха челові́ки воскреси́вий.","Ра́дуйся, ве́ліє незло́біє к мучи́телем твої́м яви́вий;","ра́дуйся, єго́же ра́ди Госпо́дь Бог возгремі́ во о́блаціх возду́шних.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ спасти́ чи́стую ду́шу дще́ре царе́ви Гали́ни, той яви́ тя Госпо́дь, о Харала́мпіє, я́ко а́нгела сві́тла, му́дра учи́теля і апо́стола ві́ри Христо́ви. І вне́млющи словесе́м твої́м, блаже́нная Гали́на уми́лися се́рдцем і Бо́гу возгласи́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя Іо́сифа показа́ Госпо́дь Бог, єгда́ вразуми́ тя ізвісти́ти, прему́дре, сказа́ніє би́вшаго блаже́нній Гали́не со́ннаго виді́нія. Ви́ді бо мно́жество водно́є, є́же єсть дарова́ніє Ду́ха Свята́го, ви́ді сад вели́к при вода́х мно́гих, рай Госпо́день, і в нем ви́ді виногра́д красе́н, пра́ведних водворе́ніє, і стра́жа мі́ста того́, Христа́ Бо́га, взе́млюща овцю́ на ра́мена Своя́. Ті́мже зове́м ті:","Ра́дуйся, ста́рцев украше́ніє;","ра́дуйся, прия́телище даро́в Ду́ха Свята́го.","Ра́дуйся, я́ко с ли́ки а́нгельськими славосло́виши Го́спода;","ра́дуйся, я́ко рай Госпо́день і жизнь ві́чную стяжа́л єси́.","Ра́дуйся, Пастиренача́льника Христа́ Бо́га на́шего служи́телю;","ра́дуйся, до́брий ста́да Христо́ва па́стирю і всего́ ми́ра моли́твенниче.","Ра́дуйся, виногра́да Госпо́дня украше́ніє;","ра́дуйся, Це́ркве Христо́ви утвержде́ніє.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нствія земна́го тече́ніє соверша́я, не восхоті́л єси́ во́лю нечести́вих ідолослужи́телей сотвори́ти і от ві́ри і́стинния отступи́ти, но вразумля́яй мучи́телі твоя́ богому́дрими словеси́ твої́ми, страда́нія за Христа́ восприя́л єси́ лю́тая, поя́ Го́споду Бо́гу піснь побі́дную: Аллилу́я."]},{"h":"Ікос 8","ps":["Все се́рдце своє́ я́ростію іспо́лнив, вдаде́ тя цар нечести́вий ні́коєй жені́ вдови́ці на поруга́ніє. Ти же, свя́те Харала́мпіє, входя́ в дом єя́, восклони́лся єси́ на ні́кий при хра́мині столп, і а́біє сухи́й той столп прозябе́; тогда́ жена́ тая́, зіло́ ужасну́вшися, к Бо́гу обрати́ся. Ми же во умиле́нії се́рдця взива́єм ті:","Ра́дуйся, Харала́мпіє, світи́льниче всесві́тлий;","ра́дуйся, уго́дниче Христо́в, благода́тію преіспо́лненний.","Ра́дуйся, я́ко і са́моє і́м'я твоє́ чу́дним житіє́м твої́м оправди́ся;","ра́дуйся, вдови́ць предста́тельство і заступле́ніє.","Ра́дуйся, уче́нієм твої́м мно́гія ко Христу́ приведи́й;","ра́дуйся, си́рих наде́ждо і укріпле́ніє.","Ра́дуйся, му́чеников красото́; ра́дуйся, человіколю́бія зерца́ло.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Все бога́тство ума́ твоєго́, вся благода́тния да́ри, я́же прия́л єси́ от Го́спода Бо́га, вдал єси́, свя́те Харала́мпіє, на служе́ніє челові́ком, науча́я всіх ві́рі і благоче́стію, і в час кончи́ни твоєя́ святи́я не о себі́ самі́м моли́лся єси́, но о спасе́нії і благоде́нствії всіх, почита́ющих святу́ю па́м'ять твою́, да наслажда́ються дарова́ній Го́спода Бо́га, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не возмого́ша воспі́ти досто́йно вели́чіє душі́ твоєя́ і неізрече́нноє твоє́ милосе́рдіє, і́мже див'я́щеся, ми, недосто́йнії, в простоті́ се́рдця зове́м:","Ра́дуйся, світи́льниче, мрак гріхо́вний от люде́й сві́том ві́ри отгоня́яй;","ра́дуйся, вінце́м му́ченичеським па́че звізд небе́сних блиста́яй.","Ра́дуйся, моли́твами твої́ми прозябе́нія хлі́бов у Христа́ Бо́га іспроша́яй;","ра́дуйся, я́ко кров твою́ честну́ю на зе́млю пролія́л єси́.","Ра́дуйся, я́ко то́ю кро́вію щедро́ти Госпо́дні нам грі́шним стяжа́л єси́;","ра́дуйся, я́ко Госпо́дь рекл єсть тебі́: бу́ди глаго́л твой ісціле́ніє боля́щим.","Ра́дуйся, я́ко прия́то бисть Бо́гом моле́ніє усте́н твої́х;","ра́дуйся, скорб'я́щих благода́тноє утіше́ніє.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу твою́, ні во что́же ті́ло твоє́ вміни́л єси́, святи́й му́чениче, і ме́чному на тя осужде́нію ра́довался єси́, поя́ благоді́ющему Го́споду Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і прибі́жище бисть ті, вели́кий Харала́мпіє, Госпо́дь Бог, яви́вийся ті во сла́ві Своє́й в час блаже́нния кончи́ни твоєя́. Ті́мже зове́м ті:","Ра́дуйся, дру́же Госпо́день;","ра́дуйся, я́ко Госпо́дь дає́ть ті, я́же про́сиши.","Ра́дуйся, стра́шную сла́ву Госпо́дню ви́дівий;","ра́дуйся, защи́тниче люде́й от гла́да і мо́ра.","Ра́дуйся, тлетво́рнаго возду́ха, погубля́ющаго плоди́ земни́я, си́лою Бо́жиєю отгони́телю;","ра́дуйся, трудолю́бія учи́телю.","Ра́дуйся, я́ко о здра́вії тіле́с і душ спасе́нії хода́тайствуєши;","ра́дуйся, я́ко і о ско́тіх, созда́нних на потре́бу челові́ков, пече́шися.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє а́ще і премно́гоє прино́сим ті, чудотво́рче, нічто́же твори́м ра́вно чудесе́м твої́м і мно́гому твоєму́ к нам грі́шним милосе́рдію, і́мже див'я́щеся, Го́сподеві зове́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник путеводи́телен бу́ди нам, Харала́мпіє, во тьмі гріхо́вній ходя́щим, і моли́ся ко Го́споду, є́же от'я́ти от нас вся́коє суєві́ріє, просвіти́ти наш ум сві́том Єва́нгелія і уче́ній, поле́зних ко труду́ земледі́льця і во вся́кой ве́щі, да просветле́ни умо́м, во умиле́нії се́рдця зове́м ті:","Ра́дуйся, неізсяка́ємоє ми́ро, на труд челове́ч ізлія́нноє;","ра́дуйся, весно́ Госпо́дня благоуха́нная.","Ра́дуйся, рая́ Госпо́дня дре́во прекра́сноє;","ра́дуйся, моли́тву, я́ко кади́ло благово́нноє, Го́сподеві возсила́яй.","Ра́дуйся, диха́нієм моли́тви твоє́й святи́я зе́млю согрева́яй;","ра́дуйся, предста́тельством твої́м пред Го́сподем росо́ю плоди́ земни́я ороша́яй.","Ра́дуйся, земледі́льцев покрови́телю; ра́дуйся, жи́зні їх строї́телю.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть, обеща́нную ті Го́сподем Бо́гом, є́же іспо́лнитися вся́кому проше́нію твоєму́, ві́дая, — “Молю́ Тя, Го́споди, — рекл єси́, — даждь сла́ву і́мені Твоєму́: іді́же положе́ни бу́дуть моя́ мо́щі, да не бу́деть на мі́сті том глад і мор, іли́ тлетво́рний возду́х, погубля́яй плоди́, но мир в челові́ціх і тілесе́м здра́віє, і душа́м спасе́ніє, і плодо́в земни́х ізоби́ліє да бу́дуть”. О Го́споди Бо́же наш! Ізли́й благода́ть Твою́ сію́ і на всіх нас, пою́щих Ті: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ чудеса́, пресла́вне Харала́мпіє, сла́вим долготерпі́ніє, страда́нія і ди́вную кончи́ну твою́, і чудя́щеся милосе́рдію твоєму́, си́це зове́м ті:","Ра́дуйся, о дождеіх благовре́менних пред Го́сподем хода́тайствуяй;","ра́дуйся, моли́твами твої́ми от бу́рі і гра́да нас сохраня́яй.","Ра́дуйся, ти бо проси́л єси́ плодоро́діє мі́сту, іді́же пострада́л єси́;","ра́дуйся, ти бо моли́лся єси́ ко Го́споду, да низпосле́ть Он, Милосе́рдий, на труд земледі́льця Своє́ благослове́ніє.","Ра́дуйся, страда́льче непобіди́мий і непреодолі́нний;","ра́дуйся, свяще́нниче Бо́жий, о всем ми́рі хода́тайствуяй.","Ра́дуйся, наде́ждо всіх моля́щихся тебі́;","ра́дуйся, земледі́льцев ра́дость сві́тлая.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О преди́вний Харала́мпіє, засту́пниче наш премилосе́рдий! Воньми́ гла́су недосто́йния моли́тви на́шея і моли́ся за ни ко Го́споду, є́же сохрани́ти нас от гла́да і мо́ра і междоусо́бния бра́ні, і на всяк ми́рний труд челове́ч низпосла́ти Бо́жиє благослове́ніє, да во ві́ки воспіва́єм Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели на Небесі́ ра́довахуся непоро́чному житію́ твоєму́, священному́чениче Харала́мпіє, ти бо послі́довал єси́ святи́м проро́ком і апо́столом, наставля́я лю́ди на путь спасе́нія. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, вели́кий світи́льниче Це́ркве;","ра́дуйся, пропові́дниче пра́вди.","Ра́дуйся, слове́с жи́зні ві́чния учи́телю;","ра́дуйся, ідолослуже́нія обличи́телю.","Ра́дуйся, і́мже сатана́ посрамля́ється;","ра́дуйся, і́мже ві́ра Христо́ва прославля́ється.","Ра́дуйся, я́ко і́менем Христо́вим вра́жию си́лу низложи́л єси́;","ра́дуйся, я́ко си́лою Бо́жиєю ко́зні бісо́вськия разруши́л єси́.","Ра́дуйся, Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нному страстоте́рпцю і уго́днику Бо́жию, ороси́вшему зе́млю честно́ю своє́ю кро́вію і плодоро́діє землі́ от Бо́га іспроси́вшему, похва́льная із глубини́ душі́ возглаша́єм пі́нія. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, священному́чениче Харала́мпіє, милосе́рдий наш пред Бо́гом засту́пниче і преди́вний чудотво́рче."]},{"h":"Молитва перша","ps":["О свяще́нная і многострада́льная главо́, па́стирю до́брий слове́сних ове́ць Христо́вих, священному́чениче Христо́в Харала́мпіє, Магнисі́йськая похвало́ і сла́во вселе́нния, всеми́рний світи́льниче і вели́кий наш засту́пниче і помо́щниче в ско́рбіх, біда́х і вся́ких ну́ждах! Усли́ши нас грі́шних, к тебі́ прибіга́ющих і моля́щихся, і ізба́ви нас от вся́каго зла́го обстоя́нія. Ти бо прия́л єси́ от Го́спода благода́ть і си́лу вели́ку за мно́гія і ну́жния страда́нія твоя́ і терпі́ніє, є́же всю́ду і во всем нам помога́ти, і найпа́че іді́же па́м'ять твоя́ почита́єма бу́деть бді́нієм, пі́нієм і усе́рдним моле́нієм. Сицева́я благода́ть даде́ся ті, священному́чениче Христо́в, от я́вльшагося ті Го́спода Царя́ сла́ви по твоєму́ іспрошенію. Єгда́ на ме́чноє тя усіче́ніє осуди́ша, усли́шал єси́ превожделі́нний і сладча́йший о́ний глас, глаго́лющий тебі́: Прийди́, Харала́мпіє, дру́же Мой, мно́гія муки́ і́мене ра́ди Моєго́ претерпі́вий, і проси́ у Мене́, є́же хо́щеши, і Аз дам ті. Ти же, вели́кий світи́льниче, рекл єси́ Христу́ Го́споду усти́ свої́ми: Го́споди мой, вели́ко у́бо мні єсть от Тебе́, Сві́та невече́рняго, дарова́ніє сіє́. А́ще уго́дно єсть вели́честву Твоєму́, молю́ Тя, благоволи́ дарова́ти мі сицеву́ю ми́лость Свою́: да іді́же положени́ бу́дуть мо́щі моя́ і почита́єма бу́деть па́м'ять страда́нія моєго́, не бу́деть на мі́сті том ні гла́да, ні мо́ра, іли́ тлетво́рнаго возду́ха, погубляющего плоди́, но да бу́деть па́че на мі́сті о́ном мир, здра́віє тілесе́м і душа́м спасе́ніє, ізоби́ліє пшени́ци, вина́, і єле́я і умноже́ніє ското́в, я́же на потре́бу челові́ком. Ти же па́ки, уго́дниче Христо́в Харала́мпіє многострадальниче, глас Го́споден усли́шал єси́, вещающий тебі́: Бу́ди по проше́нію твоєму́, пресла́вний Мой во́їне. І а́біє по глаго́ланії сем Госпо́днем пре́дал єси́ ду́шу свою́ без ме́чнаго посіче́нія, і по́йде во слід Христа́ Го́спода со сла́вою мно́гою, А́нгелом у́бо сретающим і провождающим ю до Престо́ла Госпо́дня с ра́достію вели́кою. І та́ко прия́л єси́ віне́ць сла́ви от Боже́ственния руки́ Єго́ с ли́ки святи́х, ві́чно сла́в'ящих пресвято́є і́м'я Го́спода. І та́мо, во сла́ві небе́сній пребива́я, при́зри, уго́дниче Бо́жий, і на нас грі́шних, моля́щихся тебі́, і воспом'яни́ нас пред Го́сподем, є́же дарова́ти нам на потре́бу ве́лія Єго́ ми́лості в безконе́чния ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О пречу́дний священному́чениче Харала́мпіє, страстоте́рпче непреодолі́нний, свяще́нниче Бо́жий, о всем ми́рі хода́тайствуяй! При́зри на моле́ніє нас, почита́ющих святу́ю па́м'ять твою́. Іспроси́ нам у Го́спода Бо́га проще́ніє гріхо́в на́ших, да не до конця́ прогні́вається на нас Госпо́дь: согріши́хом бо і недосто́йни яви́хомся милосе́рдія Бо́жия. Моли́ о нас Го́спода Бо́га, да низпосле́ть мир на гра́ди і ве́сі на́ша, да ізба́вить нас от наше́ствія іноплеме́нников, междуусо́бния бра́ні і вся́ких раздо́ров і нестроє́ній! Утверди́, священному́чениче, ві́ру і благоче́стіє во всіх ча́діх правосла́вния христия́нськия Це́ркве, і да ізба́вить нас Госпо́дь Бог от єресе́й, раско́лов і вся́каго суєві́рія. О милосе́рдний му́чениче! Моли́ся за ни ко Го́споду, да сохрани́ть нас от гла́да і вся́ких болі́зней, і да пода́сть нам ізоби́ліє плодо́в земни́х, ското́в умноже́ніє на потре́бу челові́ком і вся нам поле́зная: найпа́че же да сподо́бимся, моли́твами твої́ми, Небе́снаго Ца́рствія Христа́ Бо́га на́шего, Єму́же честь і поклоне́ніє подоба́єть, со Безнача́льним єго́ Отце́м і Пресвяти́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, свяще́ннійшая главо́, па́стирю до́брий слове́сних ове́ць Христо́вих, священному́чениче Христо́в Харала́мпіє, вели́кий о нас засту́пниче в ско́рбіх і біда́х і во всіх ну́ждах! Усли́ши нас, грі́шних і недосто́йних раб твої́х, моля́щихся тебі́, да твої́ми всеси́льними моли́твами Всеблаги́й Госпо́дь ізба́вить ни от вся́каго зла́го обстоя́нія, прости́ть вся согріше́нія, во́льная і нево́льная, сподо́бит ни про́чая лі́та жи́зні на́шея сконча́ти в соблюде́нії за́повідей Єго́ і покая́нії. Іспроси́, уго́дниче Бо́жий, да пребу́деть благослове́ніє Царя́ Небе́снаго над благослове́нною їм Россією. Ти бо прия́л єси́ єще́ в житії́ своє́м от Го́спода си́лу всім притекающим к тебі́ с мольбо́ю подава́ти потре́бноє, ті́мже і ста́рці, і возрастнії, і ді́ти прийма́ху ісціле́нія ра́ди хода́тайства твоєго́, уго́дниче, пред Престо́лом Го́спода. Єгда́ же на ме́чноє тя усіче́ніє осуди́ша, сли́шал єси́ превожделі́нний і сладча́йший глас Го́спода, глаго́лющ к тебі́ сицева́я: прийди́, Харала́мпіє, дру́же мой, мно́гая ра́ди І́мене Моєго́ претерпі́вий, проси́ у Мене́, чесо́ хо́щеши, і дам ті. Ти же, вели́кий світи́льниче, рекл єси́ Єму́ усти́ свої́ми: Го́споди, а́ще уго́дно Тебе́ єсть, молю́ Тя, даждь сла́ву І́мені Твоєму́, іді́же положени́ бу́дуть моя́ мо́щі і па́м'ять моя́ і́мать почитатися, да не бу́деть на мі́сті том глад і мор іли́ тлетво́рний возду́х, погубляющ плоди́, но да бу́деть па́че на мі́стіх тіх мир, тілесе́м здра́віє і душа́м спасе́ніє, ізоби́ліє же пшени́ци і вина́ і ското́в умноже́ніє на потре́бу челові́ком. І та́ко по проше́нію твоєму́ прия́л єси́ от Го́спода ве́лію благода́ть. На твоя́ моле́нія, на тя, священному́чениче Христо́в Харала́мпіє, упова́єм, получи́ти ве́лію ми́лость от Го́спода в безконе́чний вік. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко столп ізбра́нний Це́ркве Христо́вой / і світи́льник присносве́тлий всея́ вселе́нния, / прему́дре показа́ся, Харала́мпіє, / возсія́ в ми́рі муче́нієм, / разруши́ і́дольськоє мракобе́сіє, блаже́нне, / сего́ ра́ди яви́ся предста́тель Христу́, // моли́ся спасти́ся нам."]},{"h":"Кондак, глас 8","ps":["Подо́бствовав благода́тію свяще́нства, сла́вне, / Це́рков сві́тло укра́сил єси́ Боже́ственним страда́нієм, / є́же за Христа́ прия́л єси́ до́блественно, ра́дуяся, Харала́мпіє, / честни́й світи́льниче всеми́рний, осіява́яй конці́, // я́ко непобіди́мий."]},{"h":"Величання","ps":["Велича́єм тя, / священному́чениче Харала́мпіє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст священномученику Серафиму (Чичагову), митрополиту Петроградському","e":"Akathist to the Hieromartyr Seraphim (Chichagov), Metropolitan of Petrograd","secs":[{"h":"Кондак 1","ps":["Ізбра́нний архієре́ю і до́брий во́їне Христо́в, / святи́телю о́тче Серафи́ме, / воспису́єм ті похва́льная пі́нія, / ти бо, всім се́рдцем Бо́га возлюби́в, / ві́рен Єму́ да́же до сме́рти преби́л єси́ / і віне́ць Небе́сния сла́ви прия́л єси́. / Ті́мже, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, / моли́ Це́ркві Росси́йстій непоколеби́мій преби́ти / і синово́м земна́го оте́чества твоєго́ спасти́ся, / да с любо́вію зове́м ті:","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Ікос 1","ps":["А́нгельському служе́нію подража́я, богому́дре святи́телю Серафи́ме, ревни́тель Правосла́вния ві́ри яви́лся єси́ і, ду́шу пла́менную імі́я, мно́гим лю́дем ізря́дний наста́вник бил єси́. Ми же, благодаря́ще Бо́га, дарова́вшаго нам такова́го архипа́стиря сла́вна, воспіва́єм ті сицева́я:","Ра́дуйся, сла́внаго ро́да до́броє прозябе́ніє;","ра́дуйся, світи́льниче ві́ри негаси́мий.","Ра́дуйся, ізді́тська Бо́га возлюби́вий;","ра́дуйся, в Нем єди́нім наде́жду полага́вий.","Ра́дуйся, оте́чества на́шего кра́сний пло́де;","ра́дуйся, моли́твенниче ко Го́споду усе́рдний.","Ра́дуйся, любо́вію к Бо́гу і лю́дем преіспо́лненний;","ра́дуйся, наро́ду Бо́лгарському ра́тним по́двигом послужи́вий.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 2","ps":["Ви́дя себі́ отроча́ мла́до і си́ра су́ща, Серафи́ме всесла́вне, Отцю́ си́рих ско́рби серде́чния прине́сл єси́ ї, Того́ покро́вом покрива́єм, в моли́твах і уче́нії усе́рдіє ве́ліє яви́л єси́. Ми же, прославля́юще Отця́ Небе́снаго, ні єди́наго си́ра оставля́ющаго, воспіва́єм с тобо́ю Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум почита́ющих тя, святи́телю, недоуміва́єть, коль мно́гія тала́нти дарова́ ті Госпо́дь, я́же ти, я́ко ві́рний раб Христо́в, умно́жил єси́ сія́ во сла́ву Це́ркве. Сего́ ра́ди Госпо́дь, ви́дя ві́рность твою́ в ма́лом, над мно́гими тя поста́ви, ми же с любо́вію взива́єм ті си́це:","Ра́дуйся, в і́стинах христия́нських ізмла́да наста́вленний;","ра́дуйся, от ю́ности Го́спода всім се́рдцем возлюби́вий.","Ра́дуйся, во іспита́ніїх мно́гих Бо́гом ди́вно храни́мий;","ра́дуйся, по́двиги му́жества, я́ко до́брий во́їн, во бра́ні яви́вий.","Ра́дуйся, зако́ни Бо́жія в творе́нії Єго́ уразумі́вий;","ра́дуйся, лю́дем боля́щим і неду́жним сострада́вий.","Ра́дуйся, ціле́бними древеси́ врачева́ніє лю́дем подава́вий;","ра́дуйся, святи́м враче́м-безсре́бреником уподо́бивийся.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго направля́єм, в чи́ні ієре́йстім Бо́гу послужи́ти возжелі́л єси́, святи́телю о́тче Серафи́ме, і, благослове́нієм пра́ведника Кроншта́дтськаго укріпля́єм, вся кра́сная ми́ра сего́, я́ко уме́ти, вміни́л єси́ і, на служе́ніє па́стирськоє ре́вностне устреми́вся, добр плод сотвори́л єси́, поя́ во умиле́нії се́рдця Зижди́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я тща́ніє о Це́ркві Христо́вой, святи́й пра́ведний Іоа́нн пред кончи́ною своє́ю благослови́ тя іко́ною свято́ю і завіща́ ті, я́ко ча́ду своєму́ духо́вному, ра́товати о Правосла́вії. Ми же, восхваля́юще усе́рдіє твоє́ в ісполне́нії во́лі Бо́жієй, со благогові́нієм вопіє́м ті:","Ра́дуйся, послуша́нія па́стирю Кроншта́дтському до́брий рачи́телю;","ра́дуйся, заві́тов єго́ ві́рний ісполни́телю.","Ра́дуйся, отця́ твоєго́ духо́внаго от поноше́нія защити́вий;","ра́дуйся, ві́рних к єдиноми́слію призива́вий.","Ра́дуйся, па́стви твоєя́ богому́дрий окорми́телю;","ра́дуйся, уста́вов церко́вних при́сний блюсти́телю.","Ра́дуйся, чистоти́ Правосла́вния ві́ри пропові́дниче;","ра́дуйся, Преда́нія оте́чеськаго благогові́йний храни́телю.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смути́ тя, святи́телю, єгда́ блаже́нная ста́риця Параске́ва откри́ тебі́ повелі́ніє преподо́бнаго Серафи́ма, є́же возвісти́ти Імпера́тору Россі́йському о откри́тії святи́х моще́й єго́. Ти же, послі́дуя зо́ву сему́, ле́топись оби́телі Диве́євськия соста́вил єси́ і в прославле́нії подви́жника Саро́вськаго усе́рдно потруди́лся єси́, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше ві́рнії лю́діє благода́тния труди́ твоя́, прославле́нія ра́ди Саро́вськаго подви́жника под'я́тия, святи́телю Серафи́ме, просла́виша Бо́га, дарова́вшаго ті му́дрость і ра́зум. Сего́ ра́ди і ми, по́двиги твоя́ помина́юще, гла́сом хвале́нія вопіє́м ті:","Ра́дуйся, преподо́бнаго Серафи́ма пла́менно возлюби́вий;","ра́дуйся, усе́рдними труди́ твої́ми того́ просла́вивий.","Ра́дуйся, благода́тнаго посіще́нія єго́ удосто́єнний;","ра́дуйся, обітова́нієм ста́рця, вку́пі при́сно пребива́ти, обра́дованний.","Ра́дуйся, святи́ми єго́ моли́твами укрепле́нний;","ра́дуйся, сві́том любве́ єго́ ди́вно просвіще́нний.","Ра́дуйся, я́ко се́рдце твоє́ скрижа́льми Ду́ха Бо́жия соді́лал єси́;","ра́дуйся, я́ко ду́ші ві́рних Боже́ственним ра́зумом озари́л єси́.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 5","ps":["Я́ко боготе́чная звізда́, просія́л єси́, досточу́дне, єгда́ жезл архієре́йський вручи́ ті Госпо́дь і поручи́ смотре́нію твоєму́ па́ству мно́гих градо́в і ве́сей Россі́йських. Ти же, ду́шу за лю́ди полага́я, премно́гия доброді́телі яви́л єси́ і, чистоту́ Правосла́вія огражда́я, благоче́стіє христия́нськоє насажда́л єси́, призива́я пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя оскуді́ніє ві́ри в наро́ді на́шем, я́ко страж неуси́пний Це́ркве Христо́ви яви́лся єси́, богому́дре, і, заві́ту преподо́бнаго Серафи́ма о стяжа́нії Ду́ха Свята́го послі́дуя, призива́л єси́ ві́рния лю́ди правосла́вную ві́ру і́стинним благоче́стієм укріпля́ти. Ми же, о сем ра́дующеся, глаго́лем ті сицева́я:","Ра́дуйся, па́стви твоєя́ прему́дрий управи́телю;","ра́дуйся, хра́мов і оби́телей Бо́жиїх до́брий украси́телю.","Ра́дуйся, в служе́нії святи́тельстім ре́вность показа́вий;","ра́дуйся, к церко́вним та́їнствам благогові́йно приступа́ти призива́вий.","Ра́дуйся, к дія́нію богоми́сліє приложи́вий;","ра́дуйся, моли́тву в основа́ніє доброді́телей полага́ти науча́вий.","Ра́дуйся, смире́нієм твої́м мно́гія доброді́телі стяжа́вий;","ра́дуйся, ко спасе́нію путь ві́рним показа́вий.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 6","ps":["Пропові́дуя сло́во і́стини, призива́л єси́, святи́телю Серафи́ме, па́стирі вку́пі с миря́нами возрожда́ти жизнь церко́вную, да усе́рдієм їх не уга́снеть ві́ра Правосла́вная, пра́вда же Бо́жия да вразуми́ть лю́ди россі́йськия воспіва́ти хвале́бную піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ благода́ть, святи́телю о́тче Серафи́ме, в житії́ твоє́м, ти бо, труди́ к трудо́м прилага́я і тща́ніє неуси́пноє о ча́діх церко́вних імі́я, і́стинний па́стир Христо́во в землі́ Росси́йстій яви́лся єси́. Сего́ ра́ди воспіва́єм тя си́це:","Ра́дуйся, па́стирськаго служе́нія до́брий рачи́телю;","ра́дуйся, прему́дрости Бо́жієй ди́вний стяжа́телю.","Ра́дуйся, мно́гими дарова́нії от Го́спода украше́нний;","ра́дуйся, і́стинния ві́ри усе́рдний пропові́дниче.","Ра́дуйся, єресе́й і душевре́дних уче́ній обличи́телю;","ра́дуйся, ю́ним от собла́знов ми́ра ві́рноє огражде́ніє і защище́ніє.","Ра́дуйся, во благостоя́нії Це́ркве спасе́ніє Россі́ї ви́дівий;","ра́дуйся, до конця́ дній твої́х Оте́честву на́шему ві́рно послужи́вий.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 7","ps":["Хотя́й в Правосла́вії страну́ Россі́йськую утверди́ти і от губи́тельства враг ви́димих і неви́димих огради́ти, болі́зновал єси́ се́рдцем о Оте́честві твоє́м, святи́телю Серафи́ме, і, Го́споду предстоя́, усе́рдно моли́л єси́ о спасе́нії ста́да Христо́ва, вопія́ к Нему́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго Серафи́ма яви́ тя Госпо́дь, єгда́ на Оте́чество на́ше приї́де тьма безбо́жия. Ти же, святи́телю, тезоіме́нному ста́рцю подража́я, прилі́жно моли́л єси́ Пресвяту́ю Богоро́дицю, я́ко Засту́пницю Усе́рдную, да отве́рзеть две́рі милосе́рдія Своєго́ і укріпи́ть лю́ди россі́йськия во ві́рі Правосла́вній. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, і́скренней любо́вію к Бо́жієй Ма́тері іспо́лненний;","ра́дуйся, ми́лостію Єя́ к землі́ Росси́йстій уті́шенний.","Ра́дуйся, я́ко Засту́пницю Оте́чества і Сті́ну Неруши́мую Ю благовести́вий;","ра́дуйся, моли́твою к Ней па́ству укріпи́вий.","Ра́дуйся, усе́рдний і те́плий пред Не́ю моли́твенниче;","ра́дуйся, Гербове́цькия Єя́ іко́ни сугу́бий почита́телю.","Ра́дуйся, Покро́в Пресвяти́я Богоро́диці над оби́телію Диве́євською просла́вивий;","ра́дуйся, мно́гая чудеса́ благода́тная, от Нея́ бива́ємая, списа́вий.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 8","ps":["Сла́вноє явле́ніє си́ли Бо́жієй ви́дим на тебі́, святи́телю Христо́в Серафи́ме, єгда́ кресто́м вооружи́вся, сло́вом благода́тним лю́ди правосла́вния от неві́рія огражда́л єси́, заблу́ждшия же і совраще́нния вразумля́л єси́, неуста́нно взива́я к Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бисть, я́ко серафи́м о́гненний, всеблаже́нне о́тче, неуси́пно пеки́йся о слове́снім ста́ді твоє́м. Ті́мже тя, я́ко па́стиря до́браго, пі́сньми похва́льними воспіва́єм та́ко:","Ра́дуйся, Це́ркве Правосла́вния тве́рдоє укріпле́ніє;","ра́дуйся, єресе́й і раско́лов небоя́зненноє посрамле́ніє.","Ра́дуйся, стра́ждущим і в біді́ су́щим ско́рий помо́щниче;","ра́дуйся, душ немощни́х ди́вний ціли́телю.","Ра́дуйся, отпа́вших от Правосла́вія кро́ткий вразуми́телю;","ра́дуйся, см'яте́нних і озло́бленних му́дрий наказа́телю.","Ра́дуйся, заблу́ждшия к покая́нію приводи́вий;","ра́дуйся, любо́вію твоє́ю сердца́ хла́дная согрева́вий.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє восскорбе́, єгда́ наро́д землі́ на́шея хла́дностію ві́ри от Бо́га отступи́. Ти же небоя́зненний защи́титель Правосла́вія яви́лся єси́, угото́вав себі́ к му́ченичеському страда́нію. Тім, тя ублажа́юще, со благогові́нієм вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствующий язи́к оскудіва́єть пред мно́жеством дарова́ній, от Бо́га ті да́нних, досточу́дне о́тче, я́же му́дре употреби́в, я́ко многопло́дная ма́слина яви́лся єси́. Ми же, а́ще і неіску́сни єсьми́, оба́че ча́да твоя́ су́ще, восхваля́єм тя си́це:","Ра́дуйся, сло́ва Бо́жия ре́вностний пропові́дниче;","ра́дуйся, па́стирей і наро́да церко́внаго усе́рдний учи́телю.","Ра́дуйся, оте́чества на́шего му́жественний во́їне;","ра́дуйся, по́двигов ра́тних по́мощію Бо́жієй до́блестний соверши́телю.","Ра́дуйся, душ і тіле́с любвеоби́льний врачева́телю;","ра́дуйся, святи́х образо́в іску́сний живописа́телю.","Ра́дуйся, пі́сней церко́вних му́дрий сочини́телю;","ра́дуйся, дія́ній уго́дников Бо́жиїх благогові́йний состави́телю.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й лю́ди Россі́йськия, поста́ви тя Христо́с, о́тче Серафи́ме, па́стиря ві́рна слове́сних ове́ць, да не расточа́ться в годи́ну безбо́жия. Ти же, зо́ву Бо́жию послі́дуя і благослове́нієм пра́веднаго Іоа́нна Кроншта́дтськаго наставля́єм, Правосла́віє ре́вностно защища́л єси́ і призива́л єси́ лю́ди в братолю́бії пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́на заступле́нія бисть ті Богоро́диця Ді́ва, о́тче чадолюби́вий, єгда́ терпі́л єси́ гоне́нія і у́зи темни́чния. Це́рков же, в біда́х су́щую, і чад єя́ ві́рних моли́твами твої́ми і забо́тою па́стирською укріпля́л єси́. Сего́ ра́ди мир правосла́вний сла́вить тя си́це:","Ра́дуйся, святі́йшаго Патріа́рха Ти́хона ві́рний послу́шниче;","ра́дуйся, священному́ченика Петра́ во іспові́данії ві́ри подража́телю.","Ра́дуйся, митрополи́та Се́ргия і́скренній сподви́жниче;","ра́дуйся, алтаря́ Госпо́дня досто́йний служи́телю.","Ра́дуйся, всего́ себе́ в же́ртву Го́сподеві преда́вий;","ра́дуйся, гоне́нія мно́гая претерпі́вий.","Ра́дуйся, поруга́нія в заточе́нії кро́тко приє́мий;","ра́дуйся, правосла́вную ві́ру да́же до сме́рти сохрани́вий.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє ко Пресвяті́й Тро́йце прине́сл єси́ се́рдцем і житіє́м твої́м, святи́телю Серафи́ме, найпа́че же кончи́ною му́ченичеською, просла́вльшей Бо́га; сего́ ра́ди преше́л єси́ во оби́телі небе́сния, іді́же со А́нгельськими ли́ки поє́ши Трийпоста́сному Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ Христо́в просвіти́ тя от младе́нства, святи́телю Серафи́ме, сего́ ра́ди, я́ко світи́льник, возсія́л єси́ лю́дем мно́гими доброді́тельми. Ми же, пребива́юще во мра́ці гріхо́в і скорбе́й на́ших, назида́ємся чу́дним житіє́м твої́м і со упова́нієм прославля́єм тя си́це:","Ра́дуйся, я́ко ві́рний раб, Христу́ послі́довавий;","ра́дуйся, о́браз житія́ доброді́тельнаго і кончи́ни му́ченичеськия яви́вий.","Ра́дуйся, ві́рою несумні́нною враго́в посрами́вий;","ра́дуйся, в муче́ніях, я́ко зла́то в горни́лі, очище́нний.","Ра́дуйся, я́ко в не́мощі твоє́й си́лу Бо́жию яви́л єси́;","ра́дуйся, я́ко смире́нієм ко́зні дия́вольськия посрами́л єси́.","Ра́дуйся, блаже́нную сла́ву от Бо́га стяжа́вий;","ра́дуйся, нетлі́нним вінце́м с новому́ченики увінча́нний.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 12","ps":["Благода́тію Ду́ха Свята́го тече́ніє жи́зні соверши́л єси́ і ві́ру соблю́л єси́ невреди́мо, святи́телю Христо́в Серафи́ме. Сего́ ра́ди прия́л єси́ віне́ць пра́вди, угото́ванний тебі́ от Подвигополо́жника Христа́, Єму́же, в ра́дості предстоя́ с новому́ченики і іспові́дники Россі́йськими, вопіє́ши: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще піснь хвали́ Человіколю́бцю Бо́гу, ди́вному во святи́х Свої́х, прославля́єм тя, о́тче Серафи́ме, я́ко сокро́вище благода́тних даро́в Ду́ха Свята́го яви́лся єси́. Сего́ ра́ди во умиле́нії се́рдця взива́єм ті си́це:","Ра́дуйся, во оби́телі небе́сния водвори́вийся;","ра́дуйся, Пресвяту́ю Тро́йцю при́сно велича́ющий.","Ра́дуйся, в ри́зах бі́лих А́гнцю Бо́жию предстоя́щий;","ра́дуйся, оби́лієм весе́лія духо́внаго преіспо́лненний.","Ра́дуйся, в ли́ці святи́телей Христо́вих велича́ємий;","ра́дуйся, в со́нмі новому́ченик россі́йських прославля́ємий.","Ра́дуйся, о нас пред Го́сподем непости́дний хода́таю;","ра́дуйся, моли́тв с ві́рою к тебі́ прибіга́ющих ско́рий ісполни́телю.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 13","ps":["О, священному́чениче Серафи́ме, всероссі́йський світи́льниче і во́їне Христо́в добропобі́дний, вінце́м му́ченичества от Го́спода увінча́нний! Не забу́ди ста́до твоє́ і умоли́ Влади́ку Христа́ в любві́ к Правосла́вію нам утверди́тися, во ві́рі укріпи́тися і ві́чния ізба́витися му́ки, да с тобо́ю воспіва́єм Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельському служе́нію подража́я, богому́дре святи́телю Серафи́ме, ревни́тель Правосла́вния ві́ри яви́лся єси́ і, ду́шу пла́менную імі́я, мно́гим лю́дем ізря́дний наста́вник бил єси́. Ми же, благодаря́ще Бо́га, дарова́вшаго нам такова́го архипа́стиря сла́вна, воспіва́єм ті сицева́я:","Ра́дуйся, сла́внаго ро́да до́броє прозябе́ніє;","ра́дуйся, світи́льниче ві́ри негаси́мий.","Ра́дуйся, ізді́тська Бо́га возлюби́вий;","ра́дуйся, в Нем єди́нім наде́жду полага́вий.","Ра́дуйся, оте́чества на́шего кра́сний пло́де;","ра́дуйся, моли́твенниче ко Го́споду усе́рдний.","Ра́дуйся, любо́вію к Бо́гу і лю́дем преіспо́лненний;","ра́дуйся, наро́ду Бо́лгарському ра́тним по́двигом послужи́вий.","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Кондак 1","ps":["Ізбра́нний архієре́ю і до́брий во́їне Христо́в, / святи́телю о́тче Серафи́ме, / воспису́єм ті похва́льная пі́нія, / ти бо, всім се́рдцем Бо́га возлюби́в, / ві́рен Єму́ да́же до сме́рти преби́л єси́ / і віне́ць Небе́сния сла́ви прия́л єси́. / Ті́мже, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, / моли́ Це́ркві Росси́йстій непоколеби́мій преби́ти / і синово́м земна́го оте́чества твоєго́ спасти́ся, / да с любо́вію зове́м ті:","Ра́дуйся, священному́чениче Серафи́ме, ві́ри Правосла́вния пла́менний побо́рниче."]},{"h":"Молитва","ps":["О, вели́кий і пречу́дний уго́дниче Христо́в, священному́чениче Серафи́ме!","Прийми́ ни́ні на́шу смире́нную піснь благодаре́нія і умоли́ Вседержи́теля Бо́га в Неразді́льній Тро́йці прославля́ємаго низпосла́ти нам мир і благоде́нствіє, да сохрани́ться от разоре́нія держа́ва на́ша. Любо́вію і му́дростію твоє́ю лю́ди росси́йстії к єдине́нію собо́рному приведи́ і от єресе́й і раско́лов огради́. Си́лою хода́тайства твоєго́ терпі́ніє в ско́рбіх і болі́зніх нам низпосли́.","О, всехва́льний святи́телю Христо́в! Іспроси́ у Всеми́лостиваго Бо́га пода́ти нам пре́жде конця́ покая́ніє, да сподо́бимся с тобо́ю зрі́ти лиця́ Єго́ добро́ту неізрече́нную, воспіва́юще Отця́ і Си́на і Свята́го Ду́ха во ві́ки. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Во́їнство Царя́ Небе́снаго / па́че земна́го возлюби́в, / служи́тель пла́менний Святи́я Тро́йці яви́лся єси́. / Наставле́нія Кроншта́дтськаго па́стиря / в се́рдці своє́м слага́я, / да́нная ті от Бо́га многообра́зная дарова́нія / к по́льзі наро́да Бо́жия преумно́жил єси́. / Учи́тель благоче́стія / і побо́рник єди́нства церко́вного бив, / пострада́ти да́же до кро́ве сподо́бился єси́. / Священному́чениче Серафи́ме, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 6","ps":["Саро́вському чудотво́рцю тезоімени́ть бив, / те́плую любо́в к нему́ імі́л єси́, / писа́ньми свої́ми по́двиги і чудеса́ того́ ми́ру возвісти́в, / ві́рния к єго́ прославле́нію подви́гл єси́ / і благода́рственнаго посіще́нія / самаго́ Преподо́бнаго сподо́бился єси́. / С ни́мже ни́ні, священному́чениче Серафи́ме, / в Небе́сних черто́зіх водворя́яся, / моли́ Христа́ Бо́га // серафи́мськия ра́дости нам прича́стником би́ти."]},{"h":"Величання","ps":["Велича́єм тя, / священному́чениче Серафи́ме, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши за нас // Христа́ Бо́га на́шего."]}],"notes":[]}];
export default D;
